// Content for Not Fair, Not Funny (node g11, ages 6–9, Chapter 2) — NEW v2 build to GDD 11 (mechanic-
// embodying), the gender-teasing & ally game in the Gender & Respect thread. "A joke shouldn't hurt." 84
// researched, India-aware scenarios across six categories, each encoded as one of the shared v2 play actions
// (branch / reflect / strike-rewrite / role-play / sort / build / spot / match) — no binary "tap the right
// card", led by teasing-moment DILEMMAS (branch ×24 — decide the kind/ally move, see the ripple, get a
// debrief), say-the-comeback / ally lines (role-play), and the ally-toolkit builder (build). Teaches: fun vs
// mean teasing, why "just a joke" doesn't erase harm (impact over intent), recognising & refusing gender
// put-downs ("like a girl", "boys don't cry", "so girly"), the concrete upstander moves (speak up,
// distract, support, tell, check in), and checking your own jokes. IMPACT OVER INTENT (how a joke lands, not
// whether it was 'meant'); DON'T VILLAINISE THE JOKER (Reyansh-type checks & repairs, never branded 'bad');
// PROTECT THE TARGET (the teased child is never at fault); SAFE ESCALATION (telling a trusted adult is
// reporting, not tattling — Childline 1098). Builds on g10 (Fair Play World); prereq g10. Rendered by the
// shared engine (components/games/v2-engine.tsx). gameId "not-funny" (the GDD/library "not-fair-not-funny"
// is design-doc only — config must use the engine-host registry id). DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // — Fun teasing vs mean teasing —
  {"id":"nf-001","cat":"fun-vs-mean","type":"sort","hook":"Lensy: some teasing is fun, some is mean. Sort these.","items":[{"id":"a","text":"You both laugh, it stops when asked"},{"id":"b","text":"It keeps going after you say stop"},{"id":"c","text":"A gentle joke you're both smiling at"},{"id":"d","text":"A jab meant to hurt"},{"id":"e","text":"A nickname you both giggle at"},{"id":"f","text":"The same dig, again, to wound"}],"bins":[{"id":"fun","label":"Fun teasing","valence":"pos"},{"id":"mean","label":"Mean teasing","valence":"neg"}],"key":{"a":"fun","b":"mean","c":"fun","d":"mean","e":"fun","f":"mean"},"relearn":"Fun teasing makes both laugh and stops when asked; mean teasing keeps going.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-002","cat":"fun-vs-mean","type":"branch","hook":"You make a joke and your friend stops smiling.","options":[{"text":"Check in: \"sorry, that wasn't kind, you okay?\"","consequence":"They feel respected; you repair it fast.","outcome":"kind","best":true},{"text":"Say \"can't you take a joke?\"","consequence":"They feel worse; the joke became a jab.","outcome":"unkind"}],"debrief":"If a joke stops being fun for the other person, it's stopped being a joke.","relearn":"If your joke hurts someone, checking in beats doubling down.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-003","cat":"fun-vs-mean","type":"reflect","hook":"Lensy: how do you tell fun teasing from mean teasing?","prompt":"Pick the best clue.","options":["Is everyone laughing?","Does it stop when asked?","Does it aim to hurt?"],"affirm":"All good clues, the big one is: does it hurt, and does it stop when asked?","relearn":"The test: is everyone okay, and does it stop when asked?","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-004","cat":"fun-vs-mean","type":"strike-rewrite","hook":"\"If I find it funny, it must be okay.\"","myth":{"un":"If I find it funny, it must be okay for everyone.","re":"A joke is only fun if it's fun for the person it's about, too.","why":"Funny-to-you can still hurt someone else."},"relearn":"A joke isn't fun if it hurts the person it's about.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-005","cat":"fun-vs-mean","type":"sort","hook":"Sort: a joke WITH someone, or AT someone?","items":[{"id":"a","text":"A silly inside joke you share"},{"id":"b","text":"Mocking someone's looks"},{"id":"c","text":"Laughing together at a funny film"},{"id":"d","text":"Making someone the punchline"},{"id":"e","text":"Both cracking up at a clumsy trip you took"},{"id":"f","text":"Laughing AT a kid who dropped his tiffin"}],"bins":[{"id":"with","label":"WITH (kind)","valence":"pos"},{"id":"at","label":"AT (unkind)","valence":"neg"}],"key":{"a":"with","b":"at","c":"with","d":"at","e":"with","f":"at"},"relearn":"Laughing WITH people is kind; laughing AT people isn't.","persona":"any","source":"humor"},
  {"id":"nf-006","cat":"fun-vs-mean","type":"reflect","hook":"Lensy: the best jokes leave everyone smiling. Agree?","prompt":"What do you think?","options":["Yes","Everyone laughs","No one's hurt"],"affirm":"The best humor includes everyone, no one's the target.","relearn":"Great jokes leave everyone, including the 'target', smiling.","persona":"any","source":"inclusive humor"},
  {"id":"nf-007","cat":"fun-vs-mean","type":"branch","hook":"Your friends are teasing you and it's actually fun, then it tips into mean.","options":[{"text":"Say \"okay, that part's not funny, let's stop\"","consequence":"Good friends ease off; the fun stays fun.","outcome":"assertive","best":true},{"text":"Pretend it's fine while it stings","consequence":"Naming the line helps friends respect it."}],"debrief":"You can enjoy the fun part and call the line when it's crossed.","relearn":"You can name when teasing tips from fun into mean.","persona":"any","source":"assertiveness"},
  {"id":"nf-008","cat":"fun-vs-mean","type":"sort","hook":"Sort: friendly teasing, or mean teasing?","items":[{"id":"a","text":"\"Ha, you tripped, you okay though?\""},{"id":"b","text":"Repeating 'loser' at someone to hurt"},{"id":"c","text":"A goofy nickname you both like"},{"id":"d","text":"Calling someone names till they cry"},{"id":"e","text":"A shared joke you're both in on"},{"id":"f","text":"A dig that won't stop after 'please stop'"}],"bins":[{"id":"friendly","label":"Friendly","valence":"pos"},{"id":"mean","label":"Mean","valence":"neg"}],"key":{"a":"friendly","b":"mean","c":"friendly","d":"mean","e":"friendly","f":"mean"},"relearn":"A name repeated to hurt is mean teasing, not fun.","persona":"any","source":"teasing vs bullying"},
  // — 'Just a joke' isn't a free pass —
  {"id":"nf-009","cat":"just-a-joke","type":"strike-rewrite","hook":"\"It's just a joke, so it doesn't count.\"","myth":{"un":"If you call it a joke, it can't really hurt.","re":"'Just a joke' doesn't erase the hurt; the harm is real.","why":"Calling it a joke is often a way to dodge the hurt caused."},"relearn":"'Just a joke' doesn't make a put-down okay.","persona":"Reyansh","source":"disparagement humor"},
  {"id":"nf-010","cat":"just-a-joke","type":"branch","hook":"A kid makes fun of another's accent, then says \"relax, just joking.\"","options":[{"text":"Say \"it's not funny if it hurts them\"","consequence":"You name the dodge; the teasing loses cover.","outcome":"ally","best":true},{"text":"Let 'just joking' settle it","consequence":"'Just joking' shouldn't be a free pass for hurt."}],"debrief":"'Just joking' isn't a magic pass that erases the hurt.","relearn":"You can call out a put-down even when it's labelled a 'joke'.","persona":"Ananya","source":"disparagement humor"},
  {"id":"nf-011","cat":"just-a-joke","type":"strike-rewrite","hook":"\"Jokes about a whole group are harmless fun.\"","myth":{"un":"Jokes that put down a whole group are harmless.","re":"Group put-down jokes spread unfair ideas about people.","why":"They make unkind beliefs feel normal and okay."},"relearn":"Jokes that put down a group quietly spread unfairness.","persona":"any","source":"disparagement humor"},
  {"id":"nf-012","cat":"just-a-joke","type":"sort","hook":"Sort: a joke that's fine, or one that puts a group down?","items":[{"id":"a","text":"A pun about vegetables"},{"id":"b","text":"\"Girls are bad at maths\" as a 'joke'"},{"id":"c","text":"A silly knock-knock joke"},{"id":"d","text":"A 'joke' that boys are dumb"},{"id":"e","text":"A funny riddle about the rain"},{"id":"f","text":"\"Kids from that town are slow\" as a 'joke'"}],"bins":[{"id":"fine","label":"Fine fun","valence":"pos"},{"id":"putdown","label":"Group put-down","valence":"neg"}],"key":{"a":"fine","b":"putdown","c":"fine","d":"putdown","e":"fine","f":"putdown"},"relearn":"Jokes that put a group down aren't the same as harmless fun.","persona":"any","source":"disparagement humor"},
  {"id":"nf-013","cat":"just-a-joke","type":"reflect","hook":"Lensy: who decides if a joke went too far, the teller or the person it's about?","prompt":"What do you think?","options":["The person it's about","Both, but their feelings count","Not just the teller"],"affirm":"The feelings of the person it's about matter most, not just the teller's intent.","relearn":"Whether a joke hurt is mostly about how the other person felt.","persona":"any","source":"impact over intent"},
  {"id":"nf-014","cat":"just-a-joke","type":"branch","hook":"You hear a 'joke' that puts down a group you belong to.","options":[{"text":"Say \"that's not really funny to me\"","consequence":"You stand up for yourself; some rethink it.","outcome":"assertive","best":true},{"text":"Force a laugh","consequence":"You can name that it doesn't feel funny to you."}],"debrief":"You're allowed to say a 'joke' about your group doesn't land.","relearn":"You can say a put-down joke about your group isn't funny.","persona":"Faizan-type","source":"self-advocacy"},
  {"id":"nf-015","cat":"just-a-joke","type":"strike-rewrite","hook":"\"If you don't laugh, you can't take a joke.\"","myth":{"un":"Not laughing means you can't take a joke.","re":"Not laughing at a put-down means you noticed it wasn't kind.","why":"'Can't take a joke' is used to silence people who are hurt."},"relearn":"You don't have to laugh at something unkind.","persona":"any","source":"disparagement humor"},
  {"id":"nf-016","cat":"just-a-joke","type":"role-play","hook":"Someone says \"can't you take a joke?\" after a mean dig.","setup":"Hold your ground. Say:","yourLine":[{"text":"\"I like jokes, just not ones that hurt people.\"","best":true},{"text":"\"Sorry, I'll laugh.\""}],"relearn":"You can love jokes and still refuse the mean ones.","persona":"Ananya","source":"assertiveness / voice"},
  {"id":"nf-017","cat":"just-a-joke","type":"reflect","hook":"Lensy: a joke can be clever AND kind. Want both?","prompt":"What do you think?","options":["Yes","Clever and kind","The best kind"],"affirm":"The cleverest jokes don't need a victim. Aim for those.","relearn":"The best humor is clever and kind, no victim needed.","persona":"any","source":"inclusive humor"},
  // — Gender teasing & put-downs —
  {"id":"nf-018","cat":"gender-teasing","type":"strike-rewrite","hook":"\"You throw like a girl!\" (said as an insult)","myth":{"un":"'Like a girl' is an insult.","re":"Girls throw, run and play brilliantly; 'like a girl' isn't a put-down.","why":"Using a gender as an insult puts down half the world."},"relearn":"'Like a girl' isn't an insult, girls are great at everything.","persona":"Ananya","source":"gender teasing"},
  {"id":"nf-019","cat":"gender-teasing","type":"branch","hook":"Kids tease a boy for crying: \"baby! boys don't cry!\"","options":[{"text":"Say \"everyone cries, that's not a put-down\"","consequence":"He's supported; the put-down loses power.","outcome":"ally","best":true},{"text":"Join in","consequence":"He feels ashamed of a normal feeling."}],"debrief":"Teasing a boy for crying punishes a normal, healthy feeling.","relearn":"Crying isn't 'unmanly'; teasing it isn't fair or funny.","persona":"Faizan-type","source":"gender teasing (links g01)"},
  {"id":"nf-020","cat":"gender-teasing","type":"strike-rewrite","hook":"\"That's so girly\" (said to shame a boy)","myth":{"un":"Calling something 'girly' is a way to shame a boy.","re":"Liking 'girly' things is fine; 'girly' isn't an insult.","why":"It only stings if we treat girls' things as lesser."},"relearn":"'Girly' isn't an insult; everyone can like anything.","persona":"Faizan-type","source":"gender teasing"},
  {"id":"nf-021","cat":"gender-teasing","type":"sort","hook":"Sort: a friendly thing to say on the team, or a gender put-down?","items":[{"id":"a","text":"\"Nice goal!\""},{"id":"b","text":"\"Pink? What are you, a girl?\""},{"id":"c","text":"\"Want to join our team?\""},{"id":"d","text":"\"You play like a girl, ha\""},{"id":"e","text":"\"Good pass, well done!\""},{"id":"f","text":"\"Boys don't cry, baby\""}],"bins":[{"id":"kind","label":"Friendly","valence":"pos"},{"id":"putdown","label":"Gender put-down","valence":"neg"}],"key":{"a":"kind","b":"putdown","c":"kind","d":"putdown","e":"kind","f":"putdown"},"relearn":"Using 'a girl' as an insult, or 'boys don't cry', is gender teasing.","persona":"Reyansh","source":"gender teasing"},
  {"id":"nf-022","cat":"gender-teasing","type":"role-play","hook":"A friend is teased: \"that game's for girls, why do YOU play it?\"","setup":"Back them up. Say:","yourLine":[{"text":"\"Games are for everyone, it's a great game.\"","best":true},{"text":"Laugh along"}],"relearn":"A calm comeback defends a friend and the truth.","persona":"Reyansh","source":"comebacks / voice"},
  {"id":"nf-023","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Boys who do ballet/cooking deserve teasing.\"","myth":{"un":"Boys who like 'girl' activities deserve teasing.","re":"Boys can love ballet, cooking, anything, no teasing earned.","why":"Interests aren't gendered; teasing them is unfair."},"relearn":"No one earns teasing for liking something 'not for their gender'.","persona":"Faizan-type","source":"gender norms"},
  {"id":"nf-024","cat":"gender-teasing","type":"branch","hook":"A girl is mocked for being 'bossy' when she leads.","options":[{"text":"Say \"she's a good leader, not bossy\"","consequence":"You reframe it; leadership isn't a girl flaw.","outcome":"ally","best":true},{"text":"Agree she's bossy","consequence":"'Bossy' is often just 'leading while a girl'."}],"debrief":"Girls get called 'bossy' for the leading boys get praised for.","relearn":"Leading isn't 'bossy'; don't tease girls for it.","persona":"Ananya","source":"gender teasing"},
  {"id":"nf-025","cat":"gender-teasing","type":"reflect","hook":"Lensy: using a gender as an insult, who does it hurt?","prompt":"What do you think?","options":["The kid teased","All of that gender","Lots of people"],"affirm":"It hurts the kid AND quietly puts down everyone of that gender.","relearn":"Gender insults hurt the person and a whole group at once.","persona":"any","source":"disparagement humor"},
  {"id":"nf-026","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Teasing about looks or skin is fine if it's funny.\"","myth":{"un":"Teasing someone's looks or skin colour is okay if it's 'funny'.","re":"Mocking looks or skin colour hurts; it's never just funny.","why":"It attacks something a person can't and shouldn't change."},"relearn":"Teasing looks or skin colour isn't funny; it's hurtful.","persona":"any","source":"appearance / colourism (links g06)"},
  {"id":"nf-027","cat":"gender-teasing","type":"sort","hook":"Sort: a kind comment, or a gender/looks put-down?","items":[{"id":"a","text":"\"Cool haircut!\""},{"id":"b","text":"\"You're too dark to be pretty\""},{"id":"c","text":"\"Great catch!\""},{"id":"d","text":"\"You run like a girl, ha\""},{"id":"e","text":"\"That's a smart idea!\""},{"id":"f","text":"\"Boys shouldn't like that\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"putdown","label":"Put-down","valence":"neg"}],"key":{"a":"kind","b":"putdown","c":"kind","d":"putdown","e":"kind","f":"putdown"},"relearn":"Spot put-downs about gender, looks and skin, they're not jokes.","persona":"any","source":"appearance / gender teasing"},
  {"id":"nf-028","cat":"gender-teasing","type":"role-play","hook":"Someone teases a friend's dark skin as a 'joke'.","setup":"Stand up, kindly. Say:","yourLine":[{"text":"\"Every skin colour is great, that's not funny.\"","best":true},{"text":"Laugh"}],"relearn":"You can shut down a colourist 'joke' with a kind, clear line.","persona":"Ananya","source":"colourism / ally (links g06)"},
  // — How put-downs feel (impact over intent) —
  {"id":"nf-029","cat":"how-it-feels","type":"reflect","hook":"Lensy: think of a time a 'joke' was about you and stung.","prompt":"How did it feel?","options":["Bad","Embarrassing","Lonely"],"affirm":"That sting is real, and it's why we don't aim jokes at people.","relearn":"Put-down 'jokes' really sting; that feeling matters.","persona":"Faizan-type","source":"empathy"},
  {"id":"nf-030","cat":"how-it-feels","type":"branch","hook":"You realise a joke you made really hurt someone.","options":[{"text":"Apologise: \"I'm sorry, that was unkind\"","consequence":"They feel better; you grow as a friend.","outcome":"repair","best":true},{"text":"Defend it: \"I didn't mean it like that\"","consequence":"Intent matters less than the hurt; owning it helps."}],"debrief":"What you meant matters less than how it landed, own the impact.","relearn":"If a joke hurt, apologise for the impact, not just your intent.","persona":"Reyansh","source":"impact over intent / repair"},
  {"id":"nf-031","cat":"how-it-feels","type":"strike-rewrite","hook":"\"If I didn't mean to hurt, it doesn't count.\"","myth":{"un":"If I didn't mean to hurt, the hurt doesn't count.","re":"Hurt counts even when it wasn't meant; you can still make it right.","why":"Caring about impact is what kind people do."},"relearn":"Even unmeant hurt is real; you can still say sorry.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-032","cat":"how-it-feels","type":"reflect","hook":"Lensy: before a joke, ask 'how would this land for them?' Good habit?","prompt":"What do you think?","options":["Yes","A kind check","I'll try it"],"affirm":"A quick 'how would this land?' keeps your jokes kind.","relearn":"Checking how a joke might land is a kind habit.","persona":"any","source":"empathy / perspective-taking"},
  {"id":"nf-033","cat":"how-it-feels","type":"branch","hook":"A friend laughs off a mean joke but looks hurt underneath.","options":[{"text":"Check in later: \"that joke wasn't fair, you okay?\"","consequence":"They feel seen; laughing it off was a mask.","outcome":"kind","best":true},{"text":"Assume they're fine","consequence":"A brave laugh can hide real hurt; checking in helps."}],"debrief":"People often laugh to hide hurt, a quiet check-in means a lot.","relearn":"A laugh can hide hurt; check in on a friend after.","persona":"any","source":"empathy"},
  {"id":"nf-034","cat":"how-it-feels","type":"match","hook":"Match the put-down to the feeling it can cause.","pairs":[{"left":"Mocked for looks","right":"Ashamed"},{"left":"Left out by a 'joke'","right":"Lonely"},{"left":"Teased every single day","right":"Worn down"},{"left":"Laughed at in front of class","right":"Small"},{"left":"Name called again and again","right":"Like hiding"}],"relearn":"Put-downs cause real feelings: shame, loneliness, feeling small or worn down.","persona":"any","source":"empathy"},
  {"id":"nf-035","cat":"how-it-feels","type":"reflect","hook":"Lensy: kindness costs nothing and helps a lot. Worth choosing?","prompt":"What do you think?","options":["Yes","Always","Easy choice"],"affirm":"Choosing kind over a cheap laugh is a small, powerful habit.","relearn":"Choosing kindness over a put-down laugh is always worth it.","persona":"any","source":"values"},
  {"id":"nf-036","cat":"how-it-feels","type":"branch","hook":"Everyone's laughing at a 'joke' about a quiet kid who isn't there.","options":[{"text":"Say \"that's not fair on them\" and change the subject","consequence":"The pile-on stops; you protected someone absent.","outcome":"ally","best":true},{"text":"Add your own joke","consequence":"Talking someone down behind their back is still unkind."}],"debrief":"Put-downs behind someone's back are still put-downs.","relearn":"Standing up for someone who isn't there is real kindness.","persona":"Ananya","source":"empathy / bystander"},
  // — Being an ally (upstander moves) —
  {"id":"nf-037","cat":"be-an-ally","type":"branch","hook":"A friend is being teased about their gender right in front of you.","options":[{"text":"Speak up: \"that's not kind, stop\"","consequence":"Often the teasing stops fast when someone speaks up.","outcome":"upstander","best":true},{"text":"Look away","consequence":"Silence lets it continue; speaking up helps."}],"debrief":"When a peer steps in, teasing often stops within seconds.","relearn":"Speaking up, even two words, can stop teasing fast.","persona":"Faizan-type","source":"upstander research"},
  {"id":"nf-038","cat":"be-an-ally","type":"strike-rewrite","hook":"\"If it's not happening to me, it's not my problem.\"","myth":{"un":"Teasing someone else is none of my business.","re":"An ally who steps in can stop it; silence lets it grow.","why":"Bystanders set the tone, for better or worse."},"relearn":"Standing up for others is exactly your business.","persona":"Ananya","source":"bystander research"},
  {"id":"nf-039","cat":"be-an-ally","type":"role-play","hook":"You want to step in but it feels scary.","setup":"Try a short, calm line. Say:","yourLine":[{"text":"\"Hey, that's not cool.\"","best":true},{"text":"Nothing"}],"relearn":"You don't need a speech, a short \"that's not cool\" works.","persona":"any","source":"upstander / voice"},
  {"id":"nf-040","cat":"be-an-ally","type":"branch","hook":"It feels too risky to speak up to the teaser directly.","options":[{"text":"Distract, or go support the kid, or tell a trusted adult","consequence":"There's more than one way to be an ally.","outcome":"upstander","best":true},{"text":"Do nothing because you can't confront them","consequence":"Distracting, supporting and telling are ally moves too."}],"debrief":"Allies have options: distract, support, or tell an adult.","relearn":"You can ally without confronting.","persona":"quiet child","source":"upstander moves"},
  {"id":"nf-041","cat":"be-an-ally","type":"role-play","hook":"After someone was teased, you go find them.","setup":"Offer support. Say:","yourLine":[{"text":"\"That wasn't fair to you. Want to hang out?\"","best":true},{"text":"Pretend it didn't happen"}],"relearn":"Checking in after, and including them, is powerful allyship.","persona":"any","source":"upstander / support"},
  {"id":"nf-042","cat":"be-an-ally","type":"sort","hook":"Sort: an ally (upstander) move, or not?","items":[{"id":"a","text":"Saying 'that's not kind'"},{"id":"b","text":"Laughing along"},{"id":"c","text":"Sitting with the teased kid"},{"id":"d","text":"Filming it for fun"},{"id":"e","text":"Telling a trusted adult"},{"id":"f","text":"Egging the teaser on"}],"bins":[{"id":"ally","label":"Ally move","valence":"pos"},{"id":"no","label":"Not an ally","valence":"neg"}],"key":{"a":"ally","b":"no","c":"ally","d":"no","e":"ally","f":"no"},"relearn":"Allies speak up, support and tell; laughing, filming or egging on feeds the harm.","persona":"any","source":"upstander moves"},
  {"id":"nf-043","cat":"be-an-ally","type":"branch","hook":"You spoke up and the teaser turned on you a bit.","options":[{"text":"Stay calm; get a friend or adult to back you","consequence":"With backup it's easier; the right people respect you.","outcome":"upstander","best":true},{"text":"Wish you'd stayed quiet","consequence":"Bringing backup makes standing up safer and easier."}],"debrief":"You don't have to be a lone hero, bring a friend or an adult.","relearn":"If speaking up gets hard, bring backup, a friend or adult.","persona":"any","source":"upstander / safety"},
  {"id":"nf-044","cat":"be-an-ally","type":"reflect","hook":"Lensy: being an ally takes courage. Got some?","prompt":"What do you think?","options":["Yes","A bit, growing","I'll be brave"],"affirm":"Courage grows each time you use it. You've got this.","relearn":"Allyship takes courage, and courage grows with practice.","persona":"any","source":"self-efficacy"},
  {"id":"nf-045","cat":"be-an-ally","type":"branch","hook":"A whole group is teasing one kid; you're just one person.","options":[{"text":"Stand next to the kid; others often join you","consequence":"One upstander gives other quiet kids courage to join.","outcome":"upstander","best":true},{"text":"Assume one person can't help","consequence":"One upstander often sparks others to step up too."}],"debrief":"One person standing up gives everyone else permission to.","relearn":"Even one ally can shift the whole group.","persona":"Ananya","source":"bystander research"},
  {"id":"nf-046","cat":"be-an-ally","type":"role-play","hook":"You see a 'just a joke' put-down and want to name it.","setup":"Say the two-word classic:","yourLine":[{"text":"\"Not funny.\"","best":true},{"text":"A nervous laugh"}],"relearn":"A simple \"not funny\" can open everyone's eyes.","persona":"Ananya","source":"upstander / voice"},
  {"id":"nf-047","cat":"be-an-ally","type":"strike-rewrite","hook":"\"Telling an adult about teasing is tattling.\"","myth":{"un":"Telling an adult about teasing is tattling.","re":"Telling to keep someone safe is reporting, and it's brave.","why":"Reporting helps; tattling is just to get someone in trouble."},"relearn":"Telling an adult to stop teasing is reporting, not tattling.","persona":"Ananya","source":"telling vs tattling"},
  {"id":"nf-048","cat":"be-an-ally","type":"reflect","hook":"Lensy: which ally move feels most like you?","prompt":"Pick one to try.","options":["Speak up","Distract","Support the kid","Tell an adult"],"affirm":"That's your go-to ally move, keep it ready.","relearn":"Pick an ally move that fits you; any of them helps.","persona":"any","source":"upstander moves"},
  {"id":"nf-049","cat":"be-an-ally","type":"branch","hook":"Your own friend is the one doing the teasing.","options":[{"text":"Quietly tell them \"that's not cool, ease off\"","consequence":"A friend's word often lands best; they stop.","outcome":"upstander","best":true},{"text":"Stay loyal and say nothing","consequence":"Real loyalty includes helping a friend be kinder."}],"debrief":"Telling a friend to stop is hard, and a real act of friendship.","relearn":"A good friend helps another friend stop being unkind.","persona":"Reyansh","source":"upstander / friendship"},
  {"id":"nf-050","cat":"be-an-ally","type":"build","hook":"Build your ally toolkit.","prompt":"Pick the moves to keep ready.","pieces":["speak up: 'not cool'","distract / change subject","support the kid after","tell a trusted adult","laugh along"],"mode":"assemble","key":["speak up: 'not cool'","distract / change subject","support the kid after","tell a trusted adult"],"relearn":"Your ally toolkit: speak up, distract, support, tell, never laugh along.","persona":"any","source":"upstander moves"},
  {"id":"nf-051","cat":"be-an-ally","type":"reflect","hook":"Lensy: when you stand up for someone, how do they feel?","prompt":"What do you think?","options":["Less alone","Supported","Grateful"],"affirm":"Your stand tells them they're not alone, that's huge.","relearn":"Standing up tells someone they're not alone.","persona":"any","source":"support"},
  {"id":"nf-052","cat":"be-an-ally","type":"branch","hook":"You weren't brave enough to step in this time.","options":[{"text":"Check in with the kid after, and plan to do better","consequence":"You still help, and you're readier next time.","outcome":"growth","best":true},{"text":"Feel guilty and do nothing","consequence":"You can still help after, and try again next time."}],"debrief":"If you froze, you can still support after, and grow braver.","relearn":"Even if you froze, you can help after and try again.","persona":"quiet child","source":"self-compassion / growth"},
  // — Checking my own jokes —
  {"id":"nf-053","cat":"my-own-jokes","type":"reflect","hook":"Lensy honest check: do your jokes ever punch DOWN at someone?","prompt":"Be honest with yourself.","options":["Sometimes","Maybe","I'll watch for it"],"affirm":"Noticing your own jokes is exactly what a kind, funny person does.","relearn":"Checking your own jokes for who they punch at is smart and kind.","persona":"Reyansh","source":"self-awareness"},
  {"id":"nf-054","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"The best way to be funny is to roast someone.\"","myth":{"un":"You have to put someone down to be funny.","re":"The funniest people make jokes that don't need a victim.","why":"Wit beats cruelty, and ages better."},"relearn":"You can be hilarious without putting anyone down.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-055","cat":"my-own-jokes","type":"branch","hook":"You think of a joke that would get a big laugh but it targets a kid.","options":[{"text":"Skip it, or aim it at yourself / a silly thing instead","consequence":"You still get the laugh, no one's hurt.","outcome":"kind","best":true},{"text":"Tell it anyway for the laugh","consequence":"A laugh at someone's cost isn't worth the hurt."}],"debrief":"A laugh that costs someone else isn't worth it, redirect the joke.","relearn":"Aim jokes at ideas or yourself, not at a person.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-056","cat":"my-own-jokes","type":"role-play","hook":"You made a joke that hurt; you want to fix it.","setup":"Make it right. Say:","yourLine":[{"text":"\"That came out unkind, I'm sorry.\"","best":true},{"text":"\"You're too sensitive.\""}],"relearn":"A clean apology beats blaming the person you hurt.","persona":"Reyansh","source":"repair / voice"},
  {"id":"nf-057","cat":"my-own-jokes","type":"sort","hook":"Sort: a joke that's safe to tell, or one to skip?","items":[{"id":"a","text":"A pun everyone enjoys"},{"id":"b","text":"A jab at a kid's family"},{"id":"c","text":"A silly story about yourself"},{"id":"d","text":"Mocking how someone talks"},{"id":"e","text":"A daft riddle about animals"},{"id":"f","text":"A joke about a boy liking pink"}],"bins":[{"id":"safe","label":"Safe to tell","valence":"pos"},{"id":"skip","label":"Skip it","valence":"neg"}],"key":{"a":"safe","b":"skip","c":"safe","d":"skip","e":"safe","f":"skip"},"relearn":"Puns, riddles and self-jokes are safe; jabs at people are ones to skip.","persona":"any","source":"inclusive humor"},
  {"id":"nf-058","cat":"my-own-jokes","type":"reflect","hook":"Lensy: a good rule, joke UP or sideways, not DOWN. Makes sense?","prompt":"What do you think?","options":["Yes","Don't punch down","Good rule"],"affirm":"Don't punch down, jokes shouldn't kick someone who's already a target.","relearn":"Aim humor sideways or at yourself, not down at someone vulnerable.","persona":"any","source":"inclusive humor"},
  {"id":"nf-059","cat":"my-own-jokes","type":"branch","hook":"Friends egg you on to mock another kid for laughs.","options":[{"text":"Say \"nah, let's not, that's not cool\"","consequence":"You hold your line; good friends respect it.","outcome":"values","best":true},{"text":"Do it to please them","consequence":"You don't have to be unkind to keep friends."}],"debrief":"You can resist the pressure to get laughs by hurting someone.","relearn":"You can say no to making someone the joke, even for friends.","persona":"Reyansh","source":"peer pressure / values"},
  {"id":"nf-060","cat":"my-own-jokes","type":"reflect","hook":"Lensy: being funny AND kind, that's the real skill. Up for it?","prompt":"What do you think?","options":["Yes","Funny and kind","That's my goal"],"affirm":"Funny-and-kind is the gold standard. You can be both.","relearn":"The real skill is being funny and kind at the same time.","persona":"any","source":"inclusive humor"},
  {"id":"nf-061","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"Saying sorry for a joke is weak.\"","myth":{"un":"Apologising for a joke makes you look weak.","re":"Owning a joke that hurt is strong and respected.","why":"Big people repair; only small ones double down."},"relearn":"Apologising for a joke that hurt is a strong move.","persona":"Reyansh","source":"repair / values"},
  {"id":"nf-062","cat":"my-own-jokes","type":"build","hook":"Build a 'kind comedian' code.","prompt":"Pick the rules.","pieces":["joke with people, not at them","punch up or sideways, never down","stop if it hurts","apologise if it lands wrong","make someone the target"],"mode":"assemble","key":["joke with people, not at them","punch up or sideways, never down","stop if it hurts","apologise if it lands wrong"],"relearn":"Kind comedian code: with not at, never down, stop if it hurts, apologise.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-063","cat":"gender-teasing","type":"branch","hook":"A boy is mocked for having girls as his best friends.","options":[{"text":"Say \"boys and girls can totally be friends\"","consequence":"You defend a real friendship; the mocking fades.","outcome":"ally","best":true},{"text":"Tease him too","consequence":"Friendship across genders is normal and good."}],"debrief":"There's nothing to mock about boys and girls being friends.","relearn":"Boys and girls being friends isn't something to tease.","persona":"Faizan-type","source":"gender norms / friendship"},
  {"id":"nf-064","cat":"just-a-joke","type":"branch","hook":"A kid says \"you're so dumb for a girl, haha\" and calls it a joke.","options":[{"text":"Say \"that's a put-down, not a joke, stop\"","consequence":"You name the dig; the 'joke' cover falls away.","outcome":"ally","best":true},{"text":"Laugh because it ended in 'haha'","consequence":"A 'haha' on a put-down doesn't make it a real joke."}],"debrief":"A 'joke' that insults a girl's brains is a put-down in disguise.","relearn":"Watch for put-downs dressed up as jokes, and name them.","persona":"Ananya","source":"disparagement humor"},
  {"id":"nf-065","cat":"how-it-feels","type":"branch","hook":"You're the one being teased and it really hurts.","options":[{"text":"Say \"that's not okay\" and tell a trusted adult if it keeps on","consequence":"You stand up for yourself and get support.","outcome":"assertive","best":true},{"text":"Bottle it up","consequence":"You deserve support; telling someone helps."}],"debrief":"If you're the target, you can speak up and get help, it's not your fault.","relearn":"If you're teased, you can say 'not okay' and tell a trusted adult.","persona":"Faizan-type","source":"self-advocacy"},
  {"id":"nf-066","cat":"be-an-ally","type":"branch","hook":"Online, kids are piling mean 'jokes' on someone in a group chat.","options":[{"text":"Don't add to it; message the kid kindly and tell an adult","consequence":"You break the pile-on and support them.","outcome":"upstander","best":true},{"text":"Add a laughing emoji","consequence":"Even an emoji feeds an online pile-on."}],"debrief":"Online put-downs spread fast; not adding, and supporting, matters.","relearn":"Don't feed an online pile-on; support the target and tell an adult.","persona":"Reyansh","source":"cyberbullying / upstander"},
  {"id":"nf-067","cat":"fun-vs-mean","type":"reflect","hook":"Lensy: with real friends, teasing stops the moment it stings. True?","prompt":"What do you think?","options":["Yes","Real friends stop","That's the test"],"affirm":"Real friends ease off the instant it stops being fun.","relearn":"Real friends stop teasing the moment it hurts.","persona":"any","source":"friendship / teasing"},
  {"id":"nf-068","cat":"gender-teasing","type":"role-play","hook":"Someone says 'don't be such a girl' to a boy who's scared.","setup":"Reframe it. Say:","yourLine":[{"text":"\"Being scared is human, not a 'girl' thing.\"","best":true},{"text":"Snigger"}],"relearn":"Feelings aren't a gender; don't use 'girl' as an insult.","persona":"Faizan-type","source":"gender teasing"},
  {"id":"nf-069","cat":"my-own-jokes","type":"reflect","hook":"Lensy: would your joke still feel funny if it were about YOU?","prompt":"A good test?","options":["Yes, great test","I'll use it","Helps me check"],"affirm":"The 'would I laugh if it were me?' test keeps jokes kind.","relearn":"Test a joke by imagining it aimed at you.","persona":"Reyansh","source":"empathy / perspective-taking"},
  {"id":"nf-070","cat":"be-an-ally","type":"branch","hook":"You see teasing but you're new and don't want trouble.","options":[{"text":"Start small, sit with the kid or tell an adult quietly","consequence":"Even quiet allyship helps and feels safer.","outcome":"upstander","best":true},{"text":"Decide it's not your place","consequence":"Quiet allyship still counts and is a safe start."}],"debrief":"Allyship can be quiet, you don't have to make a scene.","relearn":"You can be a quiet ally: sit with them, tell an adult.","persona":"quiet child","source":"upstander moves"},
  {"id":"nf-071","cat":"just-a-joke","type":"reflect","hook":"Lensy: 'I was joking' shouldn't erase someone's hurt. Agree?","prompt":"What do you think?","options":["Yes","Hurt still counts","Agree"],"affirm":"'I was joking' doesn't undo the hurt, caring about that is kindness.","relearn":"'I was joking' doesn't cancel the hurt a joke caused.","persona":"any","source":"impact over intent"},
  {"id":"nf-072","cat":"how-it-feels","type":"reflect","hook":"Lensy: a kind word can undo a mean joke's sting. Want to be that person?","prompt":"What do you think?","options":["Yes","I can be kind","Count me in"],"affirm":"You can be the kind word that helps someone bounce back.","relearn":"A kind word can heal the sting of a put-down.","persona":"any","source":"support"},
  {"id":"nf-073","cat":"fun-vs-mean","type":"branch","hook":"A classmate gives you a goofy nickname; you actually don't like it.","options":[{"text":"Say \"please don't call me that\"","consequence":"A kind classmate stops; your feelings count.","outcome":"assertive","best":true},{"text":"Put up with it","consequence":"You're allowed to say a nickname doesn't sit right."}],"debrief":"Even a 'friendly' nickname should stop if you don't like it.","relearn":"You can ask someone to stop a nickname you dislike.","persona":"any","source":"boundaries"},
  {"id":"nf-074","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Teasing toughens kids up, so it's good for them.\"","myth":{"un":"Teasing toughens kids up.","re":"Mean teasing wears kids down; support builds real strength.","why":"Kids grow strong from safety and support, not put-downs."},"relearn":"Mean teasing doesn't toughen kids; it wears them down.","persona":"any","source":"child wellbeing"},
  {"id":"nf-075","cat":"be-an-ally","type":"role-play","hook":"The class is laughing at one kid; you decide to flip it.","setup":"Redirect with warmth. Say:","yourLine":[{"text":"\"Hey, leave them, who wants to play?\"","best":true},{"text":"Add to the laughing"}],"relearn":"Redirecting the group's energy is a clever ally move.","persona":"Ananya","source":"upstander / distraction"},
  {"id":"nf-076","cat":"my-own-jokes","type":"branch","hook":"Capstone: the whole group's watching and you've a joke ready, about a kid.","options":[{"text":"Switch it to a silly self-joke or a fun topic","consequence":"You get the laugh and keep everyone safe.","outcome":"kind","best":true},{"text":"Land the joke at the kid's expense","consequence":"Power over a crowd is a chance to be kind, not cruel."}],"debrief":"With the crowd, use it to include, not to wound.","relearn":"With everyone watching, pick the joke that hurts no one.","persona":"Reyansh","source":"inclusive humor / consolidation"},
  {"id":"nf-077","cat":"be-an-ally","type":"reflect","hook":"Lensy: who could YOU stand up for this week?","prompt":"Think of someone.","options":["A teased classmate","A left-out kid","Anyone put down","Myself"],"affirm":"That's an upstander plan. Small stands change the whole room.","relearn":"You can choose to be an ally, in small ways, often.","persona":"any","source":"agency"},
  {"id":"nf-078","cat":"gender-teasing","type":"sort","hook":"Sort: a fair comment, or a gender put-down dressed as a joke?","items":[{"id":"a","text":"\"You're really good at this\""},{"id":"b","text":"\"For a girl, not bad, haha\""},{"id":"c","text":"\"Want to team up?\""},{"id":"d","text":"\"Real boys don't do that\""},{"id":"e","text":"\"You're a great teammate\""},{"id":"f","text":"\"Stop being such a girl\""}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"putdown","label":"Gender put-down","valence":"neg"}],"key":{"a":"fair","b":"putdown","c":"fair","d":"putdown","e":"fair","f":"putdown"},"relearn":"'For a girl' and 'real boys don't' are put-downs, not compliments or jokes.","persona":"Ananya","source":"gender teasing"},
  {"id":"nf-079","cat":"how-it-feels","type":"branch","hook":"A group you're in always jokes about the same kid.","options":[{"text":"Name it: \"we always pick on them, let's stop\"","consequence":"You break a mean pattern the group drifted into.","outcome":"upstander","best":true},{"text":"Keep the pattern going","consequence":"'Jokes' aimed at one kid are bullying; you can break them."}],"debrief":"A repeated 'joke' at one kid is bullying. Name it and stop it.","relearn":"Always joking about one kid is bullying; break it.","persona":"Ananya","source":"teasing vs bullying"},
  {"id":"nf-080","cat":"just-a-joke","type":"reflect","hook":"Lensy: 'not fair, not funny', when does a joke fail that test?","prompt":"Pick one.","options":["When it hurts someone","When it puts a group down","When it won't stop"],"affirm":"All of those, that's exactly when a joke isn't fair or funny.","relearn":"A joke fails when it hurts, puts a group down, or won't stop.","persona":"any","source":"consolidation"},
  {"id":"nf-081","cat":"be-an-ally","type":"build","hook":"Capstone: build your upstander plan.","prompt":"Pick what you'll do when you see a put-down.","pieces":["say 'not cool'","support the kid after","distract / redirect","tell a trusted adult","laugh along"],"mode":"assemble","key":["say 'not cool'","support the kid after","distract / redirect","tell a trusted adult"],"relearn":"Your upstander plan: speak up, support, distract, tell, never laugh along.","persona":"any","source":"consolidation"},
  {"id":"nf-082","cat":"my-own-jokes","type":"reflect","hook":"Lensy: what will you carry from Not Fair, Not Funny?","prompt":"Pick your motto.","options":["Joke with, not at","Not funny if it hurts","Be an ally","Punch up, never down"],"affirm":"Carry that. You can be the funny one AND the kind one.","relearn":"Jokes are for laughing together, never at someone; and be an ally.","persona":"any","source":"consolidation"},
  {"id":"nf-083","cat":"fun-vs-mean","type":"strike-rewrite","hook":"\"Everyone teases, so it's just normal.\"","myth":{"un":"Everyone teases, so mean teasing is just normal.","re":"Common doesn't mean kind; we can do better than mean teasing.","why":"Normal isn't the same as fair or funny."},"relearn":"Just because teasing is common doesn't make it okay.","persona":"any","source":"norms"},
  {"id":"nf-084","cat":"be-an-ally","type":"reflect","hook":"Lensy: imagine a class where everyone's an ally. Good place?","prompt":"What do you think?","options":["Amazing","Everyone safe","Yes!"],"affirm":"That's the world allies build, one 'not cool' at a time.","relearn":"When everyone's an ally, everyone is safer and kinder.","persona":"any","source":"vision"},
  {"id":"nf-900","cat":"be-an-ally","type":"branch","hook":"Two boys keep calling a classmate 'girly' for his pink lunchbox.","options":[{"text":"Step beside him: \"Pink's great. Let's go sit.\"","consequence":"He relaxes and the teasing loses its crowd.","outcome":"upstander","best":true},{"text":"Eat fast and move away","consequence":"He's left alone with it; standing near him helps."}],"debrief":"Standing close to the teased kid takes away the teaser's audience.","relearn":"Standing with someone is an ally move, even without a word.","persona":"Faizan-type","source":"upstander moves"},
  {"id":"nf-901","cat":"be-an-ally","type":"branch","hook":"On the bus, kids chant \"crybaby\" at a boy who teared up after a fall.","options":[{"text":"Say \"everyone cries, that's not funny\" and sit by him","consequence":"The chant fizzles and he isn't alone.","outcome":"upstander","best":true},{"text":"Look out the window","consequence":"The chant grows; a calm \"not funny\" can stop it fast."}],"debrief":"\"Boys don't cry\" is false, and naming the put-down stops it.","relearn":"Everyone cries; calling it out is an ally move.","persona":"any","source":"upstander / gender"},
  {"id":"nf-902","cat":"be-an-ally","type":"branch","hook":"A girl who organised the game is being called \"bossy\" by two teammates.","options":[{"text":"\"She's leading, not bossy. Let's just play.\"","consequence":"They drop it and the game starts.","outcome":"upstander","best":true},{"text":"Shrug, it's not about you","consequence":"\"Bossy\" sticks to her; a quick correction would help."}],"debrief":"Calling a girl bossy for leading is a gender put-down, not a fact.","relearn":"Backing a leader who's called \"bossy\" is allyship.","persona":"Ananya","source":"upstander / gender"},
  {"id":"nf-903","cat":"be-an-ally","type":"branch","hook":"During PT, boys laugh \"you throw like a girl\" at someone who missed.","options":[{"text":"\"Girls throw great. Try again, you've got this.\"","consequence":"The laugh stops and he tries again.","outcome":"upstander","best":true},{"text":"Laugh a little so you fit in","consequence":"Your laugh feeds it; a kind line would have helped instead."}],"debrief":"\"Like a girl\" isn't an insult, and refusing to laugh is an ally move.","relearn":"Not joining the laugh, and encouraging, is allyship.","persona":"any","source":"upstander / gender"},
  {"id":"nf-904","cat":"be-an-ally","type":"branch","hook":"You hear a kid being teased about her dark skin.","options":[{"text":"\"Skin jabs aren't jokes. Come get water.\"","consequence":"You name it and walk her away.","outcome":"upstander","best":true},{"text":"Pretend you didn't hear","consequence":"It keeps going; naming it helps."}],"debrief":"Colour and looks jabs are put-downs, never jokes, and you can refuse them.","relearn":"Calling out a skin jab and supporting her is an ally move.","persona":"Ananya","source":"upstander / colourism"},
  {"id":"nf-905","cat":"be-an-ally","type":"branch","hook":"A new kid who speaks a different language is being mimicked by a group.","options":[{"text":"Go talk to the new kid and ask them to join your game","consequence":"They feel welcome and the mimicking loses steam.","outcome":"upstander","best":true},{"text":"Watch and say nothing","consequence":"They stay an outsider; a simple welcome would change that."}],"debrief":"Including someone is a powerful, low-risk way to be an ally.","relearn":"Welcoming a teased kid in is real allyship.","persona":"quiet child","source":"upstander / inclusion"},
  {"id":"nf-906","cat":"be-an-ally","type":"branch","hook":"Kids keep mocking a classmate for his worn-out, torn shoes.","options":[{"text":"Change the subject: \"Who's up for langdi at break?\"","consequence":"The focus shifts and the mocking stops.","outcome":"upstander","best":true},{"text":"Add \"yeah they're old\"","consequence":"You join the put-down; redirecting would have helped him."}],"debrief":"Distracting the group is a calm ally move that needs no confrontation.","relearn":"Changing the subject can quietly stop a put-down.","persona":"quiet child","source":"upstander / distraction"},
  {"id":"nf-907","cat":"be-an-ally","type":"branch","hook":"You froze when a kid was teased, but lunch is coming up.","options":[{"text":"Sit with him: \"that wasn't fair earlier\"","consequence":"He feels less alone and you're still an ally.","outcome":"growth","best":true},{"text":"Avoid him so it's less awkward","consequence":"He stays alone; checking in after still helps."}],"debrief":"Checking in after still helps, even if you couldn't step in then.","relearn":"You can be an ally after the moment, not only during it.","persona":"quiet child","source":"upstander / support"},
  {"id":"nf-908","cat":"be-an-ally","type":"branch","hook":"The teasing won't stop even after kids said \"stop\".","options":[{"text":"Tell Mrs. Pillai so she can keep him safe","consequence":"A trusted teacher steps in and it stops.","outcome":"tell","best":true},{"text":"Keep quiet, you don't want to seem a tattletale","consequence":"Telling to keep someone safe is reporting."}],"debrief":"Telling a trusted teacher to keep someone safe is reporting, not tattling.","relearn":"When teasing won't stop, telling a trusted adult is brave.","persona":"any","source":"telling vs tattling"},
  {"id":"nf-909","cat":"be-an-ally","type":"branch","hook":"Your big sister Sana is nearby when kids gang up on your friend.","options":[{"text":"Go get Sana to help sort it out","consequence":"An older sibling steps in and they back off.","outcome":"tell","best":true},{"text":"Decide only parents count as help","consequence":"An older sibling is a trusted grown-up too."}],"debrief":"A trusted older sibling counts as someone you can tell, not just a parent.","relearn":"An older sibling is a trusted person you can go to for help.","persona":"any","source":"trusted adult / sibling"},
  {"id":"nf-910","cat":"be-an-ally","type":"branch","hook":"A kid is being teased but you're shy and confronting feels scary.","options":[{"text":"Quietly sit beside her and share your snack","consequence":"She feels supported, no big speech needed.","outcome":"upstander","best":true},{"text":"Decide allies must shout at the teaser","consequence":"Quiet ally moves count too; sitting with her helps."}],"debrief":"Quiet allyship, like sitting with someone, helps and feels safer.","relearn":"You can be a quiet ally without confronting anyone.","persona":"quiet child","source":"low-risk allyship"},
  {"id":"nf-911","cat":"be-an-ally","type":"branch","hook":"Reyansh repeats a 'joke' he saw online that puts down a classmate.","options":[{"text":"\"That one's mean, yaar. Let's not.\"","consequence":"He thinks again and drops the joke.","outcome":"upstander","best":true},{"text":"Repeat it too so he isn't embarrassed","consequence":"Repeating spreads it; a gentle nudge helps him check it."}],"debrief":"A friend's gentle nudge helps a friend check a hurtful joke.","relearn":"Helping a friend rethink a mean joke is a kind ally move.","persona":"Reyansh","source":"upstander / friendship"},
  {"id":"nf-912","cat":"be-an-ally","type":"branch","hook":"In the class chat, kids pile laughing stickers on one boy's photo.","options":[{"text":"Don't add to it; message him kindly in private","consequence":"You break the pile-on and he knows you care.","outcome":"upstander","best":true},{"text":"Add one sticker, it's no big deal","consequence":"Even one feeds it; reaching out helps."}],"debrief":"Not adding, and checking in privately, stops an online pile-on.","relearn":"In a chat, not piling on and reaching out is an ally move.","persona":"Reyansh","source":"cyber allyship"},
  {"id":"nf-913","cat":"be-an-ally","type":"branch","hook":"The teased kid starts crying and the teasers laugh harder.","options":[{"text":"Take him aside: \"Come, let's go.\"","consequence":"He gets away from it and isn't alone.","outcome":"upstander","best":true},{"text":"Wait for a teacher to notice","consequence":"He stays in it; walking him out helps now."}],"debrief":"Getting the target to safety is an ally move you can do right away.","relearn":"Walking a hurt friend out of it helps in the moment.","persona":"any","source":"upstander / support"},
  {"id":"nf-914","cat":"be-an-ally","type":"branch","hook":"You're the only one who saw a kid put down in a quiet corner.","options":[{"text":"Go over: \"that's not kind, stop\"","consequence":"No crowd, so your one voice ends it.","outcome":"upstander","best":true},{"text":"Think \"someone else will deal with it\"","consequence":"No one else saw; your voice stops it."}],"debrief":"If you're the only one who sees it, your one voice still matters.","relearn":"One person who notices can stop a put-down by speaking up.","persona":"Ananya","source":"bystander research"},
  {"id":"nf-915","cat":"be-an-ally","type":"branch","hook":"A kid is teased for liking dance, which others call \"girly\".","options":[{"text":"\"Anyone can like dance.\" Then join him.","consequence":"He stops shrinking and the tease falls flat.","outcome":"upstander","best":true},{"text":"Stay out of it to be safe","consequence":"He hides what he loves; backing him helps."}],"debrief":"\"Girly\" isn't an insult, and backing what someone loves is allyship.","relearn":"Standing up for what a friend likes is an ally move.","persona":"Faizan-type","source":"upstander / gender"},
  {"id":"nf-916","cat":"be-an-ally","type":"strike-rewrite","hook":"\"I'm only one kid, I can't make teasing stop.\"","myth":{"un":"One kid is too small to stop teasing.","re":"When one peer steps in, teasing often stops within seconds.","why":"A single voice tells the teaser the crowd isn't on their side."},"relearn":"Even one ally stepping in can stop teasing fast.","persona":"Ananya","source":"bystander research"},
  {"id":"nf-917","cat":"be-an-ally","type":"strike-rewrite","hook":"\"If I'm too shy to speak up, I just can't help at all.\"","myth":{"un":"A shy kid has no way to be an ally.","re":"Quiet moves like sitting with the kid or telling an adult help too.","why":"Allyship has many doors, and not all of them need a loud voice."},"relearn":"You can be a quiet ally; you don't have to confront anyone.","persona":"quiet child","source":"low-risk allyship"},
  {"id":"nf-918","cat":"be-an-ally","type":"strike-rewrite","hook":"\"Telling a teacher about teasing makes me a tattletale.\"","myth":{"un":"Telling a teacher about teasing is tattling.","re":"Telling to keep someone safe is reporting, and it is brave.","why":"Reporting protects a person; tattling just tries to get someone in trouble."},"relearn":"Telling a trusted adult to keep someone safe is reporting, not tattling.","persona":"any","source":"telling vs tattling"},
  {"id":"nf-919","cat":"be-an-ally","type":"strike-rewrite","hook":"\"It's their fight, I shouldn't get in the middle.\"","myth":{"un":"Teasing between others is none of my business.","re":"Stepping in is your business; silence lets teasing grow.","why":"Bystanders set the tone, so doing nothing quietly takes the teaser's side."},"relearn":"Standing up for others is exactly your business.","persona":"any","source":"bystander research"},
  {"id":"nf-920","cat":"be-an-ally","type":"strike-rewrite","hook":"\"If I help the teased kid, they'll just look weaker.\"","myth":{"un":"Helping a teased kid makes them look weak.","re":"Backed-up kids feel calmer and less alone, not weaker.","why":"Support builds someone up; being left alone is what wears them down."},"relearn":"Backing someone up makes them feel less alone, not weaker.","persona":"any","source":"support research"},
  {"id":"nf-921","cat":"be-an-ally","type":"strike-rewrite","hook":"\"I have to fix it all by myself or I shouldn't try.\"","myth":{"un":"A real ally handles it completely alone.","re":"Bringing a friend or trusted adult to help is smart allyship.","why":"You don't have to be a lone hero, and backup makes helping safer."},"relearn":"You can ally by getting backup, you don't have to act alone.","persona":"any","source":"upstander / safety"},
  {"id":"nf-922","cat":"be-an-ally","type":"role-play","hook":"A kid is being teased and you want to step in calmly.","setup":"Say a short, steady line to the teasers:","yourLine":[{"text":"\"That's enough, stop.\"","best":true},{"text":"Giggle nervously"}],"relearn":"A calm \"that's enough, stop\" can end teasing fast.","persona":"any","source":"upstander / voice"},
  {"id":"nf-923","cat":"be-an-ally","type":"role-play","hook":"You want to pull a teased classmate away from the crowd.","setup":"Invite her to come with you. Say:","yourLine":[{"text":"\"Chal, come play with us.\"","best":true},{"text":"Say nothing and hope she follows"}],"relearn":"A warm invite gives a teased kid a way out, fast.","persona":"any","source":"upstander / support"},
  {"id":"nf-924","cat":"be-an-ally","type":"role-play","hook":"After the teasing stops, you find the kid sitting alone.","setup":"Check in on how he's doing. Say:","yourLine":[{"text":"\"You okay? That wasn't fair to you.\"","best":true},{"text":"Walk past quietly"}],"relearn":"Checking in after tells someone they matter and aren't alone.","persona":"any","source":"upstander / check-in"},
  {"id":"nf-925","cat":"be-an-ally","type":"role-play","hook":"Your friend keeps poking fun at a kid for crying.","setup":"Tell your friend to ease off. Say:","yourLine":[{"text":"\"Hey, leave it. Everyone cries.\"","best":true},{"text":"Laugh along so it's not awkward"}],"relearn":"A friend's calm \"leave it\" can stop a put-down quickly.","persona":"Reyansh","source":"upstander / friendship"},
  {"id":"nf-926","cat":"be-an-ally","type":"role-play","hook":"You decide to redirect the group's energy into a game.","setup":"Change the focus with warmth. Say:","yourLine":[{"text":"\"Leave that, who wants to play kabaddi?\"","best":true},{"text":"Stand quietly in the crowd"}],"relearn":"Redirecting the group is a clever way to stop a put-down.","persona":"Ananya","source":"upstander / distraction"},
  {"id":"nf-927","cat":"be-an-ally","type":"role-play","hook":"A kid is being mocked for the food in his tiffin.","setup":"Stand up for his lunch. Say:","yourLine":[{"text":"\"That smells great, can I try some?\"","best":true},{"text":"Wrinkle your nose too"}],"relearn":"Showing real interest flips a put-down into something kind.","persona":"any","source":"upstander / inclusion"},
  {"id":"nf-928","cat":"be-an-ally","type":"role-play","hook":"You want to ask a teased classmate to your group at break.","setup":"Make the invite clear and warm. Say:","yourLine":[{"text":"\"Come sit with us, there's space.\"","best":true},{"text":"Hope someone else invites her"}],"relearn":"A simple invite to sit together is real, everyday allyship.","persona":"quiet child","source":"upstander / inclusion"},
  {"id":"nf-929","cat":"be-an-ally","type":"role-play","hook":"The teaser tries the old dodge: \"can't you take a joke?\"","setup":"Hold your ground gently. Say:","yourLine":[{"text":"\"It's not a joke if it hurts him.\"","best":true},{"text":"Mumble \"I guess\" and back off"}],"relearn":"\"Can't you take a joke?\" is a dodge; a hurtful joke still hurts.","persona":"Ananya","source":"upstander / just-a-joke"},
  {"id":"nf-930","cat":"be-an-ally","type":"reflect","hook":"Lensy: when have YOU felt glad someone stood up for you?","prompt":"Think of a time.","options":["A friend spoke up","Someone sat with me","I wasn't alone"],"affirm":"Remembering that feeling can help you give it to someone else. 💛","persona":"any","source":"empathy / agency","relearn":"Recalling how it felt when someone stood up for you helps you do it for others."},
  {"id":"nf-931","cat":"be-an-ally","type":"reflect","hook":"Lensy: which calm line could YOU keep ready to use?","prompt":"Pick one to remember.","options":["\"That's not kind, stop\"","\"Not funny\"","\"Leave it, let's play\""],"affirm":"Keeping a line ready makes it easier to step in next time.","persona":"any","source":"self-efficacy","relearn":"Keeping a calm line ready makes it easier to step in next time."},
  {"id":"nf-932","cat":"be-an-ally","type":"reflect","hook":"Lensy: a quiet ally move can be just as kind. Which feels like you?","prompt":"Pick one you'd try.","options":["Sit with the kid","Share my snack","Walk them away"],"affirm":"Quiet moves count just as much as loud ones. Nice pick.","persona":"quiet child","source":"low-risk allyship","relearn":"Quiet ally moves like sitting with someone count just as much as loud ones."},
  {"id":"nf-933","cat":"be-an-ally","type":"reflect","hook":"Lensy: who is a trusted grown-up YOU could go to for help?","prompt":"Think of one person.","options":["My teacher","My older sibling","A parent","A coach"],"affirm":"Knowing who you'd tell makes it easier to get help fast.","persona":"any","source":"trusted adult","relearn":"Knowing which trusted grown-up you'd tell helps you get help fast."},
  {"id":"nf-934","cat":"be-an-ally","type":"reflect","hook":"Lensy: after you help someone, how do you usually feel?","prompt":"What do you think?","options":["Proud","Braver","Glad I did"],"affirm":"That good feeling is courage growing. It gets easier each time.","persona":"any","source":"self-efficacy","relearn":"The good feeling after helping is courage growing; it gets easier each time."},
  {"id":"nf-935","cat":"be-an-ally","type":"reflect","hook":"Lensy: what could you say to a friend who froze and feels bad?","prompt":"Pick a kind thing.","options":["\"You can help now\"","\"Let's try together\"","\"Next time we'll be ready\""],"affirm":"Being kind to a friend who froze helps you both grow braver.","persona":"any","source":"self-compassion","relearn":"Being kind to a friend who froze helps you both grow braver."},
  {"id":"nf-936","cat":"be-an-ally","type":"reflect","hook":"Lensy: where do you see kids get teased most? Where could you help?","prompt":"Think of a spot.","options":["The playground","The bus","The chat group","Lunch line"],"affirm":"Noticing where it happens means you're ready to help there.","persona":"any","source":"agency","relearn":"Noticing where teasing happens means you're ready to help there."},
  {"id":"nf-937","cat":"be-an-ally","type":"reflect","hook":"Lensy: imagine you stood up today. What's one word for that you?","prompt":"Pick a word.","options":["Brave","Kind","Fair","Strong"],"affirm":"That's the ally already inside you. Now you know its name.","persona":"any","source":"self-image","relearn":"You can name the brave, kind ally already inside you."},
  {"id":"nf-938","cat":"be-an-ally","type":"reflect","hook":"Lensy: a friend says \"it's not my problem.\" What would you tell them?","prompt":"Pick your answer.","options":["\"It could be us next\"","\"Silence helps the teaser\"","\"We can help\""],"affirm":"You see it: standing up is everyone's business. 💛","persona":"Ananya","source":"bystander research","relearn":"Standing up is everyone's business; silence helps the teaser."},
  {"id":"nf-939","cat":"be-an-ally","type":"reflect","hook":"Lensy: what's one small kind thing you could do for a teased kid?","prompt":"Think of one.","options":["Smile at them","Say hi","Save them a seat"],"affirm":"Small kindnesses add up, and they help someone feel seen.","persona":"any","source":"everyday allyship","relearn":"Small kindnesses add up and help a teased kid feel seen."},
  {"id":"nf-940","cat":"be-an-ally","type":"build","hook":"Build a plan for when a friend is being teased right now.","prompt":"Pick the steps for stepping in safely.","pieces":["say \"that's not kind, stop\"","walk them away from it","get a trusted adult if it won't stop","laugh along to fit in"],"mode":"sequence","key":["say \"that's not kind, stop\"","walk them away from it","get a trusted adult if it won't stop"],"relearn":"Speak up, get them to safety, then tell an adult if it won't stop.","persona":"any","source":"upstander plan"},
  {"id":"nf-941","cat":"be-an-ally","type":"build","hook":"Build your set of quiet ally moves for shy days.","prompt":"Pick the low-risk ways to help.","pieces":["sit with the teased kid","share your snack","tell a trusted adult","film it for laughs"],"mode":"assemble","key":["sit with the teased kid","share your snack","tell a trusted adult"],"relearn":"Quiet allyship: sit with them, share, and tell an adult.","persona":"quiet child","source":"low-risk allyship"},
  {"id":"nf-942","cat":"be-an-ally","type":"build","hook":"Build the steps for checking in on someone after teasing stops.","prompt":"Put the kind steps in order.","pieces":["find them when it's calm","ask \"are you okay?\"","invite them to play","tell them it was their fault"],"mode":"sequence","key":["find them when it's calm","ask \"are you okay?\"","invite them to play"],"relearn":"Find them, ask if they're okay, and invite them in, never blame them.","persona":"any","source":"check-in / support"},
  {"id":"nf-943","cat":"be-an-ally","type":"build","hook":"Build a list of trusted people you could tell to keep a friend safe.","prompt":"Pick who counts as a trusted grown-up.","pieces":["a teacher like Mrs. Pillai","an older sibling like Sana","a parent","the kid who's teasing"],"mode":"assemble","key":["a teacher like Mrs. Pillai","an older sibling like Sana","a parent"],"relearn":"A teacher, older sibling, or parent are all trusted people to tell.","persona":"any","source":"trusted adult"},
  {"id":"nf-944","cat":"be-an-ally","type":"build","hook":"Build the ways to be an ally without ever confronting the teaser.","prompt":"Pick the no-confrontation moves.","pieces":["distract with a game","sit with the target","tell a trusted adult","shout back at the teaser"],"mode":"assemble","key":["distract with a game","sit with the target","tell a trusted adult"],"relearn":"You can distract, support, or tell, no confrontation needed.","persona":"quiet child","source":"low-risk allyship"},
  {"id":"nf-945","cat":"be-an-ally","type":"build","hook":"Build a kind reply for the \"can't you take a joke?\" dodge.","prompt":"Pick the words that hold your ground.","pieces":["\"It's not a joke if it hurts\"","\"He didn't laugh, so it's not funny\"","\"You can be funny without this\"","\"Fine, sorry I said anything\""],"mode":"assemble","key":["\"It's not a joke if it hurts\"","\"He didn't laugh, so it's not funny\"","\"You can be funny without this\""],"relearn":"You can answer the dodge: a joke that hurts isn't a joke.","persona":"Ananya","source":"upstander / just-a-joke"},
  {"id":"nf-946","cat":"be-an-ally","type":"match","hook":"Match each ally move to the moment it fits.","pairs":[{"left":"Teaser has a crowd","right":"Distract with a game"},{"left":"It won't stop after \"stop\"","right":"Tell a trusted adult"},{"left":"Target sits alone after","right":"Check in on them"},{"left":"You're too shy to speak","right":"Quietly sit beside them"},{"left":"A quick, clear put-down","right":"Say \"that's not kind\""}],"relearn":"Different moments call for different ally moves; any of them helps.","persona":"any","source":"upstander moves"},
  {"id":"nf-947","cat":"be-an-ally","type":"match","hook":"Match the two-word line to where it works.","pairs":[{"left":"\"Not funny\"","right":"A 'just a joke' put-down"},{"left":"\"Stop it\"","right":"Teasing that keeps going"},{"left":"\"Come play\"","right":"Inviting a left-out kid"},{"left":"\"You okay?\"","right":"Checking in after"},{"left":"\"Tell sir\"","right":"When it won't stop"}],"relearn":"Even two words, said calmly, can be a real ally move.","persona":"any","source":"upstander / voice"},
  {"id":"nf-948","cat":"be-an-ally","type":"match","hook":"Match each trusted person to how they can help.","pairs":[{"left":"Mrs. Pillai, the teacher","right":"Steps in during class"},{"left":"Sana, an older sibling","right":"Helps on the way home"},{"left":"A parent at home","right":"Listens and plans next steps"},{"left":"A coach at the ground","right":"Stops it during play"},{"left":"Childline 1098","right":"Helps if it keeps going"}],"relearn":"Many trusted people can help, telling them is reporting, not tattling.","persona":"any","source":"trusted adult"},
  {"id":"nf-949","cat":"be-an-ally","type":"match","hook":"Match the ally move to the kind result it can bring.","pairs":[{"left":"Standing beside the target","right":"They feel less alone"},{"left":"Speaking up calmly","right":"The teasing often stops"},{"left":"Telling a trusted adult","right":"Someone gets kept safe"},{"left":"Inviting them to play","right":"They feel welcome"},{"left":"Checking in after","right":"They know you care"}],"relearn":"Each ally move brings a kind result for the person being teased.","persona":"any","source":"support research"},
  {"id":"nf-950","cat":"be-an-ally","type":"match","hook":"Match the tricky moment to the ally move that fits a shy kid.","pairs":[{"left":"You're nervous to confront","right":"Tell a trusted adult"},{"left":"You can't find words","right":"Just sit with them"},{"left":"The crowd is loud","right":"Wait, then check in after"},{"left":"You want to include them","right":"Save them a seat"},{"left":"You feel braver with help","right":"Bring a friend along"}],"relearn":"Shy kids have plenty of ally moves; quiet help counts.","persona":"quiet child","source":"low-risk allyship"},
  {"id":"nf-951","cat":"be-an-ally","type":"match","hook":"Match what a teaser says to the calm, fair reply.","pairs":[{"left":"\"Can't you take a joke?\"","right":"\"Not if it hurts him\""},{"left":"\"It's not your problem\"","right":"\"Standing up is my business\""},{"left":"\"You're tattling\"","right":"\"Telling to keep him safe\""},{"left":"\"He throws like a girl\"","right":"\"Girls throw great\""},{"left":"\"Boys don't cry\"","right":"\"Everyone cries\""}],"relearn":"You can meet each dodge with a calm, fair reply that holds.","persona":"Ananya","source":"upstander / dodges"},
  {"id":"nf-952","cat":"be-an-ally","type":"match","hook":"Match each ally to the move they're known for.","pairs":[{"left":"Ananya, who notices","right":"Speaks up: \"not funny\""},{"left":"A shy classmate","right":"Sits quietly with the kid"},{"left":"Reyansh, the friend","right":"Tells a teaser to ease off"},{"left":"You, after it ends","right":"Checks in on the target"},{"left":"A kid who saw it","right":"Tells a trusted adult"}],"relearn":"There's an ally move for every kind of kid, including you.","persona":"any","source":"upstander moves"},
  {"id":"nf-953","cat":"be-an-ally","type":"match","hook":"Match the place to a quiet way you could help there.","pairs":[{"left":"On the school bus","right":"Move and sit beside them"},{"left":"In the class chat","right":"Don't pile on, message kindly"},{"left":"At the lunch line","right":"Save them a spot near you"},{"left":"On the playground","right":"Pull them into your game"},{"left":"Walking home","right":"Walk with them"}],"relearn":"Wherever teasing happens, there's a quiet ally move that fits.","persona":"quiet child","source":"everyday allyship"},
  {"id":"nf-954","cat":"be-an-ally","type":"sort","hook":"Sort: a safe ally move, or one that feeds the harm?","items":[{"id":"a","text":"Saying \"that's not kind\""},{"id":"b","text":"Sitting with the teased kid"},{"id":"c","text":"Telling a trusted adult"},{"id":"d","text":"Laughing with the teasers"},{"id":"e","text":"Filming it for laughs"},{"id":"f","text":"Egging the teaser on"}],"bins":[{"id":"ally","label":"Ally move","valence":"pos"},{"id":"harm","label":"Feeds harm","valence":"neg"}],"key":{"a":"ally","b":"ally","c":"ally","d":"harm","e":"harm","f":"harm"},"relearn":"Speak up, sit with them, tell an adult; laughing or filming feeds the harm.","persona":"any","source":"upstander moves"},
  {"id":"nf-955","cat":"be-an-ally","type":"sort","hook":"Sort: words that help a teased friend, or words that hurt more?","items":[{"id":"a","text":"\"That wasn't fair to you\""},{"id":"b","text":"\"Come sit with us\""},{"id":"c","text":"\"You okay?\""},{"id":"d","text":"\"You kind of asked for it\""},{"id":"e","text":"\"Just ignore it forever\""},{"id":"f","text":"\"It was your fault\""}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts more","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"helps","d":"hurts","e":"hurts","f":"hurts"},"relearn":"Kind words help; blaming the teased kid hurts, it's never their fault.","persona":"any","source":"support"},
  {"id":"nf-956","cat":"be-an-ally","type":"sort","hook":"Sort: a quiet ally move, or a loud one? Both are okay!","items":[{"id":"a","text":"Sitting beside the kid"},{"id":"b","text":"Sharing your snack"},{"id":"c","text":"Messaging them privately"},{"id":"d","text":"Shouting \"stop it!\""},{"id":"e","text":"Telling the teasers out loud"},{"id":"f","text":"Calling a teacher over"}],"bins":[{"id":"quiet","label":"Quiet move","valence":"neutral"},{"id":"loud","label":"Loud move","valence":"tell"}],"key":{"a":"quiet","b":"quiet","c":"quiet","d":"loud","e":"loud","f":"loud"},"relearn":"Quiet and loud ally moves both help; pick what fits you that day.","persona":"quiet child","source":"low-risk allyship"},
  {"id":"nf-957","cat":"be-an-ally","type":"sort","hook":"Sort: tell an adult, or careful, check first?","items":[{"id":"a","text":"It won't stop after \"stop\""},{"id":"b","text":"A kid is scared and hurt"},{"id":"c","text":"It's online every day"},{"id":"d","text":"Two friends, one silly laugh"},{"id":"e","text":"Everyone's grinning"},{"id":"f","text":"A joke both enjoyed"}],"bins":[{"id":"report","label":"Tell an adult","valence":"tell"},{"id":"careful","label":"Check first","valence":"uhoh"}],"key":{"a":"report","b":"report","c":"report","d":"careful","e":"careful","f":"careful"},"relearn":"If it won't stop or someone's hurt, tell an adult; if all are happy, check first.","persona":"any","source":"telling vs tattling"},
  {"id":"nf-958","cat":"be-an-ally","type":"sort","hook":"Sort: step in, or leave it be?","items":[{"id":"a","text":"A kid put down for his skin"},{"id":"b","text":"A classmate teased for crying"},{"id":"c","text":"A girl called \"bossy\" for leading"},{"id":"d","text":"Two friends, an inside joke"},{"id":"e","text":"A pun all laughed at together"},{"id":"f","text":"A game both kids enjoy"}],"bins":[{"id":"yours","label":"Step in","valence":"tell"},{"id":"not","label":"Leave it be","valence":"neutral"}],"key":{"a":"yours","b":"yours","c":"yours","d":"not","e":"not","f":"not"},"relearn":"Put-downs are your business to stop; shared fun where all are happy isn't.","persona":"Ananya","source":"bystander research"},
  {"id":"nf-959","cat":"be-an-ally","type":"sort","hook":"Sort: an ally's calm reply, or a teaser's dodge?","items":[{"id":"a","text":"\"It's not funny if it hurts\""},{"id":"b","text":"\"Telling keeps him safe\""},{"id":"c","text":"\"Let's just play instead\""},{"id":"d","text":"\"Can't you take a joke?\""},{"id":"e","text":"\"It's not my problem\""},{"id":"f","text":"\"I was only joking\""}],"bins":[{"id":"reply","label":"Ally reply","valence":"pos"},{"id":"dodge","label":"Teaser dodge","valence":"neg"}],"key":{"a":"reply","b":"reply","c":"reply","d":"dodge","e":"dodge","f":"dodge"},"relearn":"Calm fair replies stand up; \"only joking\" and \"not my problem\" are dodges.","persona":"any","source":"upstander / dodges"},
  {"id":"nf-990","cat":"fun-vs-mean","type":"sort","hook":"Lensy: 'still a joke' or 'stopped being one'?","items":[{"id":"a","text":"You both laugh, then move on"},{"id":"b","text":"They said stop, you stopped"},{"id":"c","text":"You teased once, checked they're okay"},{"id":"d","text":"They look upset, you keep going"},{"id":"e","text":"You say 'can't you take a joke?'"},{"id":"f","text":"You repeat it after they said stop"}],"bins":[{"id":"joke","label":"Still a joke","valence":"pos"},{"id":"stopped","label":"Stopped","valence":"neg"}],"key":{"a":"joke","b":"joke","c":"joke","d":"stopped","e":"stopped","f":"stopped"},"relearn":"If a joke stops being fun for the other person, it has stopped being one.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-991","cat":"fun-vs-mean","type":"sort","hook":"Sort: does this pass the two-question test, or fail it?","items":[{"id":"a","text":"Everyone's okay, and it stopped on ask"},{"id":"b","text":"Both smiling, no one's the target"},{"id":"c","text":"You checked: she's laughing too"},{"id":"d","text":"He's not okay, and it won't stop"},{"id":"e","text":"Only you find it funny, she's hurt"},{"id":"f","text":"You said stop, they kept teasing"}],"bins":[{"id":"pass","label":"Passes the test","valence":"pos"},{"id":"fail","label":"Fails the test","valence":"neg"}],"key":{"a":"pass","b":"pass","c":"pass","d":"fail","e":"fail","f":"fail"},"relearn":"The test: is everyone okay, and does it stop on ask?","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-992","cat":"fun-vs-mean","type":"branch","hook":"On the bus you copy a friend's funny voice and they laugh too.","options":[{"text":"Keep it light, stop if they look uneasy","consequence":"It stays fun for both; you read the moment.","outcome":"kind","best":true},{"text":"Do it louder so the bus laughs at them","consequence":"Now they're the target; the fun became a jab."}],"debrief":"A joke WITH a friend can tip into a joke AT them; watch their face.","relearn":"Stop the moment teasing stops being fun for the other person.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-993","cat":"fun-vs-mean","type":"branch","hook":"Your cousin teases your new haircut. You laugh, but a third time it stings.","options":[{"text":"Say \"okay, enough about the hair now\"","consequence":"A kind cousin eases off; you named your line.","outcome":"assertive","best":true},{"text":"Keep laughing so you don't seem touchy","consequence":"You can say when fun has gone far enough."}],"debrief":"Enjoy the first laugh and still call it when it's gone too long.","relearn":"You can name when teasing tips from fun into too much.","persona":"any","source":"assertiveness"},
  {"id":"nf-994","cat":"fun-vs-mean","type":"branch","hook":"A friend giggles at your drawing. You ask, and they say \"no, I love it!\"","options":[{"text":"Ask once more: \"WITH me or AT me?\"","consequence":"You learn it's friendly; you relax and laugh too.","outcome":"check","best":true},{"text":"Decide they're mean and storm off","consequence":"A quick check tells you if a laugh is fun or unkind."}],"debrief":"When unsure, the question 'with me or at me?' clears it up.","relearn":"You can ask if a laugh is WITH you or AT you before deciding.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-995","cat":"fun-vs-mean","type":"branch","hook":"Reyansh: at recess your gang riffs on a boy's lunch till he goes quiet.","options":[{"text":"Say \"he's not laughing, let's drop it\"","consequence":"The gang eases off; the boy isn't the punchline.","outcome":"kind","best":true},{"text":"Add a bigger lunch joke for the gang","consequence":"A laugh the target can't share is a jab, not a joke."}],"debrief":"If the person it's about isn't laughing, it's not a joke.","relearn":"A joke is only fun if it's fun for the person it's about.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-996","cat":"fun-vs-mean","type":"branch","hook":"Faizan: kids do your soft voice and laugh. You don't find it funny.","options":[{"text":"Say \"please stop, I don't like that\"","consequence":"Kind kids stop; you don't owe anyone a laugh.","outcome":"assertive","best":true},{"text":"Force a smile and feel small","consequence":"Not laughing just means you noticed it wasn't kind."}],"debrief":"Not laughing doesn't mean you can't take a joke.","relearn":"Not laughing means you noticed it wasn't kind, not that you can't take a joke.","persona":"Faizan-type","source":"self-advocacy"},
  {"id":"nf-997","cat":"fun-vs-mean","type":"branch","hook":"In the autorickshaw queue, your friend mimics a stutter for laughs.","options":[{"text":"Say \"that's not funny, that's mean\"","consequence":"You name it; the laugh at someone's cost stops.","outcome":"ally","best":true},{"text":"Laugh because everyone else did","consequence":"Laughing AT how someone talks is mean, not friendly."}],"debrief":"Mocking how someone speaks is laughing AT them: mean teasing.","relearn":"Mimicking how someone talks for a laugh is mean, not fun.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-998","cat":"fun-vs-mean","type":"branch","hook":"You and your sister have a teasing match; she suddenly says \"stop, really.\"","options":[{"text":"Stop right away and check she's okay","consequence":"You both stay friends; 'stop' is the real signal.","outcome":"kind","best":true},{"text":"Get one last dig in first","consequence":"Fun teasing stops the moment someone means 'stop'."}],"debrief":"The instant someone means 'stop', fun teasing has to stop.","relearn":"Fun teasing stops when asked; a dig after 'stop' makes it mean.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-999","cat":"fun-vs-mean","type":"branch","hook":"Reyansh: you've a sharp comeback ready to 'win' against a kid at school.","options":[{"text":"Aim it at the situation, not at him","consequence":"You still get the laugh; nobody's wounded.","outcome":"kind","best":true},{"text":"Land it on him so you 'win the argument'","consequence":"Winning by wounding isn't winning; it's just mean."}],"debrief":"You can be quick and funny without making a person the loser.","relearn":"You can be funny and quick with no person as the punchline.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-1000","cat":"fun-vs-mean","type":"branch","hook":"At a party, a game-joke about you gets everyone giggling, you too.","options":[{"text":"Laugh along; it's fun for you too","consequence":"Everyone's okay and smiling, you too: that's fun teasing.","outcome":"kind","best":true},{"text":"Check it's fun for you too","consequence":"Good check: fun for you too means fun teasing."}],"debrief":"When everyone, including you, is really laughing, teasing is fun.","relearn":"Fun teasing makes both laugh; if it's fun for you too, enjoy it.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1001","cat":"fun-vs-mean","type":"reflect","hook":"Lensy: what's the quickest way to know if teasing is fun or mean?","prompt":"Pick the clue you'd use.","options":["Look if they're really smiling","Notice if it stops when asked","Ask 'are you okay?'"],"affirm":"Great clues, all of them. The big one: is everyone okay, and does it stop?","relearn":"The test: is everyone okay, and does it stop when asked?","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1002","cat":"fun-vs-mean","type":"reflect","hook":"Reyansh: a joke that 'wins' the laugh but leaves a kid quiet, was it worth it?","prompt":"What do you think?","options":["Not really worth it","A kinder joke is better","I'd pick another joke"],"affirm":"A laugh that costs someone isn't worth it; the kind joke wins anyway.","relearn":"A laugh that hurts the person it's about isn't worth it.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-1003","cat":"fun-vs-mean","type":"reflect","hook":"Faizan: if you don't laugh at a dig, does that mean you 'can't take a joke'?","prompt":"What do you think?","options":["No, it just wasn't kind","I'm allowed to not laugh","It means I noticed"],"affirm":"Right, not laughing just means you noticed it wasn't kind. That's okay.","relearn":"Not laughing means you noticed it wasn't kind, not that you can't take a joke.","persona":"Faizan-type","source":"self-advocacy"},
  {"id":"nf-1004","cat":"fun-vs-mean","type":"reflect","hook":"Lensy: the best teasing leaves BOTH of you grinning. Want that kind?","prompt":"What do you think?","options":["Yes, both grinning","No one's hurt","That's the good kind"],"affirm":"Yes, fun teasing leaves both people grinning, with nobody as the target.","relearn":"Fun teasing leaves both people smiling; nobody is the target.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1005","cat":"fun-vs-mean","type":"reflect","hook":"Lensy: imagine the same joke aimed at YOU. Would it still feel fun?","prompt":"A good test?","options":["Yes, great test","Helps me check","I'll try it"],"affirm":"Imagining it aimed at you is a quick way to tell fun teasing from mean.","relearn":"Picture a joke aimed at you to check if it's fun or mean.","persona":"any","source":"empathy / perspective-taking"},
  {"id":"nf-1006","cat":"fun-vs-mean","type":"reflect","hook":"Lensy: real friends ease off the second teasing stings. Have friends like that?","prompt":"What do you think?","options":["Yes I do","That's a real friend","I want friends like that"],"affirm":"Real friends stop the moment it stops being fun. Those are the keepers.","relearn":"Real friends stop teasing the moment it hurts.","persona":"any","source":"friendship / teasing"},
  {"id":"nf-1007","cat":"fun-vs-mean","type":"reflect","hook":"Reyansh: 'just having a laugh' AND making sure no one's hurt, can you do both?","prompt":"What do you think?","options":["Yes, both","Fun and kind","That's the goal"],"affirm":"You can absolutely have a laugh and keep everyone okay at the same time.","relearn":"You can have a laugh and keep everyone okay at once.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1008","cat":"fun-vs-mean","type":"strike-rewrite","hook":"\"If everyone else laughed, it must have been funny.\"","myth":{"un":"If everyone else laughed, it must have been funny.","re":"A joke isn't fun unless it's fun for the person it's about, too.","why":"A crowd can laugh while one person is being hurt."},"relearn":"A whole crowd laughing doesn't make a joke fun for its target.","persona":"any","source":"impact over intent"},
  {"id":"nf-1009","cat":"fun-vs-mean","type":"strike-rewrite","hook":"\"Teasing that keeps going just means we're close.\"","myth":{"un":"Teasing that keeps going after 'stop' just means we're close.","re":"Fun teasing stops when asked; teasing that won't stop is mean.","why":"Closeness respects a 'stop'; mean teasing ignores it."},"relearn":"Fun teasing stops when asked; teasing that won't stop is mean.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1010","cat":"fun-vs-mean","type":"strike-rewrite","hook":"Reyansh: \"If I meant it as a joke, it can't be mean.\"","myth":{"un":"If I meant it as a joke, it can't be mean.","re":"What makes teasing fun is how it lands, not what you meant.","why":"A joke can be meant kindly and still land as a hurt."},"relearn":"Whether teasing is fun depends on how it lands, not just what you meant.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-1011","cat":"fun-vs-mean","type":"strike-rewrite","hook":"\"A funny nickname is fine even if they hate it.\"","myth":{"un":"A funny nickname is fine even if the person hates it.","re":"A nickname is only fun if the person it's for likes it too.","why":"If it stings them, it's stopped being a shared joke."},"relearn":"A nickname is only fun teasing if the person it's about likes it too.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1012","cat":"fun-vs-mean","type":"strike-rewrite","hook":"\"You have to roast people to be the funny one.\"","myth":{"un":"You have to roast people to be the funny one.","re":"The funniest jokes laugh WITH people and need no target.","why":"Wit that includes everyone lands better than a put-down."},"relearn":"The funniest jokes laugh WITH people, not AT them.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1013","cat":"fun-vs-mean","type":"role-play","hook":"Friends keep teasing you about your specs and it's gone past fun.","setup":"Name your line. Say:","yourLine":[{"text":"\"That was funny once, but it's enough now.\"","best":true},{"text":"\"Whatever, keep going then.\""}],"relearn":"You can enjoy the first laugh and still say when it's enough.","persona":"any","source":"assertiveness / voice"},
  {"id":"nf-1014","cat":"fun-vs-mean","type":"role-play","hook":"You did a friend's accent for a laugh and they stopped smiling.","setup":"Repair it fast. Say:","yourLine":[{"text":"\"Sorry, that wasn't kind, I'll stop.\"","best":true},{"text":"\"Relax, can't you take a joke?\""}],"relearn":"If your joke stops being fun for someone, checking in beats doubling down.","persona":"Reyansh","source":"repair / voice"},
  {"id":"nf-1015","cat":"fun-vs-mean","type":"role-play","hook":"A kid teases another in your group and the teasing won't stop.","setup":"Say the kind, clear line:","yourLine":[{"text":"\"They said stop, so let's stop.\"","best":true},{"text":"A quiet laugh"}],"relearn":"Fun teasing stops when asked; you can be the one who says so.","persona":"Ananya","source":"upstander / voice"},
  {"id":"nf-1016","cat":"fun-vs-mean","type":"match","hook":"Match each teasing moment to fun or mean.","pairs":[{"left":"Both laughing, then it stops","right":"Fun teasing"},{"left":"A dig that won't quit after 'stop'","right":"Mean teasing"},{"left":"An inside joke you share","right":"Laughing WITH"},{"left":"Making one kid the punchline","right":"Laughing AT"},{"left":"You check the other kid is okay","right":"A kind move"}],"relearn":"Fun teasing makes both laugh and stops when asked; mean teasing aims to hurt.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1017","cat":"fun-vs-mean","type":"match","hook":"Match each clue to what it tells you about teasing.","pairs":[{"left":"It stopped the moment I asked","right":"It was fun teasing"},{"left":"It kept going after 'stop'","right":"It was mean teasing"},{"left":"Everyone, even the target, is grinning","right":"A joke WITH them"},{"left":"Only the teaser is laughing","right":"A joke AT them"},{"left":"I didn't laugh","right":"I noticed it wasn't kind"}],"relearn":"The test: is everyone okay, and does it stop when asked?","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1018","cat":"fun-vs-mean","type":"build","hook":"Build your 'is it fun teasing?' checklist.","prompt":"Pick the questions that tell you teasing is fun, not mean.","pieces":["Is everyone okay?","Does it stop when asked?","Are we laughing WITH them?","Did everyone, even them, smile?","Did it keep going after 'stop'?"],"mode":"assemble","key":["Is everyone okay?","Does it stop when asked?","Are we laughing WITH them?","Did everyone, even them, smile?"],"relearn":"Fun-teasing checklist: everyone okay, stops when asked, laughing WITH, all smiling.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1019","cat":"fun-vs-mean","type":"build","hook":"Build the order of a fun joke that doesn't tip into mean.","prompt":"Put the steps in order.","pieces":["Make a light, shared joke","Watch their face","If they look hurt, stop","Check in: 'you okay?'"],"mode":"sequence","key":["Make a light, shared joke","Watch their face","If they look hurt, stop","Check in: 'you okay?'"],"relearn":"Joke lightly, watch their face, stop if it stings, then check in.","persona":"any","source":"teasing vs bullying"},
  {"id":"nf-1081","cat":"gender-teasing","type":"strike-rewrite","hook":"\"He cried at the film, what a girl!\"","myth":{"un":"Crying makes a boy 'a girl', which is something to mock.","re":"Everyone cries; crying isn't a 'girl thing' or a put-down.","why":"Feelings have no gender, and a gender is never an insult."},"relearn":"Crying isn't a 'girl thing'; teasing it isn't fair or funny.","persona":"Faizan-type","source":"gender teasing"},
  {"id":"nf-1082","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Boys can't wear bangles, only girls can.\"","myth":{"un":"Bangles and bindis are only 'for girls'.","re":"Anyone can wear bangles or colours they love; clothes have no gender.","why":"'For girls' and 'for boys' are just things people say, not facts."},"relearn":"Clothes and colours aren't 'boy' or 'girl' only; anyone can enjoy them.","persona":"Faizan-type","source":"gender norms"},
  {"id":"nf-1083","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Pink is a girls' colour, boys who like it are weird.\"","myth":{"un":"Pink is a 'girls' colour' and weird for boys.","re":"A boy can love pink and be completely fine as he is.","why":"A colour can't belong to a gender; it's just a colour."},"relearn":"Pink isn't a 'girl colour'; anyone can love any colour.","persona":"Faizan-type","source":"gender norms (Faizan)"},
  {"id":"nf-1084","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Cooking and kitchen work is girls' stuff.\"","myth":{"un":"Cooking is 'girls' stuff' and a boy who likes it is odd.","re":"Boys cook brilliantly too; the best chefs are all genders.","why":"A skill isn't a gender; cooking is for whoever enjoys it."},"relearn":"Cooking isn't only for girls; anyone can love it.","persona":"Reyansh","source":"gender norms"},
  {"id":"nf-1085","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Don't be a sissy, man up!\"","myth":{"un":"A scared or gentle boy should 'man up' and stop being a 'sissy'.","re":"Being gentle or scared is human; no boy needs to 'man up'.","why":"There's no one way to be a boy; kindness isn't weakness."},"relearn":"'Man up' isn't fair; gentle and scared are fine for anyone.","persona":"Faizan-type","source":"gender teasing"},
  {"id":"nf-1086","cat":"gender-teasing","type":"strike-rewrite","hook":"\"She's good at maths? But she's a girl!\"","myth":{"un":"Girls aren't really meant to be good at maths.","re":"Girls are brilliant at maths; being a girl says nothing about it.","why":"Talent isn't decided by gender, only by practice and interest."},"relearn":"Girls are great at maths; gender doesn't decide who's good.","persona":"Ananya","source":"gender norms"},
  {"id":"nf-1087","cat":"gender-teasing","type":"strike-rewrite","hook":"\"You're so fair, you must be the pretty one.\"","myth":{"un":"Fair skin is what makes someone pretty.","re":"Every skin shade is lovely; fairness doesn't make anyone 'prettier'.","why":"Ranking skin by shade is a put-down, not a compliment."},"relearn":"Every skin shade is beautiful; fairness isn't 'better'.","persona":"any","source":"colourism (links g06)"},
  {"id":"nf-1088","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Girls shouldn't climb trees, that's for boys.\"","myth":{"un":"Climbing and rough play is 'for boys', not girls.","re":"Girls climb, run and play rough just as well; play has no gender.","why":"'For boys' is just a rule someone made up, not a fact."},"relearn":"Climbing and rough play aren't 'for boys'; anyone can.","persona":"Ananya","source":"gender norms"},
  {"id":"nf-1089","cat":"gender-teasing","type":"strike-rewrite","hook":"\"He plays with dolls, ha, what a baby girl.\"","myth":{"un":"A boy playing with dolls is babyish and 'girly'.","re":"Dolls help kids practise caring; any child can love them.","why":"Toys aren't 'boy' or 'girl', and caring is a great skill."},"relearn":"Dolls aren't only for girls; caring play is good for anyone.","persona":"Faizan-type","source":"gender norms"},
  {"id":"nf-1090","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Girls can't be class monitor, they get too bossy.\"","myth":{"un":"Girls who lead are 'bossy' and shouldn't be monitor.","re":"A girl leading is a good leader, not 'bossy'.","why":"We praise boys for leading and call girls 'bossy' for the same thing."},"relearn":"Leading isn't 'bossy'; girls make great leaders.","persona":"Ananya","source":"gender teasing"},
  {"id":"nf-1093","cat":"gender-teasing","type":"strike-rewrite","hook":"\"You're too dark, stand at the back for the photo.\"","myth":{"un":"Darker-skinned kids should hide at the back of a photo.","re":"Every shade belongs in the front; no skin is 'too dark'.","why":"Pushing someone back for their skin is a put-down, not a joke."},"relearn":"No skin is 'too dark'; everyone belongs in the picture.","persona":"any","source":"colourism (links g06)"},
  {"id":"nf-1094","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Stop being a drama queen about it.\"","myth":{"un":"A girl who speaks up about feeling hurt is just a 'drama queen'.","re":"Naming hurt isn't drama; it's honest and brave.","why":"'Drama queen' is used to silence girls who say something's wrong."},"relearn":"Speaking up about hurt isn't 'drama'; it's fair and brave.","persona":"Ananya","source":"gender teasing"},
  {"id":"nf-1097","cat":"gender-teasing","type":"branch","hook":"A boy hears \"you run like a girl!\" and slows down, sad.","options":[{"text":"Say \"like a girl is fast, look at the sprinters!\"","consequence":"He smiles and speeds up again.","outcome":"ally","best":true},{"text":"Laugh along","consequence":"He feels small and stops trying."}],"debrief":"'Like a girl' is meant as an insult but isn't one, because girls are brilliant; naming that takes its sting away.","relearn":"'Like a girl' means fast and skilled; it's no insult.","persona":"Ananya","source":"gender teasing"},
  {"id":"nf-1098","cat":"gender-teasing","type":"branch","hook":"Reyansh fears bringing his pink bottle: \"that's a girl bottle.\"","options":[{"text":"Bring it; say \"it's just a colour I like\"","consequence":"He stands by what he likes; kids shrug it off.","outcome":"ally","best":true},{"text":"Hide it, bring a 'boy' colour","consequence":"He drops something he loves over a made-up rule."}],"debrief":"Colours aren't 'boy' or 'girl'; liking pink is completely fine.","relearn":"A colour can't belong to a gender; like what you like.","persona":"Reyansh","source":"gender norms (Faizan-thread)"},
  {"id":"nf-1099","cat":"gender-teasing","type":"branch","hook":"A girl is told \"girls can't be cricket captain\" at recess.","options":[{"text":"Say \"she's the best player, she should captain\"","consequence":"The team agrees; skill picks the captain.","outcome":"ally","best":true},{"text":"Agree girls shouldn't captain","consequence":"A made-up rule benches a good captain."}],"debrief":"Captains are chosen for skill and fairness, never for gender.","relearn":"Girls can captain any team; gender doesn't decide it.","persona":"Ananya","source":"gender teasing"},
  {"id":"nf-1100","cat":"gender-teasing","type":"branch","hook":"Kids chant \"Faizan loves rangoli, he's a girl!\" as he draws.","options":[{"text":"Say \"rangoli's art, anyone can make it\"","consequence":"He keeps drawing proudly; the chant fizzles.","outcome":"ally","best":true},{"text":"Tell him to stop so they'll quit","consequence":"He drops something he loves to dodge teasing."}],"debrief":"Art and rangoli aren't 'girl' things; Faizan is fine as he is.","relearn":"Liking art isn't 'girly'; anyone can love making it.","persona":"Faizan-type","source":"gender norms"},
  {"id":"nf-1102","cat":"gender-teasing","type":"branch","hook":"A girl is called \"too dark\" by a classmate during PT.","options":[{"text":"Say \"every skin colour's great, don't say that\"","consequence":"She feels backed up; the jab stops.","outcome":"ally","best":true},{"text":"Tell her to just ignore it","consequence":"She's left to carry the hurt alone."}],"debrief":"Teasing skin colour is a put-down; every shade is beautiful.","relearn":"No skin is 'too dark'; colourist jabs aren't jokes.","persona":"Ananya","source":"colourism / ally (links g06)"},
  {"id":"nf-1103","cat":"gender-teasing","type":"branch","hook":"Boys won't let a girl join football: \"go do skipping.\"","options":[{"text":"Say \"she's quick, let her play, it's for everyone\"","consequence":"She joins in and scores a goal.","outcome":"ally","best":true},{"text":"Tell her to find a 'girl game'","consequence":"A made-up split keeps a good player out."}],"debrief":"Games aren't split into 'boy' and 'girl'; everyone can join.","relearn":"Football is for everyone; don't split games by gender.","persona":"Ananya","source":"gender norms"},
  {"id":"nf-1106","cat":"gender-teasing","type":"branch","hook":"A girl is mocked for a loud, confident voice: \"total tomboy.\"","options":[{"text":"Say \"speaking up clearly is a good thing\"","consequence":"She keeps her confidence; the label loses power.","outcome":"ally","best":true},{"text":"Tell her to be 'more ladylike'","consequence":"She shrinks her voice to fit a made-up mould."}],"debrief":"Being loud and confident isn't a 'boy' or 'girl' trait to mock.","relearn":"A confident voice is great; it's no put-down.","persona":"Ananya","source":"gender norms"},
  {"id":"nf-1107","cat":"gender-teasing","type":"role-play","hook":"A friend is teased: \"sewing? that's for girls, why do YOU do it?\"","setup":"Back them up. Say:","yourLine":[{"text":"\"Sewing's a cool skill, anyone can learn it.\"","best":true},{"text":"Laugh along"}],"persona":"any","source":"gender stereotypes","relearn":"Sewing is a skill anyone can learn; hobbies have no gender."},
  {"id":"nf-1108","cat":"gender-teasing","type":"role-play","hook":"Someone snaps at a girl who's organising the game: \"stop being so bossy!\"","setup":"Reframe it for her. Say:","yourLine":[{"text":"\"She's not bossy, she's a good leader.\"","best":true},{"text":"Mutter that she is a bit bossy"}],"persona":"Ananya","source":"bias / leadership","relearn":"A girl who organises the game is a leader, not 'bossy'."},
  {"id":"nf-1109","cat":"gender-teasing","type":"role-play","hook":"Kids laugh at a boy crying after a fall: \"baby! boys don't cry!\"","setup":"Stand with him. Say:","yourLine":[{"text":"\"Everyone cries, that's totally normal.\"","best":true},{"text":"Snigger with them"}],"persona":"any","source":"boys-dont-cry myth","relearn":"Everyone cries; it's normal, not a 'girl' thing."},
  {"id":"nf-1111","cat":"gender-teasing","type":"role-play","hook":"Someone teases your friend's dark skin as a 'joke' at the bus stop.","setup":"Shut it down, kindly. Say:","yourLine":[{"text":"\"Every skin colour's great, that's not funny.\"","best":true},{"text":"Look away and say nothing"}],"persona":"any","source":"colourism","relearn":"Every skin colour is great; a 'joke' about it isn't funny."},
  {"id":"nf-1112","cat":"gender-teasing","type":"role-play","hook":"A boy says \"I want to do garba this year\" and a cousin scoffs \"that's girly!\"","setup":"Encourage him. Say:","yourLine":[{"text":"\"Garba's for everyone, go for it!\"","best":true},{"text":"Tell him maybe he shouldn't"}],"persona":"any","source":"gender stereotypes","relearn":"Garba is for everyone; cheer a boy on, don't scoff."},
  {"id":"nf-1113","cat":"gender-teasing","type":"role-play","hook":"A classmate calls a girl who fixed the cycle \"weird, that's a boy thing.\"","setup":"Set it straight. Say:","yourLine":[{"text":"\"Fixing things is for anyone, nice work!\"","best":true},{"text":"Agree it's a 'boy thing'"}],"persona":"Ananya","source":"gender stereotypes","relearn":"Fixing things is for anyone, not a 'boy thing'."},
  {"id":"nf-1114","cat":"gender-teasing","type":"role-play","hook":"Someone tells a quiet boy \"you talk softly like a girl, ha.\"","setup":"Back him up. Say:","yourLine":[{"text":"\"A soft voice is fine, it's not a 'girl' thing.\"","best":true},{"text":"Copy the soft voice to mock him"}],"persona":"any","source":"gender stereotypes","relearn":"A soft voice is fine and isn't a 'girl' thing to mock."},
  {"id":"nf-1115","cat":"gender-teasing","type":"role-play","hook":"A girl is told \"don't do science club, girls aren't into that.\"","setup":"Speak up for her. Say:","yourLine":[{"text":"\"Girls are great at science, join us!\"","best":true},{"text":"Say maybe it's not for her"}],"persona":"Ananya","source":"gender stereotypes","relearn":"Girls are great at science; invite her in, don't push her out."},
  {"id":"nf-1117","cat":"gender-teasing","type":"reflect","hook":"Lensy: when someone says \"that's for girls\" or \"that's for boys\"... is it a real rule?","prompt":"What do you think?","options":["No, just something people say","Toys and games are for everyone","Nobody owns a colour or a game"],"affirm":"Right, 'boy stuff' and 'girl stuff' are made up; anyone can like anything.","persona":"any","source":"gender stereotypes","relearn":"'Boy stuff' and 'girl stuff' are made up; anyone can like anything."},
  {"id":"nf-1118","cat":"gender-teasing","type":"reflect","hook":"Lensy: a friend is teased with 'you're such a girl'. How might they feel?","prompt":"Pick what fits.","options":["Hurt and small","Like they should hide what they like","Sad that a gender is used to mock"],"affirm":"It stings, and it quietly tells every girl she's an insult. We can do better.","persona":"any","source":"gender put-downs","relearn":"'You're such a girl' stings and tells every girl she's an insult."},
  {"id":"nf-1119","cat":"gender-teasing","type":"reflect","hook":"Lensy: what makes 'like a girl' stop sounding like an insult?","prompt":"Pick your idea.","options":["Remembering girls are brilliant","Saying it back with pride","Knowing a gender isn't an insult"],"affirm":"Yes, the moment we see girls as great, 'like a girl' has no sting left.","persona":"any","source":"gender put-downs","relearn":"Once we see girls as brilliant, 'like a girl' has no sting left."},
  {"id":"nf-1120","cat":"gender-teasing","type":"reflect","hook":"Lensy: a 'joke' about someone's skin colour, who does it hurt?","prompt":"What do you think?","options":["The kid teased","Everyone with that skin shade","Lots of people, quietly"],"affirm":"It hurts the kid AND tells a whole group their shade is 'less'. Not okay.","persona":"any","source":"colourism","relearn":"A 'joke' about skin colour hurts the kid and a whole group quietly."},
  {"id":"nf-1121","cat":"gender-teasing","type":"reflect","hook":"Lensy: a boy says pink is his favourite. What's the kind thing to think?","prompt":"Pick one.","options":["Cool, colours are for everyone","Nice, he likes what he likes","No colour belongs to a gender"],"affirm":"Exactly, a colour can't be 'a girl's' or 'a boy's'. Like what you love.","persona":"any","source":"colours / gender","relearn":"No colour belongs to a gender; like what you love."},
  {"id":"nf-1122","cat":"gender-teasing","type":"reflect","hook":"Lensy: a girl gets called 'bossy' for leading the game. Fair?","prompt":"What do you think?","options":["No, leading isn't a flaw","Boys get praised for the same thing","She's a leader, not 'bossy'"],"affirm":"Right, 'bossy' is often just 'leading while a girl'. Leading is good.","persona":"Ananya","source":"bias / leadership","relearn":"'Bossy' is often just 'leading while a girl'; leading is good."},
  {"id":"nf-1123","cat":"gender-teasing","type":"reflect","hook":"Lensy: someone says 'boys don't cry'. Is that true?","prompt":"Pick what feels right.","options":["No, everyone cries","Crying is healthy for anyone","Tears aren't a 'girl' thing"],"affirm":"True, everyone cries, and teasing a boy for it isn't fair or funny.","persona":"any","source":"boys-dont-cry myth","relearn":"Everyone cries; tears aren't a 'girl' thing."},
  {"id":"nf-1124","cat":"gender-teasing","type":"sort","hook":"Sort: a kind comment, or a gender put-down dressed as a joke?","items":[{"id":"a","text":"\"Cool kick, nice goal!\""},{"id":"b","text":"\"You throw like a girl, haha\""},{"id":"c","text":"\"Want to be on my team?\""},{"id":"d","text":"\"Boys don't cry, baby\""},{"id":"e","text":"\"That was a smart move!\""},{"id":"f","text":"\"Pink? are you a girl or what\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"putdown","label":"Gender put-down","valence":"neg"}],"key":{"a":"kind","b":"putdown","c":"kind","d":"putdown","e":"kind","f":"putdown"},"relearn":"'Like a girl', 'boys don't cry' and colour jabs are put-downs, not jokes.","persona":"any","source":"gender teasing"},
  {"id":"nf-1125","cat":"gender-teasing","type":"sort","hook":"Sort: a fair thing to say, or a put-down about looks or skin?","items":[{"id":"a","text":"\"I love your new shoes!\""},{"id":"b","text":"\"You're too dark to look nice\""},{"id":"c","text":"\"Great drawing!\""},{"id":"d","text":"\"Your nose is so funny, ha\""},{"id":"e","text":"\"You did really well today\""},{"id":"f","text":"\"Why are you so fat\""}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"putdown","label":"Put-down","valence":"neg"}],"key":{"a":"fair","b":"putdown","c":"fair","d":"putdown","e":"fair","f":"putdown"},"relearn":"Jabs about skin, looks or bodies aren't jokes; they're put-downs.","persona":"any","source":"appearance / colourism (links g06)"},
  {"id":"nf-1126","cat":"gender-teasing","type":"sort","hook":"Sort: is this for everyone, or a made-up 'only boys / only girls' rule?","items":[{"id":"a","text":"\"Anyone can play cricket\""},{"id":"b","text":"\"Only girls can dance\""},{"id":"c","text":"\"Any kid can like cooking\""},{"id":"d","text":"\"Boys only for science club\""},{"id":"e","text":"\"Everyone can wear bright colours\""},{"id":"f","text":"\"Dolls are just for girls\""}],"bins":[{"id":"all","label":"For everyone","valence":"pos"},{"id":"madeup","label":"Made-up rule","valence":"neg"}],"key":{"a":"all","b":"madeup","c":"all","d":"madeup","e":"all","f":"madeup"},"relearn":"'Only boys' / 'only girls' are made-up rules; activities are for everyone.","persona":"any","source":"gender norms"},
  {"id":"nf-1127","cat":"gender-teasing","type":"sort","hook":"Sort: backing a friend up, or piling on the gender teasing?","items":[{"id":"a","text":"\"Anyone can like that, it's cool\""},{"id":"b","text":"\"Haha, that's so girly\""},{"id":"c","text":"\"Don't listen to them, you're fine\""},{"id":"d","text":"\"Yeah, real boys don't do that\""},{"id":"e","text":"\"Want to sit with me?\""},{"id":"f","text":"\"Ladka hokar yeh karta hai!\""}],"bins":[{"id":"ally","label":"Backing up","valence":"tell"},{"id":"piling","label":"Piling on","valence":"neg"}],"key":{"a":"ally","b":"piling","c":"ally","d":"piling","e":"ally","f":"piling"},"relearn":"Allies back a friend up; piling on uses gender as the insult.","persona":"any","source":"ally / gender teasing"},
  {"id":"nf-1128","cat":"gender-teasing","type":"sort","hook":"Sort: a true thing about gender, or a myth someone made up?","items":[{"id":"a","text":"\"Anyone can be brave\""},{"id":"b","text":"\"Girls are bad at maths\""},{"id":"c","text":"\"Everyone can be gentle\""},{"id":"d","text":"\"Boys must be tough always\""},{"id":"e","text":"\"All kids feel scared sometimes\""},{"id":"f","text":"\"Girls can't lead\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Made-up myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Gender myths ('girls can't', 'boys must') aren't facts; people are people.","persona":"any","source":"gender norms"},
  {"id":"nf-1129","cat":"gender-teasing","type":"sort","hook":"Sort: a real compliment, or a sneaky put-down?","items":[{"id":"a","text":"\"You're really good at this\""},{"id":"b","text":"\"Not bad, for a girl\""},{"id":"c","text":"\"You're so kind\""},{"id":"d","text":"\"Strong, like a real boy\""},{"id":"e","text":"\"Brilliant catch!\""},{"id":"f","text":"\"Pretty, even with dark skin\""}],"bins":[{"id":"real","label":"Real compliment","valence":"pos"},{"id":"sneaky","label":"Sneaky put-down","valence":"neg"}],"key":{"a":"real","b":"sneaky","c":"real","d":"sneaky","e":"real","f":"sneaky"},"relearn":"'For a girl' or 'even with dark skin' sneaks a put-down into praise.","persona":"any","source":"gender teasing / colourism"},
  {"id":"nf-1130","cat":"gender-teasing","type":"sort","hook":"Sort: a kind way to react, or a gender put-down, to a crying boy?","items":[{"id":"a","text":"\"It's okay to cry, I'm here\""},{"id":"b","text":"\"Stop being such a girl\""},{"id":"c","text":"\"Take your time, no rush\""},{"id":"d","text":"\"Baby! boys don't cry\""},{"id":"e","text":"\"Want to talk about it?\""},{"id":"f","text":"\"Man up, don't be soft\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"putdown","label":"Gender put-down","valence":"neg"}],"key":{"a":"kind","b":"putdown","c":"kind","d":"putdown","e":"kind","f":"putdown"},"relearn":"'Like a girl', 'boys don't cry' and 'man up' are put-downs, not comfort.","persona":"any","source":"gender teasing (links g01)"},
  {"id":"nf-1131","cat":"gender-teasing","type":"build","hook":"Build a kind reply when a friend is teased \"you play like a girl!\"","prompt":"Pick the lines that make a kind, clear comeback.","pieces":["\"Girls play brilliantly\"","\"so that's no insult\"","\"you should quit then\"","\"haha yeah you're bad\"","\"keep playing, you're good\""],"mode":"assemble","key":["\"Girls play brilliantly\"","\"so that's no insult\"","\"keep playing, you're good\""],"persona":"any","source":"gender put-downs","relearn":"Reply to 'you play like a girl': girls play brilliantly, so keep playing."},
  {"id":"nf-1132","cat":"gender-teasing","type":"build","hook":"Build the truth about colours and gender from these pieces.","prompt":"Pick the pieces that make a true sentence.","pieces":["A colour","has no gender","belongs only to girls","anyone can love it","is for boys only"],"mode":"assemble","key":["A colour","has no gender","anyone can love it"],"persona":"any","source":"colours / gender","relearn":"A colour has no gender; anyone can love it."},
  {"id":"nf-1133","cat":"gender-teasing","type":"build","hook":"Build your plan for when a friend is hit with a gender put-down.","prompt":"Pick the upstander steps, in order.","pieces":["name it: 'that's not okay'","support the friend after","join the teasing","tell a trusted grown-up if it keeps on"],"mode":"sequence","key":["name it: 'that's not okay'","support the friend after","tell a trusted grown-up if it keeps on"],"persona":"any","source":"upstander steps","relearn":"Name it, support the friend, then tell a grown-up if it keeps on."},
  {"id":"nf-1134","cat":"gender-teasing","type":"build","hook":"Build a true reply to 'boys don't cry'.","prompt":"Pick the pieces that make it true.","pieces":["Everyone cries","feelings have no gender","so it's healthy","only girls cry","and weak boys"],"mode":"assemble","key":["Everyone cries","feelings have no gender","so it's healthy"],"persona":"any","source":"boys-dont-cry myth","relearn":"Everyone cries; feelings have no gender, so it's healthy."},
  {"id":"nf-1135","cat":"gender-teasing","type":"build","hook":"Build the line that stands up to a colourist 'joke'.","prompt":"Pick the kind, clear pieces.","pieces":["Every skin shade","is beautiful","that's not funny","is ugly though","laugh it off"],"mode":"assemble","key":["Every skin shade","is beautiful","that's not funny"],"persona":"any","source":"colourism","relearn":"Every skin shade is beautiful; that 'joke' isn't funny."},
  {"id":"nf-1136","cat":"gender-teasing","type":"build","hook":"Build why 'that's so girly' isn't actually an insult.","prompt":"Pick the pieces that explain it.","pieces":["'Girly' isn't an insult","girls' things aren't lesser","anyone can like them","because girls are bad","so avoid it"],"mode":"assemble","key":["'Girly' isn't an insult","girls' things aren't lesser","anyone can like them"],"persona":"any","source":"gender put-downs","relearn":"'Girly' isn't an insult; girls' things aren't lesser and anyone can like them."},
  {"id":"nf-1137","cat":"gender-teasing","type":"build","hook":"Build the plan when a boy is teased for joining dance class.","prompt":"Pick the kind steps, in order.","pieces":["tell him 'dance is for everyone'","cheer him on at the show","laugh with the teasers","check he's okay after"],"mode":"sequence","key":["tell him 'dance is for everyone'","cheer him on at the show","check he's okay after"],"persona":"any","source":"upstander steps","relearn":"Tell him dance is for everyone, cheer him on, then check he's okay."},
  {"id":"nf-1138","cat":"gender-teasing","type":"build","hook":"Build the truth that 'girls can't lead' is a myth.","prompt":"Pick the pieces that make it true.","pieces":["Girls make great leaders","'bossy' is unfair","leading isn't a flaw","girls are too soft","so let boys lead"],"mode":"assemble","key":["Girls make great leaders","'bossy' is unfair","leading isn't a flaw"],"persona":"Ananya","source":"bias / leadership","relearn":"Girls make great leaders; 'bossy' is unfair and leading isn't a flaw."},
  {"id":"nf-1139","cat":"gender-teasing","type":"match","hook":"Match each gender put-down to the kind truth that answers it.","pairs":[{"left":"\"You throw like a girl\"","right":"Girls throw brilliantly"},{"left":"\"Boys don't cry\"","right":"Everyone cries, it's healthy"},{"left":"\"That's so girly\"","right":"Anyone can like anything"},{"left":"\"She's so bossy\"","right":"She's a good leader"},{"left":"\"You're too dark\"","right":"Every shade is beautiful"}],"persona":"any","source":"gender put-downs","relearn":"Each gender put-down has a kind truth that answers it."},
  {"id":"nf-1140","cat":"gender-teasing","type":"match","hook":"Match each kid's interest to the kind thing to say about it.","pairs":[{"left":"Boy loves cooking","right":"Cooking's a great skill for anyone"},{"left":"Girl plays football","right":"Football's for everyone"},{"left":"Boy likes pink","right":"Colours have no gender"},{"left":"Girl fixes a cycle","right":"Fixing things is for anyone"},{"left":"Boy does rangoli","right":"Art is for everyone"}],"persona":"any","source":"gender stereotypes","relearn":"Any interest fits any kid; there's a kind thing to say about each."},
  {"id":"nf-1141","cat":"gender-teasing","type":"match","hook":"Match the teasing line to who it quietly puts down.","pairs":[{"left":"\"Like a girl!\"","right":"Every girl, all at once"},{"left":"\"Too dark, na\"","right":"Everyone with that shade"},{"left":"\"Real boys don't\"","right":"Boys who are gentle"},{"left":"\"What a tomboy\"","right":"Girls who are confident"},{"left":"\"So girly\"","right":"Anyone who likes 'girls' things"}],"persona":"any","source":"gender put-downs","relearn":"Each teasing line quietly puts down a whole group, not just one kid."},
  {"id":"nf-1142","cat":"gender-teasing","type":"match","hook":"Match the put-down to the upstander move that fits best.","pairs":[{"left":"Teasing 'like a girl'","right":"Say 'that's no insult'"},{"left":"Mocking a crying boy","right":"Sit with him, say it's okay"},{"left":"It won't stop teasing","right":"Tell a trusted grown-up"},{"left":"A colourist 'joke'","right":"Say 'every shade is great'"},{"left":"Calling a girl 'bossy'","right":"Reframe: 'she's a leader'"}],"persona":"any","source":"upstander moves","relearn":"Each put-down has an upstander move that fits it."},
  {"id":"nf-1143","cat":"gender-teasing","type":"match","hook":"Match the made-up rule to why it isn't true.","pairs":[{"left":"\"Pink is for girls\"","right":"Colours have no gender"},{"left":"\"Girls can't do maths\"","right":"Girls are brilliant at maths"},{"left":"\"Cooking is girls' work\"","right":"Anyone can cook"},{"left":"\"Boys must be tough\"","right":"Boys can be gentle too"},{"left":"\"Dance is girly\"","right":"Dance is for everyone"}],"persona":"any","source":"gender myths","relearn":"Each made-up gender rule has a reason it isn't true."},
  {"id":"nf-1144","cat":"gender-teasing","type":"match","hook":"Match each kind comment to the put-down it replaces.","pairs":[{"left":"\"Great catch!\"","right":"instead of \"not bad for a girl\""},{"left":"\"Cool colour!\"","right":"instead of \"that's a girl colour\""},{"left":"\"You lead well\"","right":"instead of \"so bossy\""},{"left":"\"It's okay to cry\"","right":"instead of \"boys don't cry\""},{"left":"\"Your skin's lovely\"","right":"instead of \"you're too dark\""}],"persona":"any","source":"gender put-downs","relearn":"Each kind comment can replace a gender put-down."},
  {"id":"nf-1145","cat":"gender-teasing","type":"match","hook":"Match each line to whether it's kind or a gender put-down.","pairs":[{"left":"\"Anyone can play\"","right":"Kind and fair"},{"left":"\"Like a girl, ha\"","right":"Gender put-down"},{"left":"\"Nice work today\"","right":"A real compliment"},{"left":"\"Don't be a sissy\"","right":"A boy put-down"},{"left":"\"Want to join in?\"","right":"A warm invite"}],"persona":"any","source":"kind vs put-down","relearn":"Some lines are kind and fair; others are gender put-downs."},
  {"id":"nf-1146","cat":"gender-teasing","type":"match","hook":"Match the festival or home moment to the kind reply when it's teased.","pairs":[{"left":"Boy wants mehndi","right":"\"It's fun art, go for it\""},{"left":"Boy helps cook at home","right":"\"Helping is kind, not girly\""},{"left":"Girl bursts crackers","right":"\"Anyone can, that's fun\""},{"left":"Boy does garba","right":"\"Garba's for everyone\""},{"left":"Girl flies the kite","right":"\"Great flying, nice one!\""}],"persona":"any","source":"gender stereotypes","relearn":"Festival and home moments are for everyone; each has a kind reply."},
  {"id":"nf-1149","cat":"gender-teasing","type":"strike-rewrite","hook":"\"Girls shouldn't shout in class, it's not ladylike.\"","myth":{"un":"Girls must stay quiet and 'ladylike', never loud.","re":"Girls can be loud, bold and excited just like anyone.","why":"'Ladylike' is a rule that tries to shrink girls' voices."},"relearn":"Girls can be loud and bold; 'ladylike' is a made-up limit.","persona":"Ananya","source":"gender norms"},
  {"id":"nf-1150","cat":"gender-teasing","type":"strike-rewrite","hook":"\"His skin's so dark, we call him 'kaala' for fun.\"","myth":{"un":"A nickname mocking dark skin is just harmless fun.","re":"Mocking someone's skin shade hurts; it's a put-down, not fun.","why":"A 'fun' name about something you can't change still stings."},"relearn":"Skin-colour nicknames aren't fun; every shade is beautiful.","persona":"any","source":"colourism (links g06)"},
  {"id":"nf-1152","cat":"gender-teasing","type":"strike-rewrite","hook":"\"You let a girl beat you at running? Shameful!\"","myth":{"un":"Losing a race to a girl is shameful for a boy.","re":"Whoever's fastest wins; her being a girl isn't shameful at all.","why":"This 'shame' only exists if we wrongly rank boys above girls."},"relearn":"A girl winning isn't shameful; she's just fast.","persona":"Reyansh","source":"gender teasing"},
  {"id":"nf-1154","cat":"gender-teasing","type":"strike-rewrite","hook":"\"She wants to be a pilot? Girls can't fly planes.\"","myth":{"un":"Some jobs, like pilot, just aren't for girls.","re":"Girls grow up to be pilots, engineers, anything they work for.","why":"No job belongs to one gender; dreams aren't gendered."},"relearn":"Any job is open to any kid; 'not for girls' is a myth.","persona":"Ananya","source":"gender norms"},
  {"id":"nf-1155","cat":"gender-teasing","type":"strike-rewrite","hook":"\"He hugged his friend, ew, boys shouldn't do that.\"","myth":{"un":"Boys hugging friends is wrong or 'too soft'.","re":"A friendly hug is kind; boys can show warmth too.","why":"Caring about friends isn't a 'girl' thing; it's just human."},"relearn":"Boys can be warm and hug friends; that's kind, not 'soft'.","persona":"Faizan-type","source":"gender norms"},
  {"id":"nf-1160","cat":"gender-teasing","type":"branch","hook":"At a wedding a boy wants to dance; an uncle laughs \"that's for ladies!\"","options":[{"text":"Cheer \"dance is for everyone, show us!\"","consequence":"He joins in; the crowd claps along.","outcome":"ally","best":true},{"text":"Pull him back to his seat","consequence":"He misses the fun over a made-up rule."}],"debrief":"Dancing isn't 'for ladies'; any kid can enjoy it.","relearn":"Dance is for everyone; 'that's for the ladies' is just a saying.","persona":"Faizan-type","source":"gender norms"},
  {"id":"nf-1161","cat":"gender-teasing","type":"branch","hook":"A girl's drawing of a girl footballer is called \"silly, girls don't play.\"","options":[{"text":"Say \"women play for India, great drawing!\"","consequence":"She's proud of her art again.","outcome":"ally","best":true},{"text":"Tell her to draw a boy instead","consequence":"She edits her dream to fit a myth."}],"debrief":"Women and girls play sport everywhere; 'girls don't play' is false.","relearn":"Girls and women play every sport; it's never 'silly'.","persona":"Ananya","source":"gender norms"},
  {"id":"nf-1162","cat":"gender-teasing","type":"role-play","hook":"A cousin teases a boy at a function for wearing a bright kurta: \"too colourful, like a girl!\"","setup":"Hype him up. Say:","yourLine":[{"text":"\"That kurta's brilliant, colours are for everyone.\"","best":true},{"text":"Suggest he change into something plain"}],"persona":"any","source":"colours / gender","relearn":"A bright kurta is brilliant; colours are for everyone."},
  {"id":"nf-1163","cat":"gender-teasing","type":"role-play","hook":"A girl is mocked for being the only one in the chess team: \"girls aren't smart enough.\"","setup":"Back her up. Say:","yourLine":[{"text":"\"She's brilliant at chess, smarts aren't a 'boy' thing.\"","best":true},{"text":"Stay quiet so they don't tease you too"}],"persona":"Ananya","source":"gender stereotypes","relearn":"Girls are brilliant at chess; smarts aren't a 'boy' thing."},
  {"id":"nf-1164","cat":"gender-teasing","type":"branch","hook":"Kids whisper a quiet boy who reads poetry is \"not a proper boy.\"","options":[{"text":"Say \"no 'proper boy' rule, he's great as he is\"","consequence":"He keeps reading; the whisper loses power.","outcome":"ally","best":true},{"text":"Tell him to read 'boy stuff'","consequence":"He buries something he loves to fit in."}],"debrief":"There's no 'proper boy' mould; poetry is for anyone who loves it.","relearn":"No one is 'not a proper boy'; everyone's fine as they are.","persona":"Faizan-type","source":"gender norms"},
  {"id":"nf-1170","cat":"how-it-feels","type":"reflect","hook":"Lensy: a kid laughs at his own joke but his friend goes quiet.","prompt":"How might the quiet friend feel?","options":["Hurt","Left out","Not sure"],"affirm":"You noticed a feeling under the laugh, that care is what matters.","relearn":"A joke is only fun if it's fun for the person it's about too.","persona":"any","source":"empathy"},
  {"id":"nf-1171","cat":"how-it-feels","type":"reflect","hook":"Lensy: someone copied the way you talk to make the bus laugh.","prompt":"How would that sit with you?","options":["Embarrassing","A bit hurt","I'd go quiet"],"affirm":"That sting is real, and it's exactly why we don't aim jokes at people.","relearn":"Being made the punchline stings; that feeling counts.","persona":"any","source":"empathy"},
  {"id":"nf-1172","cat":"how-it-feels","type":"reflect","hook":"Lensy: a friend says 'I'm fine' but won't look up after a joke.","prompt":"What might 'fine' really mean?","options":["Not fine","Hiding hurt","Hard to say"],"affirm":"A brave 'I'm fine' can hide real hurt, and noticing it is kind.","relearn":"People often say 'fine' to hide hurt; a quiet check-in means a lot.","persona":"any","source":"empathy"},
  {"id":"nf-1173","cat":"how-it-feels","type":"reflect","hook":"Lensy: before you tease, picture how it would land for them. Try it?","prompt":"What do you think of that check?","options":["Smart","I'll try it","A kind habit"],"affirm":"A quick 'how would this land for them?' keeps your jokes kind.","relearn":"Checking how a joke might land before you say it is a kind habit.","persona":"Reyansh","source":"perspective-taking"},
  {"id":"nf-1174","cat":"how-it-feels","type":"reflect","hook":"Lensy: a kid drops their tiffin and everyone laughs. They turn red.","prompt":"How do they feel inside?","options":["Small","Wishing to vanish","Embarrassed"],"affirm":"You can see past the laugh to the feeling, that's real empathy.","relearn":"Laughing at a mistake can make someone feel small; the feeling is real.","persona":"any","source":"empathy"},
  {"id":"nf-1175","cat":"how-it-feels","type":"reflect","hook":"Lensy: Faizan stopped saying pink is his favourite after the teasing.","prompt":"How might shrinking himself feel?","options":["Sad","Tiring","Not himself"],"affirm":"Hiding who you are to avoid jokes is heavy, and it was never his fault.","relearn":"Mean teasing can make a kid shrink themselves; the target is never at fault.","persona":"Faizan-type","source":"impact / self"},
  {"id":"nf-1176","cat":"how-it-feels","type":"reflect","hook":"Lensy: someone said 'I was only joking' after a dig that stung.","prompt":"Does 'only joking' undo the sting?","options":["No","The hurt stays","Not really"],"affirm":"'Only joking' doesn't switch off a real feeling, the hurt still counts.","relearn":"Calling it a joke doesn't erase the hurt; impact counts over intent.","persona":"any","source":"impact over intent"},
  {"id":"nf-1177","cat":"how-it-feels","type":"reflect","hook":"Lensy: a kid is teased a little every single day at school.","prompt":"What does day-after-day teasing do?","options":["Wears you down","Hurts more","Feels heavy"],"affirm":"Drip-by-drip teasing wears a kid down, it does not 'toughen' anyone.","relearn":"Mean teasing wears kids down; it doesn't toughen them up.","persona":"any","source":"impact / cumulative harm"},
  {"id":"nf-1178","cat":"how-it-feels","type":"reflect","hook":"Lensy: your one kind word after a joke can change a kid's whole day.","prompt":"Want to be that kind word?","options":["Yes","Count me in","I can be kind"],"affirm":"You can be the kind word that helps someone bounce back, that's power.","relearn":"A kind word can soften the sting of a put-down for someone.","persona":"any","source":"support"},
  {"id":"nf-1179","cat":"how-it-feels","type":"reflect","hook":"Lensy: a friend who got teased got a 'you okay?' text from you.","prompt":"How might that land for them?","options":["Seen","Less alone","Cared for"],"affirm":"A small check-in tells someone they're not alone, and that's a big deal.","relearn":"Checking in afterwards leaves a teased kid less alone and less down.","persona":"any","source":"peer support"},
  {"id":"nf-1180","cat":"how-it-feels","type":"reflect","hook":"Lensy: a kid was joked about behind their back, not to their face.","prompt":"Does it still hurt them?","options":["Yes","When they hear","It does"],"affirm":"Put-downs behind someone's back still reach them and still hurt.","relearn":"Behind-the-back put-downs still hurt the person they're about.","persona":"any","source":"empathy / behind-the-back"},
  {"id":"nf-1181","cat":"how-it-feels","type":"reflect","hook":"Lensy: you said sorry after a joke landed wrong. How does owning it feel?","prompt":"What do you notice?","options":["Lighter","Honest","Like a friend"],"affirm":"Owning your impact and saying sorry helps both of you, and you grow.","relearn":"If you hurt someone, even by accident, saying sorry makes it right.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1182","cat":"how-it-feels","type":"reflect","hook":"Lensy: not laughing at a mean joke, does that mean you 'can't take a joke'?","prompt":"What do you reckon?","options":["No","I just noticed","It wasn't kind"],"affirm":"Not laughing means you noticed it wasn't kind, not that you're no fun.","relearn":"Not laughing means you noticed it wasn't kind; it's not 'can't take a joke'.","persona":"any","source":"impact / 'can't take a joke'"},
  {"id":"nf-1183","cat":"how-it-feels","type":"reflect","hook":"Lensy: a cousin's 'joke' about your height at a family party stings.","prompt":"Is it okay to feel hurt?","options":["Yes","Totally","Of course"],"affirm":"Your feelings are allowed, even from family, even when they meant fun.","relearn":"A put-down can sting even from family who 'meant it as fun'; that's okay.","persona":"any","source":"empathy / family"},
  {"id":"nf-1184","cat":"how-it-feels","type":"reflect","hook":"Lensy: someone says 'don't be so sensitive' after their joke hurt you.","prompt":"Whose feeling matters here?","options":["Mine too","The hurt counts","Both"],"affirm":"Your feeling is real, 'too sensitive' is just a way to dodge the hurt.","relearn":"'Too sensitive' doesn't make your hurt wrong; the feeling still counts.","persona":"any","source":"impact / blame-shift"},
  {"id":"nf-1185","cat":"how-it-feels","type":"reflect","hook":"Lensy: a quiet kid finally smiled when you sat beside them after a joke.","prompt":"What did sitting there do?","options":["Helped","Said 'not alone'","A lot"],"affirm":"Sometimes just being there says 'I'm with you' louder than words.","relearn":"Just being there for a teased kid tells them they're not alone.","persona":"quiet child","source":"peer support / presence"},
  {"id":"nf-1186","cat":"how-it-feels","type":"reflect","hook":"Lensy: you wonder if your friend liked your joke or just smiled politely.","prompt":"Worth a gentle check?","options":["Yes","I'll ask","Better safe"],"affirm":"A gentle 'that was okay, na?' shows you care how it landed for them.","relearn":"A polite smile isn't always a yes; checking how it landed is kind.","persona":"Reyansh","source":"perspective-taking"},
  {"id":"nf-1187","cat":"how-it-feels","type":"reflect","hook":"Lensy: a kid laughs along at jokes about themselves so they fit in.","prompt":"How might that feel underneath?","options":["Tiring","Lonely","Not really fun"],"affirm":"Laughing at yourself to fit in is exhausting; that feeling is real.","relearn":"A kid may laugh along to fit in while it still hurts underneath.","persona":"any","source":"empathy / masking"},
  {"id":"nf-1188","cat":"how-it-feels","type":"reflect","hook":"Lensy: imagine the teased kid is your little brother or sister.","prompt":"How does that change how you see it?","options":["I'd protect them","It matters more","I'd step in"],"affirm":"Every teased kid is someone's sibling, picturing that grows your care.","relearn":"Picturing the teased kid as your own sibling helps you feel the impact.","persona":"Ananya","source":"empathy / perspective"},
  {"id":"nf-1189","cat":"how-it-feels","type":"reflect","hook":"Lensy: you apologised, and your friend needs a day before being okay.","prompt":"Can you give them that time?","options":["Yes","No rush","I'll wait"],"affirm":"Repair isn't instant, giving them time is part of being a good friend.","relearn":"After you say sorry, a friend may need time; patience is part of repair.","persona":"any","source":"repair"},
  {"id":"nf-1190","cat":"how-it-feels","type":"branch","hook":"You joke and your friend's smile drops right away.","options":[{"text":"Ask 'oh, did that land wrong? I'm sorry'","consequence":"They feel cared for; you caught it fast.","outcome":"repair","best":true},{"text":"Keep going like nothing happened","consequence":"A dropped smile is a signal; checking in beats brushing past."}],"debrief":"When a face changes, pause and check how it landed.","relearn":"If a joke lands wrong, checking in beats pushing on.","persona":"any","source":"impact / repair"},
  {"id":"nf-1191","cat":"how-it-feels","type":"branch","hook":"A 'joke' you made last week still bothers a classmate.","options":[{"text":"Say 'sorry, that wasn't fair of me'","consequence":"An old sting can finally ease.","outcome":"repair","best":true},{"text":"Decide it's too long ago to matter","consequence":"Hurt doesn't expire; a late sorry still helps."}],"debrief":"It's never too late to own a joke that hurt.","relearn":"Even an old hurt can be made right; a late sorry counts.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1192","cat":"how-it-feels","type":"branch","hook":"A friend laughs at a dig about you, then asks 'you okay, na?'","options":[{"text":"Be honest: 'that one stung a bit'","consequence":"They learn how it landed; the friendship stays real.","outcome":"honest","best":true},{"text":"Say 'all fine' while it stings","consequence":"You can name a real feeling; your friend wants to know."}],"debrief":"You can say a joke stung, even to a kind friend.","relearn":"Naming that a joke stung is honest; a friend wants to know.","persona":"any","source":"impact / honesty"},
  {"id":"nf-1193","cat":"how-it-feels","type":"branch","hook":"Your team lost; you nearly joke 'thanks, butter-fingers Aman'.","options":[{"text":"Hold it in; one missed catch isn't a punchline","consequence":"Aman is spared a sting on a hard day.","outcome":"kind","best":true},{"text":"Say it for the laugh","consequence":"A 'joke' on a bad day stings; you can skip it."}],"debrief":"On a rough day a joke lands twice as hard.","relearn":"A joke aimed at someone already low can sting twice as hard.","persona":"any","source":"empathy / timing"},
  {"id":"nf-1194","cat":"how-it-feels","type":"branch","hook":"Kids replay a joke about a girl who isn't even there.","options":[{"text":"Say 'she's not here, let's drop it'","consequence":"The behind-the-back pile-on stops.","outcome":"ally","best":true},{"text":"Add a line to the joke","consequence":"Talking someone down behind their back still hurts."}],"debrief":"Put-downs behind a back still reach the person.","relearn":"Behind-the-back put-downs still hurt; you can stop them.","persona":"Ananya","source":"behind-the-back / ally"},
  {"id":"nf-1195","cat":"how-it-feels","type":"branch","hook":"You're the one being teased and it really hurts.","options":[{"text":"Say 'not okay' and tell a trusted grown-up if it keeps on","consequence":"You stand up for yourself and get support.","outcome":"assertive","best":true},{"text":"Bottle it all up","consequence":"You deserve support; telling a trusted grown-up helps."}],"debrief":"If you're the target you can speak up; it's not your fault.","relearn":"If you're teased, say 'not okay' and tell a trusted grown-up.","persona":"Faizan-type","source":"self-advocacy"},
  {"id":"nf-1196","cat":"how-it-feels","type":"branch","hook":"A kid you teased last term flinches when you walk past.","options":[{"text":"Say 'I was unkind before, I'm sorry'","consequence":"The flinch can ease; trust rebuilds a little.","outcome":"repair","best":true},{"text":"Tell yourself they're being dramatic","consequence":"A flinch is real hurt remembered; owning it helps."}],"debrief":"Old teasing can leave a real mark; owning it heals it.","relearn":"Teasing can leave a lasting mark; owning it starts repair.","persona":"Reyansh","source":"impact / repair"},
  {"id":"nf-1197","cat":"how-it-feels","type":"branch","hook":"A friend tells you 'I cried after that joke yesterday.'","options":[{"text":"Listen and say 'thank you for telling me, I'm sorry'","consequence":"They feel heard; the hurt shrinks.","outcome":"care","best":true},{"text":"Say 'it was nothing, forget it'","consequence":"Brushing off real tears stings more; listening helps."}],"debrief":"When a joke made someone cry, listen, don't shrink it.","relearn":"When a joke made someone cry, listening and owning it helps.","persona":"any","source":"impact / listening"},
  {"id":"nf-1198","cat":"how-it-feels","type":"branch","hook":"Someone says 'arre, I didn't MEAN to hurt you'.","options":[{"text":"Reply 'I know, but it stung, let's be careful'","consequence":"You name the impact kindly; intent isn't the test.","outcome":"clear","best":true},{"text":"Say 'forget it' so they feel okay","consequence":"You can say it stung; impact counts even when unmeant."}],"debrief":"'I didn't mean it' can be true and the hurt still real.","relearn":"Unmeant hurt still counts; you can name impact without blame.","persona":"any","source":"impact over intent"},
  {"id":"nf-1199","cat":"how-it-feels","type":"branch","hook":"A kid laughs loudest at jokes about himself so no one sees it hurts.","options":[{"text":"Tell him alone 'you don't have to laugh'","consequence":"He feels seen; he can stop the brave act.","outcome":"care","best":true},{"text":"Assume he loves the attention","consequence":"A loud laugh can be a mask; a quiet word lifts it."}],"debrief":"The loudest laugh can hide the most hurt.","relearn":"A kid may laugh loudest to hide hurt; noticing it helps.","persona":"any","source":"empathy / masking"},
  {"id":"nf-1200","cat":"how-it-feels","type":"branch","hook":"Your nickname for a classmate actually upsets them.","options":[{"text":"Drop it: 'what would you like to be called?'","consequence":"They feel respected; one kind question fixed it.","outcome":"repair","best":true},{"text":"Keep using it because 'everyone does'","consequence":"A name that hurts isn't fun for them; you can stop."}],"debrief":"If a nickname hurts, just ask and switch.","relearn":"A nickname that hurts isn't fun; ask what they'd like instead.","persona":"any","source":"impact / names"},
  {"id":"nf-1201","cat":"how-it-feels","type":"branch","hook":"A chat keeps posting memes mocking one classmate.","options":[{"text":"Stop adding; message the kid to check in","consequence":"You step out of the pile-on; the kid feels less alone.","outcome":"upstander","best":true},{"text":"Add the next meme to keep it funny","consequence":"Each repost is one more jab; piling-on wounds."}],"debrief":"Memes reposted at one person are online bullying. Stop and check in.","relearn":"Reposting a mocking meme keeps hurt going; stop and check in.","persona":"Ananya","source":"teasing vs bullying"},
  {"id":"nf-1202","cat":"how-it-feels","type":"branch","hook":"You tease your sister, she laughs, then quietly stops playing.","options":[{"text":"Say 'sorry didi, that wasn't nice, let's play'","consequence":"She comes back; you caught the hurt behind the laugh.","outcome":"repair","best":true},{"text":"Carry on, she laughed after all","consequence":"Stopping the play was the real signal; checking in helps."}],"debrief":"The laugh can come first and the hurt show after.","relearn":"A laugh can come before the hurt; watch what happens after.","persona":"any","source":"empathy / siblings"},
  {"id":"nf-1203","cat":"how-it-feels","type":"branch","hook":"A friend's joke about your accent got a big laugh; you feel small.","options":[{"text":"Tell them later 'that one about how I talk hurt'","consequence":"They didn't realise; now they can be careful.","outcome":"honest","best":true},{"text":"Laugh it off and feel bad alone","consequence":"You needn't carry it alone; naming it helps them learn."}],"debrief":"You can tell a friend a joke hurt; that's how they learn.","relearn":"Telling a friend their joke hurt helps them be careful.","persona":"any","source":"impact / voice"},
  {"id":"nf-1204","cat":"how-it-feels","type":"branch","hook":"A kid keeps getting teased; someone says 'it'll toughen him up'.","options":[{"text":"Say 'it wears him down, let's back him'","consequence":"You swap a myth for support; friends make him stronger.","outcome":"support","best":true},{"text":"Agree and leave him to it","consequence":"Teasing wears kids down; support builds strength."}],"debrief":"Teasing wears kids down; support builds strength.","relearn":"Mean teasing wears kids down; support, not teasing, builds strength.","persona":"any","source":"impact / support"},
  {"id":"nf-1205","cat":"how-it-feels","type":"branch","hook":"You and Aarav both joked, but his face says it's not even.","options":[{"text":"Check 'we okay? I don't want to hurt you'","consequence":"He can be honest; the fun stays fun for both.","outcome":"check","best":true},{"text":"Decide it's fine since you both joked","consequence":"Back-and-forth can tip into hurt; a quick check keeps it kind."}],"debrief":"Even when you both joke, check it's still fun for them too.","relearn":"Trading jokes is fun only if it stays fun for both.","persona":"Reyansh","source":"empathy / mutual"},
  {"id":"nf-1206","cat":"how-it-feels","type":"branch","hook":"You forwarded a clip mocking a kid to the class group.","options":[{"text":"Delete it: 'sorry, that wasn't fair to share'","consequence":"You stop it spreading; the kid is spared more sting.","outcome":"repair","best":true},{"text":"Leave it, everyone's laughing","consequence":"A shared clip multiplies the hurt; pulling it back helps."}],"debrief":"Sharing a mocking clip spreads the sting; you can own it.","relearn":"Sharing a clip that mocks a kid spreads the hurt; pull it back.","persona":"any","source":"impact / sharing"},
  {"id":"nf-1207","cat":"how-it-feels","type":"branch","hook":"Your friend went quiet for days after a joke; you don't know why.","options":[{"text":"Ask gently 'did something I said upset you?'","consequence":"They open up; the quiet was hurt waiting to be asked.","outcome":"care","best":true},{"text":"Wait for them to 'get over it'","consequence":"Quiet can be hurt; a gentle ask shows you care."}],"debrief":"A gentle ask can open a door the quiet shut.","relearn":"A friend's long quiet may be hurt; a gentle ask shows care.","persona":"any","source":"empathy / repair"},
  {"id":"nf-1208","cat":"how-it-feels","type":"branch","hook":"You meant your joke kindly but your friend looks upset.","options":[{"text":"Trust their face: 'I'm sorry that hurt'","consequence":"They feel believed; how it landed beats how you meant it.","outcome":"repair","best":true},{"text":"Insist 'but I meant it nicely!'","consequence":"How it landed matters more than how you meant it."}],"debrief":"When kind intent meets real hurt, trust the hurt.","relearn":"How a joke lands matters more than how you meant it.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-1209","cat":"how-it-feels","type":"branch","hook":"A new kid is teased about their village accent and goes silent.","options":[{"text":"Sit by them: 'I like how you say things'","consequence":"They feel welcomed; one warm line undoes a cold one.","outcome":"support","best":true},{"text":"Stay out of it","consequence":"Silence leaves the new kid alone; a warm word helps."}],"debrief":"A warm word helps a teased new kid feel they belong.","relearn":"A warm word can help a teased new kid feel they belong.","persona":"quiet child","source":"peer support"},
  {"id":"nf-1210","cat":"how-it-feels","type":"branch","hook":"You catch yourself about to repeat a joke you know hurt someone.","options":[{"text":"Stop and pick a different funny thing","consequence":"No one gets stung; funny needs no victim.","outcome":"kind","best":true},{"text":"Say it anyway, it gets a laugh","consequence":"A laugh isn't worth a sting; find kinder lines."}],"debrief":"If a joke hurts, you can choose a kinder funny.","relearn":"Knowing a joke hurts, you can choose a kinder funny instead.","persona":"Reyansh","source":"impact / self-check"},
  {"id":"nf-1211","cat":"how-it-feels","type":"branch","hook":"A classmate cried; a kid says 'why cry, it was a joke?'","options":[{"text":"Say 'a joke that makes someone cry isn't funny, you okay?'","consequence":"The crying kid feels backed; the dodge is named.","outcome":"ally","best":true},{"text":"Agree it was just a joke","consequence":"Tears say it wasn't funny; backing them up matters."}],"debrief":"Real tears mean it stopped being a joke.","relearn":"If a 'joke' makes someone cry, it isn't funny; back the hurt person.","persona":"Ananya","source":"impact / 'just a joke'"},
  {"id":"nf-1212","cat":"how-it-feels","type":"branch","hook":"You want to repair a joke but feel too shy to say sorry aloud.","options":[{"text":"Write a note: 'sorry about earlier, that wasn't fair'","consequence":"The sorry still lands; a quiet repair counts.","outcome":"repair","best":true},{"text":"Decide it's too awkward and skip it","consequence":"A quiet sorry, even a note, still helps."}],"debrief":"A repair can be quiet; a note counts too.","relearn":"A quiet sorry, even a note, still makes a hurt right.","persona":"quiet child","source":"repair / low-risk"},
  {"id":"nf-1213","cat":"how-it-feels","type":"branch","hook":"Everyone laughs at a 'joke' about a kid's worn-out shoes.","options":[{"text":"Say 'that's not funny' and change the subject","consequence":"The pile-on stops; the kid isn't left alone.","outcome":"ally","best":true},{"text":"Laugh along so you don't stand out","consequence":"A joke about what someone can't help stings; you can stop it."}],"debrief":"Jokes about what a kid can't help sting most.","relearn":"A joke about what a kid can't help stings; a short line stops it.","persona":"Ananya","source":"empathy / class"},
  {"id":"nf-1214","cat":"how-it-feels","type":"strike-rewrite","hook":"\"They laughed too, so it clearly didn't bother them.\"","myth":{"un":"They laughed along, so the joke didn't bother them.","re":"People often laugh to hide that a joke stung; a laugh isn't a yes.","why":"Checking how someone really feels matters more than the laugh you saw."},"relearn":"A laugh can hide hurt; check in instead of assuming it was fine.","persona":"Reyansh","source":"impact over intent"},
  {"id":"nf-1215","cat":"how-it-feels","type":"strike-rewrite","hook":"\"Teasing toughens a kid up, so it's good for them really.\"","myth":{"un":"A bit of teasing toughens kids up.","re":"Mean teasing wears kids down; support is what builds real strength.","why":"Kids who feel backed by friends cope far better than teased ones."},"relearn":"Mean teasing wears kids down, it doesn't toughen them; support helps.","persona":"any","source":"impact / cumulative harm"},
  {"id":"nf-1216","cat":"how-it-feels","type":"strike-rewrite","hook":"\"They laughed too, so my joke clearly didn't hurt them at all.\"","myth":{"un":"They laughed, so the joke didn't hurt them.","re":"People often laugh to hide hurt; a laugh isn't proof it didn't sting.","why":"Checking in matters more than reading a brave face."},"relearn":"A laugh can mask hurt; it isn't proof the joke didn't sting.","persona":"any","source":"empathy / masking"},
  {"id":"nf-1217","cat":"how-it-feels","type":"strike-rewrite","hook":"\"It was behind their back, so it doesn't count as hurting them.\"","myth":{"un":"A put-down behind someone's back doesn't really hurt them.","re":"Behind-the-back put-downs still reach the person and still hurt.","why":"Word travels, and being talked down stings whether you hear it now or later."},"relearn":"Behind-the-back put-downs still hurt the person they're about.","persona":"any","source":"behind-the-back"},
  {"id":"nf-1218","cat":"how-it-feels","type":"strike-rewrite","hook":"\"If they got hurt, they just can't take a joke.\"","myth":{"un":"If they got hurt, they just can't take a joke.","re":"Feeling hurt means the joke stung, not that something's wrong with them.","why":"How a joke lands is the test, not whether the person 'can take it'."},"relearn":"Being hurt by a joke isn't a flaw; how it lands is what matters.","persona":"any","source":"impact / blame-shift"},
  {"id":"nf-1219","cat":"how-it-feels","type":"strike-rewrite","hook":"\"It happened ages ago, so saying sorry now is pointless.\"","myth":{"un":"A joke from long ago is too late to say sorry for.","re":"Hurt doesn't expire; a late sorry can still ease an old sting.","why":"Owning it whenever you realise shows the person they matter."},"relearn":"It's never too late to own a joke that hurt; a late sorry still helps.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1220","cat":"how-it-feels","type":"strike-rewrite","hook":"\"Being teased is my own fault for being different.\"","myth":{"un":"If I'm teased, it must be my fault for being different.","re":"The teased kid is never at fault; being yourself is not a reason to be hurt.","why":"The choice to put someone down is on the teaser, not on you."},"relearn":"If you're teased it's not your fault; being yourself is never the reason.","persona":"Faizan-type","source":"impact / never your fault"},
  {"id":"nf-1221","cat":"how-it-feels","type":"match","hook":"Match the kind move to what it does for a teased friend.","pairs":[{"left":"Say 'that wasn't fair'","right":"They feel backed"},{"left":"Sit with them after","right":"They feel less alone"},{"left":"Ask 'you okay?'","right":"They feel seen"},{"left":"Say sorry for your joke","right":"The sting eases"},{"left":"Tell a trusted grown-up","right":"They feel safer"}],"relearn":"Backing, sitting with, asking, owning it, and telling all help a teased kid.","persona":"any","source":"peer support"},
  {"id":"nf-1222","cat":"how-it-feels","type":"match","hook":"Match the moment to the feeling it can leave behind.","pairs":[{"left":"Joked about in front of all","right":"Embarrassed"},{"left":"Teased day after day","right":"Worn down"},{"left":"Left out of an inside joke","right":"Lonely"},{"left":"A kind 'you okay?' after","right":"Comforted"},{"left":"A friend stands up for you","right":"Backed up"}],"relearn":"Put-downs leave hurt; kindness afterwards can leave comfort instead.","persona":"any","source":"empathy"},
  {"id":"nf-1223","cat":"how-it-feels","type":"match","hook":"Match what someone says to what's really going on underneath.","pairs":[{"left":"'I'm fine' with no eye contact","right":"Hiding hurt"},{"left":"Laughing loudest at themselves","right":"Masking a sting"},{"left":"'Forget it, it's nothing'","right":"It's not nothing"},{"left":"Going very quiet","right":"Upset inside"},{"left":"'I'll be okay, thanks'","right":"Felt your care"}],"relearn":"Brave words can hide real hurt; noticing what's underneath is kind.","persona":"any","source":"empathy / masking"},
  {"id":"nf-1224","cat":"how-it-feels","type":"match","hook":"Match the response to a hurt friend with what it gives them.","pairs":[{"left":"'I'm sorry, that hurt you'","right":"Feels owned"},{"left":"'But I didn't mean it!'","right":"Feels brushed off"},{"left":"'Want to talk about it?'","right":"Feels invited"},{"left":"'You're too sensitive'","right":"Feels blamed"},{"left":"'Thanks for telling me'","right":"Feels safe to share"}],"relearn":"Owning impact and listening help; blaming or dodging makes hurt worse.","persona":"any","source":"impact / repair"},
  {"id":"nf-1225","cat":"how-it-feels","type":"match","hook":"Match each saying to the truth it gets wrong.","pairs":[{"left":"'I was only joking'","right":"The hurt is still real"},{"left":"'It'll toughen them up'","right":"It wears them down"},{"left":"'Can't you take a joke?'","right":"How it lands is the test"},{"left":"'They laughed, so it's fine'","right":"A laugh can hide hurt"},{"left":"'It's behind their back'","right":"It still hurts them"}],"relearn":"Common dodges miss one truth: how a put-down lands is what counts.","persona":"any","source":"impact over intent"},
  {"id":"nf-1226","cat":"how-it-feels","type":"match","hook":"Match the small kind act to when it helps most.","pairs":[{"left":"Sit beside them","right":"When they're alone"},{"left":"Say 'that's not okay'","right":"As the teasing happens"},{"left":"Ask 'you alright?'","right":"Just after a joke"},{"left":"Tell a trusted grown-up","right":"When it keeps going"},{"left":"Say sorry yourself","right":"When your joke hurt"}],"relearn":"Different kind moves fit different moments; each one helps a hurt kid.","persona":"any","source":"peer support / timing"},
  {"id":"nf-1227","cat":"how-it-feels","type":"match","hook":"Match the feeling word to what made the kid feel it.","pairs":[{"left":"Ashamed","right":"Mocked for looks"},{"left":"Invisible","right":"Always the punchline"},{"left":"Cared for","right":"A friend checked in"},{"left":"Small","right":"Laughed at by all"},{"left":"Stronger","right":"Friends backed them up"}],"relearn":"Put-downs leave hard feelings; support leaves cared-for, stronger ones.","persona":"any","source":"empathy"},
  {"id":"nf-1228","cat":"how-it-feels","type":"sort","hook":"Sort: does this leave the teased kid feeling backed, or alone?","items":[{"id":"a","text":"A friend sits beside them"},{"id":"b","text":"Everyone laughs and turns away"},{"id":"c","text":"Someone asks 'you okay?'"},{"id":"d","text":"No one says a word"},{"id":"e","text":"A kid says 'that's not kind'"},{"id":"f","text":"The group keeps joking"}],"bins":[{"id":"backed","label":"Feels backed","valence":"pos"},{"id":"alone","label":"Feels alone","valence":"neg"}],"key":{"a":"backed","b":"alone","c":"backed","d":"alone","e":"backed","f":"alone"},"relearn":"Backing a kid up leaves them less alone; turning away leaves them isolated.","persona":"any","source":"peer support"},
  {"id":"nf-1229","cat":"how-it-feels","type":"sort","hook":"Sort: does this make a hurt right, or make it worse?","items":[{"id":"a","text":"'I'm sorry, that wasn't fair'"},{"id":"b","text":"'You're too sensitive'"},{"id":"c","text":"'Thanks for telling me'"},{"id":"d","text":"'It was just a joke, relax'"},{"id":"e","text":"'How can I make it up?'"},{"id":"f","text":"'I didn't mean it, so drop it'"}],"bins":[{"id":"repairs","label":"Makes it right","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"repairs","b":"worse","c":"repairs","d":"worse","e":"repairs","f":"worse"},"relearn":"Owning impact and listening repair; blaming or dodging make hurt worse.","persona":"any","source":"repair"},
  {"id":"nf-1230","cat":"how-it-feels","type":"sort","hook":"Sort: is this a real signal a joke landed wrong, or a sign it's all fun?","items":[{"id":"a","text":"Their smile drops fast"},{"id":"b","text":"They both keep giggling"},{"id":"c","text":"They go very quiet"},{"id":"d","text":"They add their own joke back"},{"id":"e","text":"Their eyes well up"},{"id":"f","text":"They say 'good one!' and grin"}],"bins":[{"id":"wrong","label":"Landed wrong","valence":"uhoh"},{"id":"fun","label":"All fun","valence":"pos"}],"key":{"a":"wrong","b":"fun","c":"wrong","d":"fun","e":"wrong","f":"fun"},"relearn":"Faces and quiet tell you when a joke landed wrong; watch for the signals.","persona":"any","source":"empathy / signals"},
  {"id":"nf-1231","cat":"how-it-feels","type":"sort","hook":"Sort: does this feeling come from a put-down, or from kindness?","items":[{"id":"a","text":"Feeling worn down"},{"id":"b","text":"Feeling cared for"},{"id":"c","text":"Feeling small"},{"id":"d","text":"Feeling backed up"},{"id":"e","text":"Feeling ashamed"},{"id":"f","text":"Feeling less alone"}],"bins":[{"id":"putdown","label":"From a put-down","valence":"neg"},{"id":"kind","label":"From kindness","valence":"pos"}],"key":{"a":"putdown","b":"kind","c":"putdown","d":"kind","e":"putdown","f":"kind"},"relearn":"Put-downs leave hard feelings; kindness leaves cared-for, backed-up ones.","persona":"any","source":"empathy"},
  {"id":"nf-1232","cat":"how-it-feels","type":"sort","hook":"Sort: does this answer say the hurt counts, or dodge it?","items":[{"id":"a","text":"'It still stung, sorry'"},{"id":"b","text":"'Can't you take a joke?'"},{"id":"c","text":"'I get how that felt'"},{"id":"d","text":"'I didn't mean it, so relax'"},{"id":"e","text":"'Your feeling is fair'"},{"id":"f","text":"'You're overreacting'"}],"bins":[{"id":"counts","label":"Hurt counts","valence":"pos"},{"id":"dodge","label":"Dodges the hurt","valence":"neg"}],"key":{"a":"counts","b":"dodge","c":"counts","d":"dodge","e":"counts","f":"dodge"},"relearn":"Naming that a feeling is real respects it; dodges push the hurt aside.","persona":"any","source":"impact over intent"},
  {"id":"nf-1233","cat":"how-it-feels","type":"sort","hook":"Sort: would this help a teased friend, or leave them stung?","items":[{"id":"a","text":"Checking in the next day"},{"id":"b","text":"Sharing the mean clip on"},{"id":"c","text":"Saving them a seat"},{"id":"d","text":"Repeating the joke later"},{"id":"e","text":"Telling a trusted grown-up"},{"id":"f","text":"Joining the laughing"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"stings","label":"Stings","valence":"neg"}],"key":{"a":"helps","b":"stings","c":"helps","d":"stings","e":"helps","f":"stings"},"relearn":"Checking in, including, and telling help; spreading and repeating sting.","persona":"any","source":"peer support"},
  {"id":"nf-1234","cat":"how-it-feels","type":"sort","hook":"Sort: is this on the teased kid, or never their fault?","items":[{"id":"a","text":"Liking pink or stories"},{"id":"b","text":"Choosing to dig at them"},{"id":"c","text":"Talking with an accent"},{"id":"d","text":"Piling on the joke"},{"id":"e","text":"Crying when it hurt"},{"id":"f","text":"Aiming a 'joke' at them"}],"bins":[{"id":"notfault","label":"Not their fault","valence":"pos"},{"id":"onteaser","label":"On the teaser","valence":"uhoh"}],"key":{"a":"notfault","b":"onteaser","c":"notfault","d":"onteaser","e":"notfault","f":"onteaser"},"relearn":"Being yourself or hurt is never your fault; teasing is the teaser's choice.","persona":"Faizan-type","source":"never your fault"},
  {"id":"nf-1235","cat":"how-it-feels","type":"sort","hook":"Sort: does this build a kid up, or wear them down?","items":[{"id":"a","text":"Friends cheering you on"},{"id":"b","text":"Daily little digs"},{"id":"c","text":"Being included"},{"id":"d","text":"Being the punchline again"},{"id":"e","text":"A teacher's kind word"},{"id":"f","text":"Whispers behind your back"}],"bins":[{"id":"builds","label":"Builds you up","valence":"pos"},{"id":"wears","label":"Wears you down","valence":"neg"}],"key":{"a":"builds","b":"wears","c":"builds","d":"wears","e":"builds","f":"wears"},"relearn":"Support and including build a kid up; repeated digs wear them down.","persona":"any","source":"impact / cumulative"},
  {"id":"nf-1236","cat":"how-it-feels","type":"build","hook":"Build the steps to make a hurtful joke right.","prompt":"Put the repair in order.","pieces":["Notice their face changed","Say 'I'm sorry, that wasn't fair'","Ask 'are you okay?'","Check in with them later","Insist you meant it nicely"],"mode":"sequence","key":["Notice their face changed","Say 'I'm sorry, that wasn't fair'","Ask 'are you okay?'","Check in with them later"],"relearn":"Repair: notice the hurt, say sorry, ask if they're okay, check in later.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1237","cat":"how-it-feels","type":"build","hook":"Build a kit of ways to comfort a friend who was just teased.","prompt":"Pick the comforting moves.","pieces":["Ask 'you okay?'","Sit with them","Say 'that wasn't fair'","Remind them it's not their fault","Tell them to toughen up"],"mode":"assemble","key":["Ask 'you okay?'","Sit with them","Say 'that wasn't fair'","Remind them it's not their fault"],"relearn":"Comfort kit: ask, sit with them, say it wasn't fair, it's not their fault.","persona":"any","source":"peer support"},
  {"id":"nf-1238","cat":"how-it-feels","type":"build","hook":"Build the things to remember when a joke makes someone cry.","prompt":"Pick the true reminders.","pieces":["Tears mean it stopped being a joke","Their feeling is real","Listen, don't shrink it","It's not their fault","Tell them they're overreacting"],"mode":"assemble","key":["Tears mean it stopped being a joke","Their feeling is real","Listen, don't shrink it","It's not their fault"],"relearn":"When a joke makes someone cry: it's real, listen, and it's not their fault.","persona":"any","source":"impact / listening"},
  {"id":"nf-1239","cat":"how-it-feels","type":"build","hook":"Build the quick check to run before a joke about a friend.","prompt":"Put the kind check in order.","pieces":["Picture how it lands for them","Ask 'would they laugh too?'","If unsure, skip or soften it","Watch their face after","Say it for the laugh anyway"],"mode":"sequence","key":["Picture how it lands for them","Ask 'would they laugh too?'","If unsure, skip or soften it","Watch their face after"],"relearn":"Kind check: picture the landing, ask if they'd laugh, skip if unsure, watch.","persona":"Reyansh","source":"perspective-taking"},
  {"id":"nf-1240","cat":"how-it-feels","type":"build","hook":"Build the gentle words for a friend who went quiet after a joke.","prompt":"Pick the kind things to say.","pieces":["'Did something I said upset you?'","'I want to know how you feel'","'I'm sorry if that stung'","'No rush, I'm here'","'Just get over it'"],"mode":"assemble","key":["'Did something I said upset you?'","'I want to know how you feel'","'I'm sorry if that stung'","'No rush, I'm here'"],"relearn":"For a quiet friend: ask, want to know, say sorry, and give them no rush.","persona":"any","source":"empathy / repair"},
  {"id":"nf-1241","cat":"how-it-feels","type":"build","hook":"Build the reasons a teased kid is never the one at fault.","prompt":"Pick the true reasons.","pieces":["Being yourself isn't a reason","The choice to tease is the teaser's","Liking what you like is fine","Your feelings are allowed","You should change to avoid it"],"mode":"assemble","key":["Being yourself isn't a reason","The choice to tease is the teaser's","Liking what you like is fine","Your feelings are allowed"],"relearn":"A teased kid is never at fault; the choice to tease is the teaser's.","persona":"Faizan-type","source":"never your fault"},
  {"id":"nf-1242","cat":"how-it-feels","type":"build","hook":"Build the steps to check in on a friend the day after teasing.","prompt":"Put the check-in in order.","pieces":["Find them when it's calm","Say 'yesterday wasn't fair on you'","Ask how they're feeling now","Offer to hang out","Bring up the joke for a laugh"],"mode":"sequence","key":["Find them when it's calm","Say 'yesterday wasn't fair on you'","Ask how they're feeling now","Offer to hang out"],"relearn":"Check in after: find calm time, say it wasn't fair, ask, and include them.","persona":"any","source":"peer support / check-in"},
  {"id":"nf-1243","cat":"how-it-feels","type":"build","hook":"Build the 'impact over intent' truths into one set.","prompt":"Pick the true ones.","pieces":["Hurt counts even if unmeant","How it lands is the test","You can still say sorry","'I didn't mean it' isn't the end","Meaning well undoes the hurt"],"mode":"assemble","key":["Hurt counts even if unmeant","How it lands is the test","You can still say sorry","'I didn't mean it' isn't the end"],"relearn":"Impact over intent: unmeant hurt still counts, and you can make it right.","persona":"any","source":"impact over intent"},
  {"id":"nf-1244","cat":"how-it-feels","type":"role-play","hook":"Your friend's face fell after your joke and you want to fix it.","setup":"Own the impact. Say:","yourLine":[{"text":"\"I'm sorry, that wasn't fair of me, are you okay?\"","best":true},{"text":"\"Relax, I was only joking.\""}],"relearn":"Owning the impact and checking in beats defending what you meant.","persona":"Reyansh","source":"repair / voice"},
  {"id":"nf-1245","cat":"how-it-feels","type":"role-play","hook":"A friend says 'doesn't matter' but clearly looks hurt by a joke.","setup":"Make space for the feeling. Say:","yourLine":[{"text":"\"It looks like it did matter, and that's okay, I'm sorry.\"","best":true},{"text":"\"Cool, glad it's nothing.\""}],"relearn":"A 'doesn't matter' can hide hurt; making space for it shows you care.","persona":"any","source":"empathy / voice"},
  {"id":"nf-1246","cat":"how-it-feels","type":"role-play","hook":"You're teased and your throat goes tight, but you want to speak.","setup":"Name how it feels. Say:","yourLine":[{"text":"\"That actually hurt, please stop.\"","best":true},{"text":"\"...\" (say nothing)"}],"relearn":"Naming the hurt out loud is brave; you're allowed to ask them to stop.","persona":"Faizan-type","source":"self-advocacy / voice"},
  {"id":"nf-1247","cat":"how-it-feels","type":"role-play","hook":"You find a classmate alone after the group joked about them.","setup":"Check in gently. Say:","yourLine":[{"text":"\"That wasn't fair to you, are you alright?\"","best":true},{"text":"\"Don't take it to heart, yaar.\""}],"relearn":"A gentle 'that wasn't fair, you alright?' helps far more than 'don't mind it'.","persona":"any","source":"peer support / voice"},
  {"id":"nf-1248","cat":"how-it-feels","type":"role-play","hook":"Someone insists 'but I didn't MEAN it' after their joke hurt you.","setup":"Hold the truth kindly. Say:","yourLine":[{"text":"\"I believe you, and it still hurt, so let's be careful.\"","best":true},{"text":"\"Fine, forget I said anything.\""}],"relearn":"You can believe they meant no harm and still say the hurt was real.","persona":"any","source":"impact over intent / voice"},
  {"id":"nf-1249","cat":"how-it-feels","type":"role-play","hook":"A kid is told 'crying over a joke? toughen up'.","setup":"Back the crying kid. Say:","yourLine":[{"text":"\"Crying's okay, that joke wasn't, you're not weak.\"","best":true},{"text":"\"Ya, just toughen up a bit.\""}],"relearn":"Crying isn't weakness, and a joke that hurts wasn't okay; back them up.","persona":"Ananya","source":"impact / voice"},
  {"id":"nf-1250","cat":"how-it-feels","type":"role-play","hook":"You realise a joke you laughed at really hurt your friend.","setup":"Own your part too. Say:","yourLine":[{"text":"\"I laughed and I shouldn't have, I'm sorry, are you okay?\"","best":true},{"text":"\"I only laughed, I didn't say it!\""}],"relearn":"Laughing along has impact too; owning your part helps a hurt friend.","persona":"any","source":"impact / voice"},
  {"id":"nf-1251","cat":"how-it-feels","type":"role-play","hook":"A friend whispers 'that joke made me feel really small'.","setup":"Meet it with care. Say:","yourLine":[{"text":"\"Thank you for telling me, that wasn't fair to you.\"","best":true},{"text":"\"You're reading too much into it.\""}],"relearn":"When someone shares a hurt, thank them and own it; don't wave it away.","persona":"any","source":"impact / listening / voice"},
  {"id":"nf-1260","cat":"just-a-joke","type":"strike-rewrite","hook":"\"I said 'just kidding', so now it doesn't count.\"","myth":{"un":"Adding 'just kidding' undoes a mean thing you said.","re":"'Just kidding' doesn't erase the hurt; the sting is real.","why":"The words still landed, so the feeling they caused is real."},"relearn":"'Just kidding' added after doesn't cancel a put-down.","persona":"Reyansh","source":"disparagement humor"},
  {"id":"nf-1261","cat":"just-a-joke","type":"strike-rewrite","hook":"\"If I meant it as a joke, it can't be mean.\"","myth":{"un":"As long as you meant it as a joke, it isn't mean.","re":"What matters is how it lands, not just how you meant it.","why":"A joke can still hurt even when no harm was meant."},"relearn":"How a 'joke' lands matters more than how it was meant.","persona":"any","source":"impact over intent"},
  {"id":"nf-1262","cat":"just-a-joke","type":"strike-rewrite","hook":"\"Saying it with a smile makes any joke okay.\"","myth":{"un":"If you smile while you say it, the joke is fine.","re":"A smile doesn't make a put-down kind; the words still hurt.","why":"People feel the put-down even when it's said with a grin."},"relearn":"A smile doesn't turn a put-down into a kind joke.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1263","cat":"just-a-joke","type":"strike-rewrite","hook":"\"Everyone laughed, so the joke must be fine.\"","myth":{"un":"If everyone laughs, the joke can't have hurt anyone.","re":"A joke can hurt one kid even while the rest are laughing.","why":"The crowd's laugh doesn't tell you how the target feels."},"relearn":"A whole group laughing doesn't mean nobody got hurt.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1264","cat":"just-a-joke","type":"strike-rewrite","hook":"\"It's only a joke if I post it online, right?\"","myth":{"un":"Putting 'jk' on a mean message makes it just a joke.","re":"'jk' doesn't erase the hurt; a put-down online still stings.","why":"The kid reading it still feels the mean words you sent."},"relearn":"Typing 'jk' doesn't make a mean message harmless.","persona":"Reyansh","source":"disparagement humor"},
  {"id":"nf-1265","cat":"just-a-joke","type":"strike-rewrite","hook":"\"A joke about a whole group is fine if it's funny.\"","myth":{"un":"A joke that puts a group down is okay if it's funny.","re":"A group put-down spreads unfair ideas, even when it gets a laugh.","why":"Funny or not, it teaches people an unkind thing about a group."},"relearn":"A funny laugh doesn't make a group put-down fair.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1266","cat":"just-a-joke","type":"strike-rewrite","hook":"\"If the joke is about me too, no one can mind.\"","myth":{"un":"If a joke is also about you, no one else can be hurt.","re":"A joke can still hurt others even if you're in it too.","why":"Being part of the joke doesn't speak for how they feel."},"relearn":"Being in the joke yourself doesn't make it okay for all.","persona":"any","source":"impact over intent"},
  {"id":"nf-1267","cat":"just-a-joke","type":"strike-rewrite","hook":"\"Comedians roast people, so roasting my friend is fine.\"","myth":{"un":"Roasting a friend is fine because comedians do it.","re":"A roast that leaves your friend hurt isn't a kind joke.","why":"If it's not fun for them too, it stopped being a joke."},"relearn":"A 'roast' that hurts your friend isn't a fair joke.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1268","cat":"just-a-joke","type":"strike-rewrite","hook":"\"It's just a joke, so I never have to say sorry.\"","myth":{"un":"You never owe a sorry for something you called a joke.","re":"If your joke hurt someone, a kind sorry helps make it right.","why":"Saying sorry shows you care more about them than the laugh."},"relearn":"You can say sorry for a joke that hurt, and it helps.","persona":"any","source":"repair"},
  {"id":"nf-1269","cat":"just-a-joke","type":"strike-rewrite","hook":"\"You can't say it's mean if I was only teasing.\"","myth":{"un":"If you call it teasing, no one can call it mean.","re":"You can name a teasing 'joke' as not okay; that's allowed.","why":"Naming a put-down doesn't make you 'no fun', it's fair."},"relearn":"You can name a teasing joke as not okay and still like fun.","persona":"Ananya","source":"self-advocacy"},
  {"id":"nf-1270","cat":"just-a-joke","type":"strike-rewrite","hook":"\"A joke can't be as bad as just being mean.\"","myth":{"un":"A put-down 'joke' is never as bad as a plain mean word.","re":"A put-down dressed as a joke can hurt just as much.","why":"The joke label hides the hurt but doesn't shrink it."},"relearn":"A put-down 'joke' can hurt as much as a plain mean word.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1271","cat":"just-a-joke","type":"strike-rewrite","hook":"\"It's only a joke; she should just laugh it off.\"","myth":{"un":"It was a joke, so she should just laugh it off.","re":"Telling someone to 'laugh it off' shifts the blame onto them.","why":"The teaser, not the hurt kid, is the one who can stop it."},"relearn":"'Just laugh it off' unfairly blames the kid who was hurt.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1272","cat":"just-a-joke","type":"strike-rewrite","hook":"\"If it's a joke at home, it's not really teasing.\"","myth":{"un":"A put-down at home is fine because it's 'just family fun'.","re":"A put-down at home can still hurt; family fun is kind, too.","why":"Being family doesn't make a mean nickname feel any better."},"relearn":"A 'joke' put-down at home can still hurt the person.","persona":"any","source":"impact over intent"},
  {"id":"nf-1273","cat":"just-a-joke","type":"strike-rewrite","hook":"\"I cracked the joke first, so I get to decide it's fine.\"","myth":{"un":"The kid who tells the joke decides if it went too far.","re":"The kid it's about gets a say in whether it went too far.","why":"Only they know how the joke actually made them feel."},"relearn":"The kid a joke is about gets a say in whether it's okay.","persona":"any","source":"impact over intent"},
  {"id":"nf-1274","cat":"just-a-joke","type":"branch","hook":"A boy mimics a classmate's stutter, then says \"chill, just a joke.\"","options":[{"text":"Say \"it's not a joke if it hurts him, stop\"","consequence":"You name the dodge; the mocking loses its cover.","outcome":"ally","best":true},{"text":"Let 'just a joke' end it","consequence":"'Just a joke' shouldn't be a free pass to mock someone."}],"debrief":"'Just a joke' is a dodge, not a free pass for a put-down.","relearn":"You can call out a put-down even when it's named a 'joke'.","persona":"Ananya","source":"disparagement humor"},
  {"id":"nf-1275","cat":"just-a-joke","type":"branch","hook":"A cousin keeps calling you a mean nickname and grins, \"don't be touchy.\"","options":[{"text":"Say \"that name isn't funny to me, please stop\"","consequence":"You name it calmly; the dodge stops working.","outcome":"assertive","best":true},{"text":"Pretend you don't mind","consequence":"You're allowed to say a 'joke' name doesn't feel funny."}],"debrief":"'Don't be touchy' is a dodge; you can ask them to stop.","relearn":"You can say a 'joke' nickname isn't funny and ask it to stop.","persona":"Faizan-type","source":"self-advocacy"},
  {"id":"nf-1276","cat":"just-a-joke","type":"branch","hook":"Friends laugh at a 'joke' that puts down kids from your town.","options":[{"text":"Say \"that's not really funny, it's a put-down\"","consequence":"You name it; some friends rethink the laugh.","outcome":"ally","best":true},{"text":"Laugh so you fit in","consequence":"Laughing along lets the put-down feel normal and okay."}],"debrief":"A laugh can let a group put-down feel normal; naming it helps.","relearn":"Naming a 'joke' as a put-down can stop it feeling normal.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1277","cat":"just-a-joke","type":"branch","hook":"You told a joke; your friend went quiet, then you said \"just kidding!\"","options":[{"text":"Check in: \"that wasn't kind of me, are you okay?\"","consequence":"You repair it; your friend feels cared about again.","outcome":"repair","best":true},{"text":"Say \"why so serious?\"","consequence":"'Why so serious?' shifts the blame onto your friend."}],"debrief":"When a joke lands wrong, checking in beats doubling down.","relearn":"If your joke hurt, checking in beats saying 'just kidding'.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1278","cat":"just-a-joke","type":"branch","hook":"A kid jokes about another's worn-out shoes, then says \"can't you laugh?\"","options":[{"text":"Say \"I laugh at jokes, not at people\"","consequence":"You draw the line; the dig loses its excuse.","outcome":"ally","best":true},{"text":"Force a laugh to seem cool","consequence":"A forced laugh tells the teaser the dig was fine."}],"debrief":"'Can't you laugh?' is a dodge; jokes shouldn't punch down.","relearn":"You can laugh at jokes and still refuse ones aimed at a person.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1279","cat":"just-a-joke","type":"branch","hook":"Online, a kid posts a mean photo meme of a classmate and adds 'lol jk'.","options":[{"text":"Don't share it; message the classmate to check in","consequence":"You stop it spreading and the kid feels supported.","outcome":"ally","best":true},{"text":"Share it since it says 'jk'","consequence":"'jk' doesn't undo the hurt, and sharing spreads it."}],"debrief":"'jk' doesn't make a mean post fine; not sharing it helps.","relearn":"A 'jk' label doesn't make a mean post okay to spread.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1280","cat":"just-a-joke","type":"branch","hook":"A teammate jokes \"you play so badly it's a joke\" after you miss a goal.","options":[{"text":"Say \"missing isn't a reason to put me down\"","consequence":"You name it; the dig stops being a free hit.","outcome":"assertive","best":true},{"text":"Laugh and feel small","consequence":"A 'joke' about a mistake can still wear you down."}],"debrief":"A 'joke' about a mistake is still a put-down you can refuse.","relearn":"You can refuse a 'joke' that puts you down for a mistake.","persona":"any","source":"self-advocacy"},
  {"id":"nf-1281","cat":"just-a-joke","type":"branch","hook":"An older kid teases a younger one hard, laughing \"they know I'm joking.\"","options":[{"text":"Say \"check with them, it didn't look fun\"","consequence":"You invite a real check-in, not an excuse.","outcome":"ally","best":true},{"text":"Assume the big kid is right","consequence":"Only the younger kid knows if the 'joke' was fun."}],"debrief":"'They know I'm joking' isn't proof; ask the kid it's about.","relearn":"Only the kid a joke is about knows if it was really fun.","persona":"any","source":"impact over intent"},
  {"id":"nf-1282","cat":"just-a-joke","type":"branch","hook":"Your friend repeats a hurtful joke they heard, thinking it's harmless.","options":[{"text":"Quietly say \"that one's actually a put-down\"","consequence":"Your friend learns it, no shame, and drops it.","outcome":"repair","best":true},{"text":"Call them a bully loudly","consequence":"Shaming them makes them defensive, not thoughtful."}],"debrief":"A kid who repeats a joke isn't 'bad'; they can check and stop.","relearn":"A kid who repeats a hurtful joke can check it and drop it.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1283","cat":"just-a-joke","type":"sort","hook":"Sort: a fair joke, or a put-down hiding behind 'just a joke'?","items":[{"id":"a","text":"A silly pun about bananas"},{"id":"b","text":"\"You're slow, just a joke\""},{"id":"c","text":"A voice that makes you both laugh"},{"id":"d","text":"\"Look at his clothes, kidding\""},{"id":"e","text":"A knock-knock joke, no victim"},{"id":"f","text":"\"Girls can't run, it's a joke\""}],"bins":[{"id":"fair","label":"Fair joke","valence":"pos"},{"id":"putdown","label":"Put-down","valence":"neg"}],"key":{"a":"fair","b":"putdown","c":"fair","d":"putdown","e":"fair","f":"putdown"},"relearn":"A 'just a joke' label can't turn a put-down into a fair joke.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1284","cat":"just-a-joke","type":"sort","hook":"Sort: which lines dodge the hurt, and which own it kindly?","items":[{"id":"a","text":"\"Can't you take a joke?\""},{"id":"b","text":"\"Sorry, that wasn't kind of me.\""},{"id":"c","text":"\"Relax, I was just kidding.\""},{"id":"d","text":"\"Are you okay? I'll stop.\""},{"id":"e","text":"\"Why so serious?\""},{"id":"f","text":"\"That was unfair, my bad.\""}],"bins":[{"id":"dodge","label":"Dodges the hurt","valence":"neg"},{"id":"owns","label":"Owns it kindly","valence":"pos"}],"key":{"a":"dodge","b":"owns","c":"dodge","d":"owns","e":"dodge","f":"owns"},"relearn":"Owning a joke that hurt beats dodging it with 'can't you take a joke'.","persona":"any","source":"repair"},
  {"id":"nf-1285","cat":"just-a-joke","type":"sort","hook":"Sort: laughing WITH everyone, or AT one kid?","items":[{"id":"a","text":"Friends giggle at a goofy dance"},{"id":"b","text":"Everyone laughs at one kid's accent"},{"id":"c","text":"A joke the whole group grins at"},{"id":"d","text":"Laughing at a kid who tripped"},{"id":"e","text":"A story with no butt of the joke"},{"id":"f","text":"Mocking one kid's name"}],"bins":[{"id":"with","label":"Laughing with","valence":"pos"},{"id":"at","label":"Laughing at","valence":"neg"}],"key":{"a":"with","b":"at","c":"with","d":"at","e":"with","f":"at"},"relearn":"A fair joke laughs WITH everyone, not AT one kid.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1286","cat":"just-a-joke","type":"sort","hook":"Sort: stopped when asked, or kept going?","items":[{"id":"a","text":"A friend stops when you say stop"},{"id":"b","text":"A kid teases on after 'stop'"},{"id":"c","text":"A joke pauses when you look upset"},{"id":"d","text":"'Stop' ignored, the dig goes on"},{"id":"e","text":"A teaser asks 'still funny?'"},{"id":"f","text":"A kid teases harder when asked"}],"bins":[{"id":"stops","label":"Stops when asked","valence":"pos"},{"id":"keeps","label":"Keeps going","valence":"neg"}],"key":{"a":"stops","b":"keeps","c":"stops","d":"keeps","e":"stops","f":"keeps"},"relearn":"A fair joke stops when asked; a mean one won't.","persona":"any","source":"fun vs mean test"},
  {"id":"nf-1287","cat":"just-a-joke","type":"sort","hook":"Sort: which 'jokes' are safe fun, and which sting like a put-down?","items":[{"id":"a","text":"A riddle about animals"},{"id":"b","text":"\"You're dumb, just teasing\""},{"id":"c","text":"A made-up funny word everyone enjoys"},{"id":"d","text":"\"Nice haircut, ha, kidding\""},{"id":"e","text":"A joke about a talking vegetable"},{"id":"f","text":"\"You smell, joking joking\""}],"bins":[{"id":"safe","label":"Safe fun","valence":"pos"},{"id":"sting","label":"Stings","valence":"neg"}],"key":{"a":"safe","b":"sting","c":"safe","d":"sting","e":"safe","f":"sting"},"relearn":"Adding 'joking' to a sting doesn't make it safe fun.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1288","cat":"just-a-joke","type":"sort","hook":"Sort: which replies are fair, and which dodge the hurt with 'it's a joke'?","items":[{"id":"a","text":"\"I'll stop, that wasn't kind.\""},{"id":"b","text":"\"Stop being so sensitive.\""},{"id":"c","text":"\"You're right, sorry.\""},{"id":"d","text":"\"It's a joke, get over it.\""},{"id":"e","text":"\"My bad, I went too far.\""},{"id":"f","text":"\"Everyone else laughed.\""}],"bins":[{"id":"fair","label":"Fair reply","valence":"pos"},{"id":"dodge","label":"Dodge","valence":"neg"}],"key":{"a":"fair","b":"dodge","c":"fair","d":"dodge","e":"fair","f":"dodge"},"relearn":"Fair replies own the hurt; dodges hide it behind 'it's a joke'.","persona":"any","source":"repair"},
  {"id":"nf-1330","cat":"just-a-joke","type":"sort","hook":"Sort: does the joke punch UP (okay) or DOWN at a smaller kid?","items":[{"id":"a","text":"A joke poking fun at a famous hero"},{"id":"b","text":"A dig at a shy new kid"},{"id":"c","text":"A funny line about the teacher's robot"},{"id":"d","text":"Teasing the youngest kid in class"},{"id":"e","text":"A joke about a king in a story"},{"id":"f","text":"Mocking a kid with worn shoes"}],"bins":[{"id":"up","label":"Punches up","valence":"pos"},{"id":"down","label":"Punches down","valence":"neg"}],"key":{"a":"up","b":"down","c":"up","d":"down","e":"up","f":"down"},"relearn":"A fair joke punches up, never down at a smaller kid.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1289","cat":"just-a-joke","type":"reflect","hook":"Lensy: who knows best if a joke went too far, the teller or the kid it's about?","prompt":"What do you think?","options":["The kid it's about","Their feelings count most","Not just the teller"],"affirm":"The feelings of the kid it's about matter most, not just what the teller meant.","relearn":"How the kid it's about felt is the best test of a joke.","persona":"any","source":"impact over intent"},
  {"id":"nf-1290","cat":"just-a-joke","type":"reflect","hook":"Lensy: 'I was joking' shouldn't wipe away someone's hurt, right?","prompt":"What do you think?","options":["Right","The hurt still counts","Caring is kind"],"affirm":"'I was joking' doesn't undo the hurt, and caring about that is real kindness.","relearn":"'I was joking' doesn't cancel the hurt a joke caused.","persona":"any","source":"impact over intent"},
  {"id":"nf-1291","cat":"just-a-joke","type":"reflect","hook":"Lensy: can you love jokes AND say no to the ones that hurt?","prompt":"What do you think?","options":["Yes","Both at once","Of course"],"affirm":"You can love jokes and still say no to the unkind ones, that's not 'no fun'.","relearn":"You can enjoy jokes and refuse the ones that hurt.","persona":"any","source":"self-advocacy"},
  {"id":"nf-1292","cat":"just-a-joke","type":"reflect","hook":"Lensy: 'can't you take a joke?' tries to make you the problem. Notice that?","prompt":"What do you think?","options":["Yes","It shifts the blame","I see it"],"affirm":"'Can't you take a joke?' shifts the blame onto the hurt kid, that's the dodge.","relearn":"'Can't you take a joke?' unfairly blames the kid who was hurt.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1293","cat":"just-a-joke","type":"reflect","hook":"Lensy: a comedian who makes fun of themselves can be the funniest of all. Ever tried it?","prompt":"What do you think?","options":["I have","I'd try it","Funniest of all"],"affirm":"Laughing at yourself is brave and warm, no one gets hurt.","relearn":"Joking about yourself is a kind, funny move that needs no victim.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1294","cat":"just-a-joke","type":"reflect","hook":"Lensy: when does a joke stop being a joke, do you think?","prompt":"What do you think?","options":["When it hurts someone","When it won't stop","When it isn't fun for them"],"affirm":"All of those, that's exactly when a joke has stopped being a joke.","relearn":"A joke stops being a joke when it hurts, won't stop, or isn't fun for them.","persona":"any","source":"fun vs mean test"},
  {"id":"nf-1295","cat":"just-a-joke","type":"reflect","hook":"Lensy: if a joke went sideways, is checking in braver than 'just kidding'?","prompt":"What do you think?","options":["Yes","Checking in is brave","I'd check in"],"affirm":"Checking in after a joke went wrong is braver and kinder than 'just kidding'.","relearn":"Checking in beats 'just kidding' when a joke went wrong.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1296","cat":"just-a-joke","type":"reflect","hook":"Lensy: a smile while saying it, does that make a put-down okay?","prompt":"What do you think?","options":["No","Words still land","The hurt is real"],"affirm":"A smile doesn't make a put-down kind, the words still land on the other kid.","relearn":"A smile doesn't turn a put-down into a kind joke.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1297","cat":"just-a-joke","type":"reflect","hook":"Lensy: is naming an unkind 'joke' the same as being 'no fun'?","prompt":"What do you think?","options":["No","I can be fun and fair","Not at all"],"affirm":"You can name a joke as not okay and still be plenty of fun.","relearn":"Naming an unkind joke doesn't make you 'no fun'.","persona":"Ananya","source":"self-advocacy"},
  {"id":"nf-1298","cat":"just-a-joke","type":"reflect","hook":"Lensy: a 'joke' about a whole group, does the laugh make it harmless?","prompt":"What do you think?","options":["No","It spreads unfairness","Still a put-down"],"affirm":"A laugh doesn't make a group put-down harmless, it can still spread unfair ideas.","relearn":"A laugh doesn't make a group put-down harmless.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1299","cat":"just-a-joke","type":"reflect","hook":"Lensy: does it matter most that the teller 'meant well', or how it landed?","prompt":"What do you think?","options":["How it landed","Both, but landing counts","Their feeling matters"],"affirm":"How a joke landed matters most, even a well-meant one can hurt.","relearn":"How a joke landed matters more than whether it was 'meant well'.","persona":"any","source":"impact over intent"},
  {"id":"nf-1300","cat":"just-a-joke","type":"reflect","hook":"Lensy: would a great comedian punch up, or punch down at a smaller kid?","prompt":"What do you think?","options":["Punch up","Never at a smaller kid","No victim needed"],"affirm":"The best jokes punch up, never down at someone with less power.","relearn":"A fair joke punches up, never down at a smaller kid.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1301","cat":"just-a-joke","type":"reflect","hook":"Lensy: a 'joke' online with 'lol' on it, can it still hurt the reader?","prompt":"What do you think?","options":["Yes","Words still sting","The reader feels it"],"affirm":"A 'joke' online still stings, 'lol' doesn't undo the words the reader sees.","relearn":"A 'joke' online still hurts even with 'lol' on it.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1302","cat":"just-a-joke","type":"reflect","hook":"Lensy: is a put-down 'joke' really gentler than just saying the mean thing?","prompt":"What do you think?","options":["No","Hurts the same","It just hides it"],"affirm":"A put-down 'joke' can hurt just as much, the label only hides it.","relearn":"A put-down 'joke' can hurt as much as a plain mean word.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1303","cat":"just-a-joke","type":"reflect","hook":"Lensy: 'why so serious?', is that an answer or a way to dodge?","prompt":"What do you think?","options":["A dodge","It changes the subject","It avoids the hurt"],"affirm":"'Why so serious?' is a dodge, it slips past the hurt instead of facing it.","relearn":"'Why so serious?' is a dodge, not an answer to the hurt.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1304","cat":"just-a-joke","type":"reflect","hook":"Lensy: if a kid repeats a hurtful joke, can they learn and stop, no shame?","prompt":"What do you think?","options":["Yes","Anyone can learn","They can repair it"],"affirm":"A kid who repeats a hurtful joke can learn and stop, no shame, just a kind fix.","relearn":"A kid who repeats a hurtful joke can check it and stop, no shame.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1305","cat":"just-a-joke","type":"reflect","hook":"Lensy: should the kid it's about get a say in whether the joke went too far?","prompt":"What do you think?","options":["Yes","They know how it felt","Their say counts"],"affirm":"The kid a joke is about gets a say, only they know how it actually felt.","relearn":"The kid a joke is about gets a say in whether it went too far.","persona":"any","source":"impact over intent"},
  {"id":"nf-1306","cat":"just-a-joke","type":"reflect","hook":"Lensy: at home or at school, does 'just a joke' work the same way?","prompt":"What do you think?","options":["Same way","A put-down still hurts","Family fun is kind too"],"affirm":"'Just a joke' is a dodge anywhere, a put-down can hurt at home, too.","relearn":"A 'just a joke' put-down can hurt at home as much as at school.","persona":"any","source":"impact over intent"},
  {"id":"nf-1307","cat":"just-a-joke","type":"role-play","hook":"A kid says \"can't you take a joke?\" right after a mean dig at you.","setup":"Hold your ground. Say:","yourLine":[{"text":"\"I take jokes fine, just not ones that hurt.\"","best":true},{"text":"\"Okay, sorry, I'll laugh.\""}],"relearn":"You can take jokes and still refuse the ones that hurt.","persona":"Ananya","source":"assertiveness / voice"},
  {"id":"nf-1308","cat":"just-a-joke","type":"role-play","hook":"Your friend went quiet after your joke; you want to fix it.","setup":"Make it right. Say:","yourLine":[{"text":"\"That wasn't kind of me, I'm sorry, are you okay?\"","best":true},{"text":"\"Relax, I was only kidding.\""}],"relearn":"A real sorry repairs a joke that hurt better than 'only kidding'.","persona":"Reyansh","source":"repair / voice"},
  {"id":"nf-1309","cat":"just-a-joke","type":"role-play","hook":"A kid mocks your friend, then grins \"it's just a joke, na.\"","setup":"Name the dodge. Say:","yourLine":[{"text":"\"It's not a joke if it hurts him, please stop.\"","best":true},{"text":"Give an awkward laugh"}],"relearn":"A calm 'it's not a joke if it hurts' shuts the dodge down.","persona":"Ananya","source":"upstander / voice"},
  {"id":"nf-1310","cat":"just-a-joke","type":"role-play","hook":"Someone teases your name as a 'joke' and says \"don't be so touchy.\"","setup":"Stand up for yourself. Say:","yourLine":[{"text":"\"That joke isn't funny to me, please stop.\"","best":true},{"text":"\"Fine, whatever.\""}],"relearn":"You can say a 'joke' about you isn't funny and ask it to stop.","persona":"Faizan-type","source":"self-advocacy / voice"},
  {"id":"nf-1311","cat":"just-a-joke","type":"role-play","hook":"A kid jokes about your friend's old uniform and adds \"just kidding!\"","setup":"Back your friend up. Say:","yourLine":[{"text":"\"That's not funny, it's a put-down, stop.\"","best":true},{"text":"Say nothing and look away"}],"relearn":"A clear 'that's a put-down, stop' defends a friend kindly.","persona":"any","source":"upstander / voice"},
  {"id":"nf-1312","cat":"just-a-joke","type":"role-play","hook":"You realise a joke you repeated was actually a group put-down.","setup":"Own it out loud. Say:","yourLine":[{"text":"\"I won't say that one, it puts people down.\"","best":true},{"text":"\"It's fine, it's just a joke.\""}],"relearn":"You can drop a joke once you see it puts people down.","persona":"Reyansh","source":"repair / voice"},
  {"id":"nf-1313","cat":"just-a-joke","type":"role-play","hook":"A group laughs at one kid; you want to break the 'just a joke' spell.","setup":"Say the two words that land:","yourLine":[{"text":"\"Not funny.\"","best":true},{"text":"A nervous chuckle"}],"relearn":"A plain 'not funny' can break the 'just a joke' spell fast.","persona":"any","source":"upstander / voice"},
  {"id":"nf-1314","cat":"just-a-joke","type":"build","hook":"Build the test for whether a 'joke' is really fair.","prompt":"Pick the questions a fair joke should pass.","pieces":["Is it fun for the kid it's about?","Does it stop when asked?","Does it laugh WITH, not AT?","Does it need a victim to be funny?","Did it get the biggest laugh?"],"mode":"assemble","key":["Is it fun for the kid it's about?","Does it stop when asked?","Does it laugh WITH, not AT?"],"relearn":"A fair joke is fun for everyone, stops when asked, and laughs WITH, not AT.","persona":"any","source":"fun vs mean test"},
  {"id":"nf-1315","cat":"just-a-joke","type":"build","hook":"Build the steps to fix a joke that hurt a friend.","prompt":"Put the repair steps in order.","pieces":["Notice they're hurt","Say sorry, no excuses","Check 'are you okay?'","Drop that joke next time"],"mode":"sequence","key":["Notice they're hurt","Say sorry, no excuses","Check 'are you okay?'","Drop that joke next time"],"relearn":"Repair a joke that hurt: notice, say sorry, check in, drop it next time.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1316","cat":"just-a-joke","type":"build","hook":"Build a comeback kit for when someone says 'just a joke'.","prompt":"Pick the calm lines that name the dodge.","pieces":["\"It's not funny if it hurts.\"","\"I laugh at jokes, not at people.\"","\"Please stop, that's a put-down.\"","\"Can't YOU take being told no?\"","\"You're so dumb anyway.\""],"mode":"assemble","key":["\"It's not funny if it hurts.\"","\"I laugh at jokes, not at people.\"","\"Please stop, that's a put-down.\""],"relearn":"Calm comebacks name the dodge without throwing a new insult.","persona":"Ananya","source":"assertiveness"},
  {"id":"nf-1317","cat":"just-a-joke","type":"build","hook":"Build the 'kind comedian' code for telling jokes.","prompt":"Pick the rules of the kind comedian code.","pieces":["Joke WITH, not AT","No victim needed","Punch up, never down","Stop if it stops being fun","Roast the smallest kid"],"mode":"assemble","key":["Joke WITH, not AT","No victim needed","Punch up, never down","Stop if it stops being fun"],"relearn":"The kind comedian code: joke WITH not AT, no victim, punch up, stop if it stops being fun.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1318","cat":"just-a-joke","type":"build","hook":"Build the order to handle a 'just a joke' put-down you saw.","prompt":"Put the steps in order.","pieces":["Notice it was a put-down","Name it: 'not funny'","Check on the kid after","Tell an adult if it keeps going"],"mode":"sequence","key":["Notice it was a put-down","Name it: 'not funny'","Check on the kid after","Tell an adult if it keeps going"],"relearn":"Handle a 'just a joke' put-down: notice, name it, check in, tell if it keeps going.","persona":"any","source":"upstander moves"},
  {"id":"nf-1319","cat":"just-a-joke","type":"build","hook":"Build a list of what 'just a joke' canNOT do.","prompt":"Pick what saying 'just a joke' can never do.","pieces":["Erase the hurt","Make a put-down fair","Decide it for the other kid","Spread unfair ideas safely","Make everyone laugh harder"],"mode":"assemble","key":["Erase the hurt","Make a put-down fair","Decide it for the other kid","Spread unfair ideas safely"],"relearn":"'Just a joke' can't erase hurt, make a put-down fair, or decide it for the other kid.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1320","cat":"just-a-joke","type":"build","hook":"Build the difference between a fair joke and a put-down 'joke'.","prompt":"Pick what makes a joke a FAIR one.","pieces":["Everyone's in on the fun","It needs no victim","It stops when asked","It picks on a smaller kid","It hides a dig as a 'joke'"],"mode":"assemble","key":["Everyone's in on the fun","It needs no victim","It stops when asked"],"relearn":"A fair joke shares the fun, needs no victim, and stops when asked.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1321","cat":"just-a-joke","type":"build","hook":"Build what you can do when YOUR joke landed wrong.","prompt":"Pick the kind moves, not the dodges.","pieces":["Say a real sorry","Ask if they're okay","Drop that joke next time","Say 'can't you take a joke?'","Tell them to toughen up"],"mode":"assemble","key":["Say a real sorry","Ask if they're okay","Drop that joke next time"],"relearn":"When your joke lands wrong: say sorry, check in, and drop it, no dodges.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1322","cat":"just-a-joke","type":"match","hook":"Match the 'just a joke' dodge to the fair line that answers it.","pairs":[{"left":"\"Can't you take a joke?\"","right":"\"I take jokes, not put-downs.\""},{"left":"\"Relax, just kidding.\"","right":"\"It still hurt, please stop.\""},{"left":"\"Everyone laughed.\"","right":"\"Not the kid it was about.\""},{"left":"\"Why so serious?\"","right":"\"That just wasn't kind.\""},{"left":"\"It's only a joke.\"","right":"\"A joke shouldn't hurt.\""}],"relearn":"Every 'just a joke' dodge has a calm line that answers it.","persona":"any","source":"assertiveness"},
  {"id":"nf-1323","cat":"just-a-joke","type":"match","hook":"Match each 'joke' to whether it laughs WITH or puts someone down.","pairs":[{"left":"A pun about the moon","right":"Fun, no victim"},{"left":"\"You're dumb, kidding\"","right":"Put-down in disguise"},{"left":"A silly group game","right":"Laughing together"},{"left":"\"Look at her clothes, ha\"","right":"A dig dressed as a joke"},{"left":"A knock-knock joke","right":"Just for laughs"}],"relearn":"Some 'jokes' laugh with you; others are digs dressed up as jokes.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1324","cat":"just-a-joke","type":"match","hook":"Match the dodge phrase to the trick it's trying to pull.","pairs":[{"left":"\"Just a joke\"","right":"Hide the hurt"},{"left":"\"Can't you take it?\"","right":"Blame the hurt kid"},{"left":"\"Everyone agrees\"","right":"Use the crowd"},{"left":"\"I didn't mean it\"","right":"Skip how it landed"},{"left":"\"Don't be touchy\"","right":"Make you the problem"}],"relearn":"Each 'just a joke' dodge tries a trick; naming the trick beats it.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1325","cat":"just-a-joke","type":"match","hook":"Match the joke moment to the kind next step.","pairs":[{"left":"Your joke made a friend quiet","right":"Check in and say sorry"},{"left":"You hear a group put-down","right":"Say 'not funny'"},{"left":"A kid keeps teasing after 'stop'","right":"Tell a trusted adult"},{"left":"You repeated a hurtful joke","right":"Drop it next time"},{"left":"A friend got teased","right":"Sit with them after"}],"relearn":"Every joke moment has a kind next step you can take.","persona":"any","source":"upstander moves"},
  {"id":"nf-1326","cat":"just-a-joke","type":"match","hook":"Match each 'just a joke' myth to its truth.","pairs":[{"left":"'Just a joke' erases hurt","right":"The hurt still counts"},{"left":"Laugh or you're no fun","right":"You can refuse mean ones"},{"left":"Only the teller decides","right":"The kid it's about has a say"},{"left":"Meaning it kind makes it kind","right":"How it lands matters"},{"left":"A 'joke' put-down is harmless","right":"It can hurt a lot"}],"relearn":"Each 'just a joke' myth has a truth that replaces it.","persona":"any","source":"disparagement humor"},
  {"id":"nf-1327","cat":"just-a-joke","type":"match","hook":"Match the 'joke' to the feeling it can leave behind.","pairs":[{"left":"Mocked in front of class","right":"Embarrassed"},{"left":"Teased about your home","right":"Small"},{"left":"Same dig, every day","right":"Worn down"},{"left":"Left out of the 'fun'","right":"Lonely"},{"left":"A friend stands up for you","right":"Safe"}],"relearn":"Put-down 'jokes' leave real feelings; an ally can leave you feeling safe.","persona":"any","source":"empathy"},
  {"id":"nf-1328","cat":"just-a-joke","type":"match","hook":"Match the joke teller's words to what would make it right.","pairs":[{"left":"\"Just kidding!\"","right":"\"Sorry, that wasn't kind.\""},{"left":"\"You're too sensitive.\"","right":"\"Your feeling counts.\""},{"left":"\"It was funny!\"","right":"\"Not for you, I'll stop.\""},{"left":"\"Everyone says it.\"","right":"\"I won't, it's a put-down.\""},{"left":"\"Toughen up.\"","right":"\"You shouldn't have to.\""}],"relearn":"Each dodge has a kind line that makes the joke right instead.","persona":"any","source":"repair"},
  {"id":"nf-1329","cat":"just-a-joke","type":"match","hook":"Match each 'joke' to the fair next move.","pairs":[{"left":"A clever riddle","right":"Enjoy it"},{"left":"A dig at someone's accent","right":"Refuse it"},{"left":"A goofy story, no victim","right":"Laugh along"},{"left":"\"You throw weak, joking\"","right":"Name the put-down"},{"left":"A funny made-up word","right":"Share the fun"}],"relearn":"Fair jokes are for enjoying; digs dressed as jokes are for refusing.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1350","cat":"my-own-jokes","type":"reflect","hook":"Lensy: before a joke leaves your mouth, who is it for a laugh AT?","prompt":"Take a beat and think.","options":["Nobody, it's just silly","Myself, I'm the goofy one","I'll check who it lands on"],"affirm":"That tiny check, who's it aimed at, is what a kind funny kid does.","relearn":"Checking your own jokes for who they punch at is smart and kind.","persona":"Reyansh","source":"self-awareness"},
  {"id":"nf-1351","cat":"my-own-jokes","type":"reflect","hook":"Lensy: a joke that needs no victim is the cleverest kind. Agree?","prompt":"What do you reckon?","options":["Yes, harder and funnier","No victim needed","I want to try those"],"affirm":"Right, the funniest jokes need nobody to be the punching bag.","relearn":"The funniest jokes need no victim, you don't put someone down to be funny.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1352","cat":"my-own-jokes","type":"reflect","hook":"You repeated a YouTube roast at school and it got quiet. How do you sit with that?","prompt":"Be honest with yourself.","options":["It didn't land like I hoped","Maybe it stung someone","I'll pick a kinder one next time"],"affirm":"Noticing the room go quiet is a clue, and you read it. That's growth.","relearn":"A kid who repeats a hurtful joke can check it and pick a kinder one.","persona":"Reyansh","source":"self-awareness"},
  {"id":"nf-1353","cat":"my-own-jokes","type":"reflect","hook":"Lensy: would your joke still feel funny if it were about YOU instead?","prompt":"A fair test?","options":["Yes, great test","I'd use it","It helps me check"],"affirm":"The would-I-laugh-if-it-were-me test keeps a joke kind.","relearn":"Test a joke by imagining it aimed at you.","persona":"Reyansh","source":"empathy / perspective-taking"},
  {"id":"nf-1354","cat":"my-own-jokes","type":"reflect","hook":"Lensy: punch UP or sideways, never DOWN at a kid with less power. Makes sense?","prompt":"What do you think?","options":["Yes","Never punch down","Good rule to keep"],"affirm":"Punch up or sideways, never down, a joke at the weaker kid is a put-down.","relearn":"Punch up, not down, a joke at someone with less power is a put-down.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1355","cat":"my-own-jokes","type":"reflect","hook":"Your funny voice imitating a classmate's stutter got laughs. How does it sit now?","prompt":"Think it over.","options":["Not great, really","It was at him, not with him","I'll drop that one"],"affirm":"You spotted it was AT him, not with him. That's the kind comedian in you.","relearn":"A joke is laughing WITH someone, not AT how they talk.","persona":"Reyansh","source":"empathy"},
  {"id":"nf-1356","cat":"my-own-jokes","type":"reflect","hook":"Lensy: when a joke lands wrong, checking in beats doubling down. Yes?","prompt":"What feels right?","options":["Yes, check in","Don't double down","I'll go ask if he's okay"],"affirm":"Checking in if a joke hurt is the strong move, not doubling down.","relearn":"If your joke hurt someone, checking in or apologising beats doubling down.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1357","cat":"my-own-jokes","type":"reflect","hook":"Lensy: you can be the funny one AND the kind one at once. Up for it?","prompt":"Your call.","options":["Yes","Funny and kind","That's my goal"],"affirm":"Funny-and-kind is the real skill, and you can be both.","relearn":"The real skill is being funny and kind at the same time.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1358","cat":"my-own-jokes","type":"reflect","hook":"Your prank on the new kid in tuition class flopped. What's the honest read?","prompt":"Sit with it a sec.","options":["He felt singled out","New kids need welcome, not pranks","I'll be the one who's nice to him"],"affirm":"You saw he needed welcome, not a target on his back. Kind catch.","relearn":"Jokes shouldn't make a new or vulnerable kid the punchline.","persona":"Reyansh","source":"empathy"},
  {"id":"nf-1359","cat":"my-own-jokes","type":"reflect","hook":"Lensy: a meme you forwarded poked fun at someone's looks. Worth a rethink?","prompt":"What do you feel?","options":["Yes, looks aren't fair game","I'll not forward those","I'll think before I share"],"affirm":"Looks and skin aren't fair game for a laugh, you read that right.","relearn":"Appearance and skin jabs are put-downs, not jokes, even in a forward.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1360","cat":"my-own-jokes","type":"reflect","hook":"Lensy: if a joke stops being fun for the other kid, it's stopped being a joke. Get it?","prompt":"Does that land?","options":["Yes","Then I stop","I'll watch their face"],"affirm":"When it stops being fun for them, it's stopped being a joke, so you stop.","relearn":"If a joke stops being fun for the other person, it has stopped being a joke.","persona":"any","source":"fun-vs-mean"},
  {"id":"nf-1361","cat":"my-own-jokes","type":"reflect","hook":"You called a boy 'girly' for a laugh and he went still. How do you hold it?","prompt":"Be honest.","options":["Girly isn't an insult","I made him the joke","I'll tell him it was wrong of me"],"affirm":"Girly isn't an insult, and you saw you made him the joke. Brave honesty.","relearn":"Girly isn't an insult, and a gender jab as a joke is still a put-down.","persona":"Reyansh","source":"gender / self-awareness"},
  {"id":"nf-1362","cat":"my-own-jokes","type":"reflect","hook":"Lensy: roasting at home, like teasing your cousin's marks, can sting too. Notice?","prompt":"What do you think?","options":["Yes, family stings too","I'll ease up","Kind even with cousins"],"affirm":"Family roasts sting too, kindness counts even with your own cousins.","relearn":"A put-down joke stings even when it's family, kindness still applies.","persona":"any","source":"empathy"},
  {"id":"nf-1363","cat":"my-own-jokes","type":"reflect","hook":"Lensy: laughing WITH a friend feels different to laughing AT them. Felt it?","prompt":"Your honest sense.","options":["Yes, totally different","With, not at","I'll aim for with"],"affirm":"With-not-at is the whole game, and your gut already knows the difference.","relearn":"A joke is laughing WITH someone, not making them the punchline.","persona":"any","source":"fun-vs-mean"},
  {"id":"nf-1364","cat":"my-own-jokes","type":"reflect","hook":"You stayed up rehearsing a comeback to 'win' tomorrow. What's it really for?","prompt":"Be honest with yourself.","options":["A laugh, but it cuts him","Winning isn't worth wounding","I'll find a comeback that's just funny"],"affirm":"A comeback can be funny without wounding, you don't need a victim to win.","relearn":"You can have a sharp, funny comeback that puts nobody down.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1365","cat":"my-own-jokes","type":"reflect","hook":"Lensy: a joke is only fun if it's fun for the kid it's ABOUT, too. Agree?","prompt":"What do you think?","options":["Yes","Fun for them too","I'll check that"],"affirm":"Only fun if it's fun for them too, that's the test that keeps jokes kind.","relearn":"A joke is only fun if it's fun for the person it's about, too.","persona":"any","source":"fun-vs-mean"},
  {"id":"nf-1366","cat":"my-own-jokes","type":"reflect","hook":"You skipped a mean joke and the moment passed fine. How does that feel?","prompt":"Sit with it.","options":["Lighter, actually","Nobody got hurt","I can do that more"],"affirm":"Skipping the mean one and the room was still fine, that's a quiet win.","relearn":"You can let a hurtful joke go unsaid and lose nothing.","persona":"Reyansh","source":"self-awareness"},
  {"id":"nf-1367","cat":"my-own-jokes","type":"reflect","hook":"Lensy: a kid who repeats a hurtful joke isn't 'bad', they can just check it. Right?","prompt":"How does that sit?","options":["Yes, not bad","Just check and fix","Anyone can learn this"],"affirm":"Not bad at all, repeating a joke just means there's a chance to check it.","relearn":"A kid who repeats a hurtful joke isn't bad, they can check it and repair.","persona":"any","source":"non-shaming"},
  {"id":"nf-1368","cat":"my-own-jokes","type":"reflect","hook":"You aimed a joke at the teacher's helper instead of the bully. Who had less power?","prompt":"Think about it.","options":["The helper did","I punched down","I'll aim it up next time"],"affirm":"You spotted you punched down, and that you can aim up. Sharp self-check.","relearn":"Punch up, not down, a joke at the kid with less power is a put-down.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1369","cat":"my-own-jokes","type":"reflect","hook":"Lensy: 'I was only joking' doesn't undo a hurt you caused. True?","prompt":"What do you feel?","options":["True","The hurt's still real","I'll own it instead"],"affirm":"Only-joking doesn't undo the hurt, owning it does. You get that.","relearn":"Saying it was just a joke doesn't erase the hurt, the harm is real.","persona":"Reyansh","source":"just-a-joke"},
  {"id":"nf-1370","cat":"my-own-jokes","type":"reflect","hook":"Lensy: making yourself the goofy hero of the story still gets the laugh. Try it?","prompt":"Up for it?","options":["Yes, self-jokes are fun","No one gets hurt","I've loads of those"],"affirm":"Self-jokes get the laugh and hurt nobody, a kind comedian's best trick.","relearn":"You can be the funny one by joking about yourself, no victim needed.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1371","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"If they don't laugh, they just can't take a joke.\"","myth":{"un":"If someone doesn't laugh, they just can't take a joke.","re":"Not laughing means they noticed it wasn't kind, and that's fair.","why":"A joke is only funny if it's fun for the person it's about, too."},"relearn":"Not laughing means they noticed it wasn't kind, not that they're no fun.","persona":"Reyansh","source":"fun-vs-mean"},
  {"id":"nf-1372","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"If I explain that it was a joke, they'll stop being upset.\"","myth":{"un":"Explaining 'it was just a joke' will fix how they feel.","re":"Explaining the joke doesn't undo the sting; only listening and repair does.","why":"They need to feel heard, not lectured on why it was meant to be funny."},"relearn":"Explaining a joke won't fix the hurt; listen and repair instead.","persona":"Reyansh","source":"repair / values"},
  {"id":"nf-1373","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"You have to roast someone to get a real laugh.\"","myth":{"un":"You have to put someone down to be really funny.","re":"The funniest jokes need no victim at all.","why":"Wit beats cruelty, and a kind joke ages far better."},"relearn":"You can be hilarious without putting anyone down.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1374","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"A joke about how someone looks is harmless fun.\"","myth":{"un":"Joking about how a kid looks or their skin is harmless fun.","re":"Looks and skin jabs are put-downs, even said with a grin.","why":"They sting the person, and laughing doesn't unsting them."},"relearn":"Appearance and skin jabs are put-downs, not harmless jokes.","persona":"any","source":"gender / inclusive humor"},
  {"id":"nf-1375","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"Calling a boy 'girly' is just a funny burn.\"","myth":{"un":"Calling a boy 'girly' is just a funny burn.","re":"Girly isn't an insult, so it can't be a fair burn.","why":"A boy can like colours or stories and be completely fine as he is."},"relearn":"Girly isn't an insult, and a gender jab as a joke is still a put-down.","persona":"Reyansh","source":"gender"},
  {"id":"nf-1376","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"If I didn't mean it, my joke didn't really hurt.\"","myth":{"un":"If I didn't mean to hurt, my joke didn't really hurt.","re":"How a joke lands is the test, not whether you meant it.","why":"Hurt counts even when it was unmeant, the feeling is real."},"relearn":"How a joke lands is the test, not whether you meant it.","persona":"Reyansh","source":"how-it-feels / impact over intent"},
  {"id":"nf-1377","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"Once a joke's out, you can't take it back, so why bother?\"","myth":{"un":"Once a joke's out you can't take it back, so why bother.","re":"You can always repair, a check-in and sorry mends a lot.","why":"Owning it tells the other kid the hurt mattered to you."},"relearn":"You can repair a joke that hurt, a check-in and sorry mends a lot.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1378","cat":"my-own-jokes","type":"strike-rewrite","hook":"\"Joking about a kid behind his back is fine, he never hears it.\"","myth":{"un":"Joking about a kid behind his back is fine, he never hears it.","re":"Behind-the-back jokes still reach him and still hurt.","why":"Words travel in a class, and being the target stings either way."},"relearn":"A behind-the-back put-down still hurts the kid it's about.","persona":"Reyansh","source":"how-it-feels"},
  {"id":"nf-1379","cat":"my-own-jokes","type":"branch","hook":"You've a joke that'd get a huge laugh, but it's aimed at a kid in your row.","options":[{"text":"Swap it to a silly self-joke or a daft topic","consequence":"You still get the laugh and nobody's hurt.","outcome":"kind","best":true},{"text":"Tell it anyway for the big laugh","consequence":"A laugh at his cost isn't worth the sting it leaves."}],"debrief":"A laugh that costs someone else isn't worth it, redirect the joke.","relearn":"Aim jokes at ideas or yourself, not at a person.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1380","cat":"my-own-jokes","type":"branch","hook":"Your group dares you to mock the quiet kid's lunch for a laugh.","options":[{"text":"Say \"nah, let's not, that's not cool\"","consequence":"You hold your line and good friends respect it.","outcome":"values","best":true},{"text":"Do it so they don't call you boring","consequence":"You don't have to be unkind to keep your friends."}],"debrief":"You can resist the push to get laughs by hurting someone.","relearn":"You can say no to making a kid the joke, even when friends push.","persona":"Reyansh","source":"peer pressure / values"},
  {"id":"nf-1381","cat":"my-own-jokes","type":"branch","hook":"Your joke calling a girl 'bossy' for leading the game fell flat.","options":[{"text":"Say \"sorry, leading isn't bossy, that was unfair\"","consequence":"She feels seen and you fix it on the spot.","outcome":"repair","best":true},{"text":"Add \"can't you take a joke?\"","consequence":"That dodges the hurt and blames her."}],"debrief":"Bossy for leading is a put-down, so own it and repair.","relearn":"Bossy for leading is a gender put-down; owning it beats blaming her.","persona":"Reyansh","source":"gender / repair"},
  {"id":"nf-1382","cat":"my-own-jokes","type":"branch","hook":"Mid-joke you see the kid it's about isn't laughing; his face dropped.","options":[{"text":"Stop and check \"that wasn't fair of me, you okay?\"","consequence":"He relaxes, the joke ended when it hurt.","outcome":"kind","best":true},{"text":"Push to the punchline anyway","consequence":"Once it's no fun for him, it's stopped being a joke."}],"debrief":"When a joke stops being fun for them, stop.","relearn":"If a joke stops being fun for them, it has stopped being a joke.","persona":"Reyansh","source":"fun-vs-mean"},
  {"id":"nf-1383","cat":"my-own-jokes","type":"branch","hook":"You're about to forward a meme poking fun at a classmate's dark skin.","options":[{"text":"Don't send it, type something kind instead","consequence":"Nobody's looks become a group joke today.","outcome":"kind","best":true},{"text":"Forward it, it's just a meme","consequence":"A skin jab is a put-down; a meme can't make it kind."}],"debrief":"Skin and looks jabs are put-downs, even as a forward.","relearn":"Skin and looks jabs are put-downs, not jokes, even in a forward.","persona":"Reyansh","source":"gender / inclusive humor"},
  {"id":"nf-1384","cat":"my-own-jokes","type":"branch","hook":"Your accent impression got laughs, but now the kid won't look at you.","options":[{"text":"Go over and say \"that wasn't kind, I'm sorry\"","consequence":"He feels you saw it; the rift starts to heal.","outcome":"repair","best":true},{"text":"Decide he's just being sensitive","consequence":"That blames him for a hurt you caused."}],"debrief":"How it landed is the test, so own it and check in.","relearn":"How a joke lands is the test; owning it beats calling him sensitive.","persona":"Reyansh","source":"repair / how-it-feels"},
  {"id":"nf-1385","cat":"my-own-jokes","type":"branch","hook":"In the group chat, friends roast one kid and tag you to join in.","options":[{"text":"Reply \"easy, that's enough on him\" and switch topic","consequence":"The pile-on cools and the kid isn't alone.","outcome":"values","best":true},{"text":"Pile on so you're not left out","consequence":"A pile-on on one kid wears him down."}],"debrief":"You can steer a roast off a single kid and still be fun.","relearn":"You can stop a pile-on and redirect the joke, no victim needed.","persona":"Reyansh","source":"inclusive humor / be-an-ally"},
  {"id":"nf-1386","cat":"my-own-jokes","type":"branch","hook":"Your joke about your friend's new haircut clearly stung him.","options":[{"text":"Say \"sorry, unkind of me, your hair's actually cool\"","consequence":"He grins, the sting is gone, still mates.","outcome":"repair","best":true},{"text":"Say \"relax, it was just a joke\"","consequence":"Just-a-joke doesn't undo the hurt on his face."}],"debrief":"Just-a-joke doesn't erase a hurt; a quick sorry mends it.","relearn":"Just a joke doesn't erase the hurt; a quick sorry mends it.","persona":"Reyansh","source":"just-a-joke / repair"},
  {"id":"nf-1387","cat":"my-own-jokes","type":"branch","hook":"A funny line pops up, mocking the kid who cried in class.","options":[{"text":"Keep it to yourself, he's had a hard day","consequence":"You spare a kid who's already low, that's strength.","outcome":"kind","best":true},{"text":"Say it, crying's funny","consequence":"Teasing a boy for crying is a put-down."}],"debrief":"Everyone cries, so a joke about it is a put-down; let it go.","relearn":"Everyone cries; teasing a boy for crying is a put-down, not a joke.","persona":"Reyansh","source":"gender / inclusive humor"},
  {"id":"nf-1388","cat":"my-own-jokes","type":"branch","hook":"The whole class is watching and you've a joke ready, aimed at one kid.","options":[{"text":"Switch it to a silly self-joke or a fun topic","consequence":"You get the laugh and keep everyone safe.","outcome":"kind","best":true},{"text":"Land it at the kid's expense","consequence":"Power over a crowd is a chance to be kind, not cruel."}],"debrief":"With the crowd watching, use it to include, not to wound.","relearn":"With everyone watching, pick the joke that hurts no one.","persona":"Reyansh","source":"inclusive humor / consolidation"},
  {"id":"nf-1389","cat":"my-own-jokes","type":"branch","hook":"You realise your favourite joke is really at your little sister's expense.","options":[{"text":"Drop it, tell her the funny bit's actually you","consequence":"She laughs along, the joke loses its target.","outcome":"kind","best":true},{"text":"Keep it, she's only little","consequence":"Punching down at a smaller kid is a put-down."}],"debrief":"Punch up, not down; swap it for a kinder joke.","relearn":"Punch up, not down; a joke at someone with less power is a put-down.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1390","cat":"my-own-jokes","type":"branch","hook":"Picking a talent-show joke; one's about a boy who likes pink.","options":[{"text":"Pick a silly joke with no kid as the butt","consequence":"The crowd laughs and no one's singled out.","outcome":"kind","best":true},{"text":"Use the one about the boy and pink","consequence":"A boy liking pink is fine; mocking it is a put-down."}],"debrief":"A boy can like pink and be fine, so pick a no-victim joke.","relearn":"A boy can like pink and be fine; mocking it is a put-down, not a joke.","persona":"Reyansh","source":"gender / inclusive humor"},
  {"id":"nf-1391","cat":"my-own-jokes","type":"role-play","hook":"You made a joke that hurt and want to set it right.","setup":"Make it right. Say:","yourLine":[{"text":"\"That came out unkind, I'm sorry.\"","best":true},{"text":"\"You're way too sensitive.\""}],"relearn":"A clean apology beats blaming the person you hurt.","persona":"Reyansh","source":"repair / voice"},
  {"id":"nf-1392","cat":"my-own-jokes","type":"role-play","hook":"Friends want you to roast the new kid. Say your line.","setup":"Hold your line. Say:","yourLine":[{"text":"\"Nah, not him, let's joke about something else.\"","best":true},{"text":"\"Okay, what's funny about him?\""}],"relearn":"You can say no to making a kid the joke and steer it elsewhere.","persona":"Reyansh","source":"peer pressure / voice"},
  {"id":"nf-1393","cat":"my-own-jokes","type":"role-play","hook":"Your joke about a girl 'throwing like a girl' fell flat. Fix it out loud.","setup":"Own it. Say:","yourLine":[{"text":"\"Sorry, that's not even true, you've a great arm.\"","best":true},{"text":"\"It was just a joke, chill.\""}],"relearn":"Like a girl isn't an insult, owning the jab beats brushing it off.","persona":"Reyansh","source":"gender / repair"},
  {"id":"nf-1394","cat":"my-own-jokes","type":"role-play","hook":"A kid asks you to stop the joke you're doing about him. Say your line.","setup":"Respond kindly. Say:","yourLine":[{"text":"\"Done, sorry, I'll stop.\"","best":true},{"text":"\"Can't you take a joke?\""}],"relearn":"When someone says stop, a real joke stops, no can't-you-take-it dodge.","persona":"Reyansh","source":"fun-vs-mean / voice"},
  {"id":"nf-1395","cat":"my-own-jokes","type":"role-play","hook":"You catch yourself before a cruel punchline. Pick a kinder line.","setup":"Redirect the joke. Say:","yourLine":[{"text":"\"Actually the funniest part is how I tripped over it.\"","best":true},{"text":"\"…and that's why he's such a loser.\""}],"relearn":"You can swap a cruel punchline for a self-joke and still get the laugh.","persona":"Reyansh","source":"inclusive humor / voice"},
  {"id":"nf-1396","cat":"my-own-jokes","type":"role-play","hook":"Your friend looks hurt after your joke. Check in out loud.","setup":"Check in. Say:","yourLine":[{"text":"\"Hey, did that land wrong? I didn't mean to sting you.\"","best":true},{"text":"\"Why're you making it a big deal?\""}],"relearn":"Checking in if a joke stung beats making it the other kid's problem.","persona":"Reyansh","source":"repair / voice"},
  {"id":"nf-1397","cat":"my-own-jokes","type":"role-play","hook":"Someone laughs at a kid's stutter and looks to you to join. Say your line.","setup":"Don't pile on. Say:","yourLine":[{"text":"\"That's not funny, leave it.\"","best":true},{"text":"\"Yeah, do it again!\""}],"relearn":"You can refuse to pile on, even two words like that's not funny works.","persona":"Reyansh","source":"inclusive humor / voice"},
  {"id":"nf-1398","cat":"my-own-jokes","type":"sort","hook":"Sort: does this joke punch UP/sideways, or DOWN?","items":[{"id":"a","text":"Teasing your own goofy dance"},{"id":"b","text":"Mocking the smallest kid's voice"},{"id":"c","text":"A joke about the popular captain"},{"id":"d","text":"Laughing at the new kid's clothes"},{"id":"e","text":"Ribbing your mate, both laughing"},{"id":"f","text":"Mimicking a shy kid for the crowd"}],"bins":[{"id":"ok","label":"Up or sideways","valence":"pos"},{"id":"down","label":"Punches down","valence":"neg"}],"key":{"a":"ok","b":"down","c":"ok","d":"down","e":"ok","f":"down"},"relearn":"Punch up or sideways, never down at the smaller, newer or shyer kid.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1399","cat":"my-own-jokes","type":"sort","hook":"Sort: kind comedian move, or a careful-rethink move?","items":[{"id":"a","text":"Joking about yourself"},{"id":"b","text":"Saying \"can't you take a joke?\""},{"id":"c","text":"Stopping when a kid says stop"},{"id":"d","text":"Doubling down after it stings"},{"id":"e","text":"Checking in if a joke hurt"},{"id":"f","text":"Forwarding a looks-meme"}],"bins":[{"id":"kind","label":"Kind comedian","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"uhoh"}],"key":{"a":"kind","b":"rethink","c":"kind","d":"rethink","e":"kind","f":"rethink"},"relearn":"Self-jokes, stopping and checking in are kind, dodges and pile-ons need a rethink.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1400","cat":"my-own-jokes","type":"sort","hook":"Sort: is this a joke WITH someone, or AT them?","items":[{"id":"a","text":"You and your friend both laughing at a shared blunder"},{"id":"b","text":"Mocking a kid's lunch box"},{"id":"c","text":"A team chant everyone joins"},{"id":"d","text":"A jab at a kid's marks"},{"id":"e","text":"Giggling together at a silly typo"},{"id":"f","text":"Imitating a kid's limp"}],"bins":[{"id":"with","label":"Laughing with","valence":"pos"},{"id":"at","label":"Laughing at","valence":"neg"}],"key":{"a":"with","b":"at","c":"with","d":"at","e":"with","f":"at"},"relearn":"A joke is laughing WITH someone, not making them the punchline.","persona":"any","source":"fun-vs-mean"},
  {"id":"nf-1401","cat":"my-own-jokes","type":"sort","hook":"Sort: which jokes need a victim, and which need none?","items":[{"id":"a","text":"A clever pun"},{"id":"b","text":"Roasting a kid's accent"},{"id":"c","text":"A funny story about your dog"},{"id":"d","text":"Mocking a girl for being 'bossy'"},{"id":"e","text":"A wordplay joke"},{"id":"f","text":"A jab at a boy who cried"}],"bins":[{"id":"none","label":"No victim","valence":"pos"},{"id":"victim","label":"Needs a victim","valence":"neg"}],"key":{"a":"none","b":"victim","c":"none","d":"victim","e":"none","f":"victim"},"relearn":"The funniest jokes, puns and wordplay, need no victim at all.","persona":"any","source":"inclusive humor"},
  {"id":"nf-1402","cat":"my-own-jokes","type":"sort","hook":"Sort: after a joke lands wrong, repair move or dodge?","items":[{"id":"a","text":"\"I'm sorry, that was unkind.\""},{"id":"b","text":"\"You're too sensitive.\""},{"id":"c","text":"\"Are you okay? I'll stop.\""},{"id":"d","text":"\"It was only a joke, relax.\""},{"id":"e","text":"\"My bad, I'll not say that again.\""},{"id":"f","text":"\"Can't you take a joke?\""}],"bins":[{"id":"repair","label":"Repair","valence":"tell"},{"id":"dodge","label":"Dodge","valence":"neg"}],"key":{"a":"repair","b":"dodge","c":"repair","d":"dodge","e":"repair","f":"dodge"},"relearn":"Sorry and check-ins repair, sensitive and can't-take-a-joke are dodges.","persona":"any","source":"repair / just-a-joke"},
  {"id":"nf-1403","cat":"my-own-jokes","type":"sort","hook":"Sort: gender put-down dressed as a joke, or a fair, kind joke?","items":[{"id":"a","text":"A silly knock-knock joke"},{"id":"b","text":"\"You throw like a girl\""},{"id":"c","text":"A funny story you star in"},{"id":"d","text":"\"Pink is for girls, ha\""},{"id":"e","text":"A daft animal pun"},{"id":"f","text":"\"Boys don't cry, baby\""}],"bins":[{"id":"fair","label":"Fair joke","valence":"pos"},{"id":"putdown","label":"Gender put-down","valence":"neg"}],"key":{"a":"fair","b":"putdown","c":"fair","d":"putdown","e":"fair","f":"putdown"},"relearn":"Gender isn't an insult, like a girl, pink-is-for-girls and boys-don't-cry are put-downs.","persona":"any","source":"gender"},
  {"id":"nf-1404","cat":"my-own-jokes","type":"build","hook":"Build a 'check before you post' code for online jokes.","prompt":"Pick the steps.","pieces":["picture the person reading it","ask: would I say this to their face","wait if you're angry","delete it if it could wound","post it fast before you overthink"],"mode":"assemble","key":["picture the person reading it","ask: would I say this to their face","wait if you're angry","delete it if it could wound"],"relearn":"Before posting a joke: picture them, would-I-say-it-to-their-face, wait, delete if it wounds.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1405","cat":"my-own-jokes","type":"build","hook":"Build a quick joke-check to run before you say it.","prompt":"Pick the checks.","pieces":["who is it aimed at?","would I laugh if it were me?","does it punch down?","is it fun for them too?","does it need a victim to work?"],"mode":"assemble","key":["who is it aimed at?","would I laugh if it were me?","does it punch down?","is it fun for them too?"],"relearn":"Before a joke: who's it aimed at, would I laugh, does it punch down, fun for them?","persona":"Reyansh","source":"self-awareness"},
  {"id":"nf-1406","cat":"my-own-jokes","type":"build","hook":"Build the steps to repair a joke that hurt your friend.","prompt":"Put the repair in order.","pieces":["notice his face dropped","stop the joke","say a clear sorry","check he's okay now","tell him to toughen up"],"mode":"sequence","key":["notice his face dropped","stop the joke","say a clear sorry","check he's okay now"],"relearn":"Repair a joke: notice, stop, a clear sorry, then check he's okay.","persona":"Reyansh","source":"repair"},
  {"id":"nf-1407","cat":"my-own-jokes","type":"build","hook":"Build a set of jokes that need no victim at all.","prompt":"Pick the no-victim jokes.","pieces":["a clever pun","a silly story about yourself","a daft animal riddle","a jab at a kid's looks","a funny wordplay"],"mode":"assemble","key":["a clever pun","a silly story about yourself","a daft animal riddle","a funny wordplay"],"relearn":"Puns, self-stories, riddles and wordplay are funny with no victim.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1408","cat":"my-own-jokes","type":"build","hook":"Build the 'aim it kindly' rule for where a joke can point.","prompt":"Pick the safe places to aim.","pieces":["at yourself","sideways at a friend who's laughing","at a silly idea or thing","down at a smaller kid","at how someone looks"],"mode":"assemble","key":["at yourself","sideways at a friend who's laughing","at a silly idea or thing"],"relearn":"Aim a joke at yourself, sideways, or at a silly thing, never down or at looks.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1409","cat":"my-own-jokes","type":"build","hook":"Build what to do the moment a kid says 'stop' to your joke.","prompt":"Put it in order.","pieces":["stop right away","say sorry","pick a kinder joke","keep going for the laugh","check he's alright"],"mode":"sequence","key":["stop right away","say sorry","check he's alright","pick a kinder joke"],"relearn":"When a kid says stop: stop, say sorry, check he's alright, pick a kinder joke.","persona":"Reyansh","source":"fun-vs-mean / repair"},
  {"id":"nf-1410","cat":"my-own-jokes","type":"build","hook":"Build a 'turn a roast into a self-joke' move.","prompt":"Pick the steps.","pieces":["catch the cruel punchline coming","swap the target to yourself","keep the silly bit","add a daft twist about you","aim it at the kid instead"],"mode":"sequence","key":["catch the cruel punchline coming","swap the target to yourself","keep the silly bit","add a daft twist about you"],"relearn":"Turn a roast kind: catch it, swap the target to you, keep the silly, add a twist.","persona":"Reyansh","source":"inclusive humor"},
  {"id":"nf-1411","cat":"my-own-jokes","type":"match","hook":"Match each joke move to what it really is.","pairs":[{"left":"A pun the class loves","right":"Joke with no victim"},{"left":"\"Can't you take a joke?\"","right":"A dodge that blames them"},{"left":"\"Sorry, that was unkind\"","right":"A repair move"},{"left":"Mocking a smaller kid","right":"Punching down"},{"left":"A silly story about yourself","right":"A self-joke"}],"persona":"any","source":"inclusive humor","relearn":"Each joke move is really a victim-free joke, a dodge, a repair, punching down, or a self-joke."},
  {"id":"nf-1412","cat":"my-own-jokes","type":"match","hook":"Match each joke to where it's aimed.","pairs":[{"left":"Laughing at your own trip","right":"Aimed at yourself"},{"left":"Ribbing a friend who's laughing too","right":"Aimed sideways"},{"left":"Mocking the new kid","right":"Aimed down"},{"left":"A daft riddle","right":"Aimed at a silly idea"},{"left":"A jab at a boy who cried","right":"A gender put-down"}],"persona":"any","source":"inclusive humor","relearn":"A joke can be aimed at yourself, sideways, down, at an idea, or as a put-down."},
  {"id":"nf-1413","cat":"my-own-jokes","type":"match","hook":"Match the line to what it does after a joke lands wrong.","pairs":[{"left":"\"I'm sorry, my bad\"","right":"Owns the hurt"},{"left":"\"You're too sensitive\"","right":"Blames the other kid"},{"left":"\"Are you okay?\"","right":"Checks in"},{"left":"\"It was just a joke\"","right":"Brushes off the hurt"},{"left":"\"I'll not say that again\"","right":"Promises to do better"}],"persona":"any","source":"repair / just-a-joke","relearn":"After a joke lands wrong, you can own it and check in, or brush it off and blame."},
  {"id":"nf-1414","cat":"my-own-jokes","type":"match","hook":"Match each saying to the truth that replaces it.","pairs":[{"left":"\"You have to roast to be funny\"","right":"The funniest jokes need no victim"},{"left":"\"Like a girl is a burn\"","right":"Gender isn't an insult"},{"left":"\"Sorry is weak\"","right":"Owning it is strong"},{"left":"\"I didn't mean it, so it's fine\"","right":"How it lands is the test"},{"left":"\"Punch down for the laugh\"","right":"Punch up, not down"}],"persona":"any","source":"inclusive humor","relearn":"Each saying has a kinder truth: no victim needed, owning it is strong"},
  {"id":"nf-1415","cat":"my-own-jokes","type":"match","hook":"Match each joke check-question to why it helps.","pairs":[{"left":"Who is it aimed at?","right":"Spots a target"},{"left":"Would I laugh if it were me?","right":"Tests fairness"},{"left":"Is it fun for them too?","right":"Keeps it kind"},{"left":"Does it punch down?","right":"Catches a put-down"},{"left":"Does it need a victim?","right":"Finds a kinder joke"}],"persona":"Reyansh","source":"self-awareness","relearn":"Joke-check questions spot the target, test fairness, and find a kinder joke."},
  {"id":"nf-1416","cat":"my-own-jokes","type":"match","hook":"Match each joke to the kind-comedian rule it follows.","pairs":[{"left":"Joking about your own goof","right":"Joke with, not at"},{"left":"Stopping when she says stop","right":"Stop if it hurts"},{"left":"Aiming up at the popular captain","right":"Punch up, not down"},{"left":"Saying sorry when it stung","right":"Repair if it lands wrong"},{"left":"A pun about the weather","right":"No victim needed"}],"persona":"Reyansh","source":"inclusive humor","relearn":"Kind-comedian rules: joke with not at, stop if it hurts, punch up, repair."},
  {"id":"nf-1417","cat":"my-own-jokes","type":"match","hook":"Match each tricky line to what it's really doing.","pairs":[{"left":"\"It's just banter\"","right":"Excusing a put-down"},{"left":"\"Everyone roasts each other\"","right":"Treating cruelty as normal"},{"left":"\"He started it\"","right":"Passing the blame"},{"left":"\"I was only joking\"","right":"Ignoring the hurt"},{"left":"\"That's not kind, stop\"","right":"Calling it for real"}],"persona":"any","source":"just-a-joke","relearn":"'Just banter' and 'only joking' often excuse a put-down or ignore the hurt."},
  {"id":"nf-1418","cat":"my-own-jokes","type":"match","hook":"Match each joke spot to whether it's still kind there.","pairs":[{"left":"At home, teasing a cousin's marks","right":"Still stings"},{"left":"On the class WhatsApp group","right":"Words travel and stay"},{"left":"To a friend's face, both laughing","right":"Fun for both"},{"left":"Behind a kid's back","right":"Still hurts him"},{"left":"A self-joke on stage","right":"Safe and silly"}],"persona":"any","source":"how-it-feels","relearn":"The same joke can be fun for both or still sting depending on where and at whom."},
];

